/* 平成15年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h15.committeeSessions.push(...[{"id":"h15-20030120-7","meetingId":"h15-cm01","date":"2003年1月20日","dateIso":"2003-01-20","committee":"厚生委員会","time":"午後１時０４分～午前３時１６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を8件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"築舘委員","kind":"質問","question":"ふれあいサポート活動計画ということで、従来からのものをさらに充実させようということだと思いますけれども、民生委員の方が７地区だったのを１３地区に分けたということで、かなり地域に密着をさせたということがあると思うんです。場所的なことも考えてみていただければというのを前々から思っていたので、その点の社会福祉協議会との連携ということの部分をお聞きしたいと思います。","respondent":"日下部障害者福祉課長","answer":"そういった点で、場所の問題ですけれども、できるだけ駅に近いということも含めまして、大井の共同ビルのほうに移転したわけですけれども、移転してからまだそんなに年数が経っていないということもありまして。","id":"exchange-001"},{"speaker":"築舘委員","kind":"質問・要望","question":"その場合に、その地域に必ずしも施設が一つずつあるというわけでもありませんので、そこの兼ね合いを今後、福栄会とか、それぞれが担当して、いろいろな形で活動はしているわけですけれども、いざ地域となると、もう少し不明確な部分も出てくるのではないか。そこの点に関してはどういうふうにお考えかというのをお聞かせいただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"地区のふれあいサポート活動会議には在宅介護支援センターの職員のスタッフもこの中に参加をしていただくというような仕組みにもなっておりますし、その辺は十分全体のバランスがとれた対応ができるのではないかと考えております。","id":"exchange-002"},{"speaker":"築舘委員","kind":"質問・要望","question":"その辺は地区によってアンバランスにならないように、うまく配分をしていただきたいと考えています。それから、ボランティアのほうですけれども、その後、社会福祉協議会とか、いろいろな形でのボランティアの募集とか、そういう形になっていると思うんですが、その後はどんな状況か、ちょっとお聞かせいただければと思います。","respondent":"高橋福祉事業部副参事","answer":"ボランティアの状況ですが、今、働き手のところでは、５０歳代、６０歳代、７０歳代の方が６７％ということで、元気老人の方が働き手としてやっている部分があります。","id":"exchange-003"},{"speaker":"築舘委員","kind":"意見","question":"ボランティアの方もそういう形でやりたいという方がいても、その辺の、何をやるのかという部分の明確に指示も出してあげたりとか、また、そういう余地をどんどん伸ばしてあげるというようなことも今後とも地域に関連をしてお願いをしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"今後のスケジュールのところで、３月のときに計画案をまとめるということになっております。今日は大ざっぱな内容ですけれども、もうちょっとまとまった内容がどういうふうな感じで議会のほうに説明されるのか、そこのところをお願いします。","respondent":"日下部障害者福祉課長","answer":"そういった意味で、多少時間的な関係もありますけれども、年度が明けてから改めて最終的な中身については厚生委員会のほうに詳しくご説明をするような形にしていきたいというふうに考えております。","id":"exchange-005"},{"speaker":"須藤委員","kind":"質問","question":"これを見ていくと、高齢者福祉、あるいは障害者福祉というのが主になってきているのではないかなと思うんですけれども、その辺の考え方はどういうふうに捉えるのか。ですから、１３地区に、いわゆる行政がこの絵を落とすのではなくて、こういう考え方なので、各地区はどうなんだという声を聞くような状況がとれるのかどうか。","respondent":"日下部障害者福祉課長","answer":"３点のご質問をいただきました。最後のほうからまいりますけれども、今委員のほうからご指摘がございましたが、１３地区、それぞれ地域の有り様も違うと。これはまさしくそのとおりだというふうに私どもも思っております。","id":"exchange-006"},{"speaker":"須藤委員","kind":"意見","question":"今話の出た、町会などでいろいろな仕事をお願いしてきて、コミュニティをつくっていくのはいいことだと思うんですけれども、町会の方々も、若い人たちは共働きで、両方とも仕事に出ているとか、いろいろな状況が、今までの町会の有り様と変わってきているんです。よろしくお願いします。行政自体がいろいろ行革をやってきて、それなりの職員減をしたりなんかしてきている。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"宮崎委員","kind":"意見","question":"今の名簿の件ですけれども、どういうふうな内容でつかんでおられるのか。区のほうがどういうふうに名簿の作成に係わっているのか、そこのところはどういうふうになっているのか、説明を願いたいと思います。","respondent":"日下部障害者福祉課長","answer":"名簿につきましては、基本的には、例えば今回、３年に一遍のひとりぐらしの高齢者、高齢世帯の調査を実施いたしました。","id":"exchange-008"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/749973?Template=document&Id=3040#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":14887,"voices":31}},{"id":"h15-20030120-8","meetingId":"h15-cm01","date":"2003年1月20日","dateIso":"2003-01-20","committee":"建設委員会","time":"午後１時０４分～午後４時４６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"きれいなカラーのコピーの冊子をいただいて、５・６丁目が載っていないということ自体がどういうことなのか。被害の大きさと関連する、その辺をまずお伺いしたいと思います。","respondent":"矢部下水道河川課長","answer":"１点目の、５・６丁目の被害が大きいことに関して、区としてどういうふうに考えているかという点ですが、私どものほうでもその辺は認識しております。そういうこともありまして、下水道局のほうには再三にわたり要望をしていると。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区長のほうから都に要請がいっているということでは、一つは請願者の要望が取り上げられていくということだと思うんですけれども、原因のところでは、このところの集中豪雨が多くなっている中でも、立会川幹線の能力不足というところでは、第二立会川幹線が一日も早く完成するのと、あと、ここの地域が上流部に関係しているということでは、行きのバスの中でも、中流部のところは取りかかったけれども。","respondent":"矢部下水道河川課長","answer":"１点目の、早急に第二立会川幹線の上流部の着工を要望してほしいということにつきましては、私どものほうでも東京都のほうにお願いしていきたいというふうに考えております。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区のできること、今日も横断グレーチング枡の問題とかありましたけれども、さっきのご答弁の中で、浸透枡のところで、今後積極的に行っていくということで、去年、上山議員が浸透枡のことなどを質問をしたときに、総合対策の中で計画的にやっていくというのがあったんですが、その辺がこの地域の具体的な計画があるのかどうか、ありとあらゆること、できることは何でもやっていただきたいなと思うんですが。","respondent":"矢部下水道河川課長","answer":"もう一つは、道路の改修工事等と併せてやっていく。浸透枡だけを設置するというのは非効率な面もありますので、道路工事等と連携をしながら浸透枡というふうな形での設置になろうかと思います。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区でいただいた、浸透枡の設置の状況の図を見せていただいたら、今日伺った地域にはほとんど浸透枡が入っていないという状況で、区ですぐできる、予算はかかりますけれども、いつ雨が降るかわからないし、災害はなかなか予測は難しいと思いますけれども、既に被害があって、被害の面では明らかになっているというところでは。","respondent":"岩田管理工事課長","answer":"ご指摘のように、雨水浸透枡は、区の総合実施計画の中で、道路、公園、公共施設については、真っ先に率先して設置をしていくという計画になっております。そこの中でも一番進んでいるのが道路浸透枡の設置でございまして、昭和５０年代からやり始めております。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後ですけれども、雨水調整池の問題で、今日公園のところを見せていただきましたけれども、この辺の場所がどうなのかなと思って、今日はあそこを見せていただいたんですけれども、ほかの地域で水をのみ込む地域があるのかどうか、どの程度の効果があるのか、そのあたりをお聞かせいただきたいと思います。","respondent":"矢部下水道河川課長","answer":"先ほどちょっと私も申し上げましたが、東京都の考え方としますと、第二立会川幹線の中流部が始まったところですので、財政問題等も含めて、その辺の制約の中で今総合的に検討をしてもらっているというふうに判断しております。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"さっき一つ漏れちゃったのが、中流部の計画をやってみて、その効果を見て上流部を検討していくということですけれども、その辺の上流部についての効果はどのように検討をされているのか、どの程度考えられているのか、お伺いしたいと思います。","respondent":"矢部下水道河川課長","answer":"基本的には雨水流出計数は、現在の立会川幹線は５０ミリ、５０％の能力しかないと言われておりますので、それに対して５０ミリの８０％、現在の下水道が現時点で目指しております治水安全度までは高まるものと考えております。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"それは当然ですよね。地下に貯留できる槽をつくるわけですから、当然高まるんだと思うんですけれども、都の言う暫定貯留の効果を見て上流部というのは、効果を見てというよりも、財政上の問題なのかどうか。これをやれば効果は出ると思うんです。もう１点は、荏原町公園は２,０００ｔぐらいとおっしゃいましたけれども、平米数に掛けるとこの程度のものしかできませんよという何か基準があるのかどうか。","respondent":"矢部下水道河川課長","answer":"ですから、上流部がやれば、それだけ効果がさらに出るというのは分かっている中で、東京都は財政状況ももちろんありますでしょうけれども、皆さんのこういう要望等を根気よく東京都に説明をして、なるべく早く実現できるように、品川区としても努力していくです。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問・要望","question":"ただ、さっき話に出た、第一国道が高いところにあって、両側になだらかに下っている感じになるんでしょうか、原っぱ公園からその先の荏原町公園あたりまで延ばすとか、実際にどこまでできるかわかりませんけれども、今計画をしている第二立会川幹線のすべてを完成させるというのは難しいということであれば、せめてその先を延ばすような要請とか、この辺は十分できるような気がするんですけれども。","respondent":"矢部下水道河川課長","answer":"ただし、土地でどのぐらいの深さまで掘削できるかとか、それをやれば、施工方法とか、住民との関係、その他で制約があるかもしれないですけれども、基本的に言えば、そこで１０ｍを超すような規模のものをつくると、ちょっとというような、そういうような価格的なものがあります。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"ということであれば、例えばこの間の豪雨の状況で、実際に降った雨との関係が、中延５・６丁目の周辺に集中をする雨水量といいますか、もしあそこにつくるとすれば、そこまで計算として出して、そういう設定をするということでしょうか。","respondent":"矢部下水道河川課長","answer":"本来的にはそういう形になると思います。ただし、現状から言いますと、入れ物の大きさが違いますので、その辺はうまく整合できるかわかりませんけれども、基本的にはそれが本筋だと思います。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"質問ですが、第二立会川幹線の中流部分が、当初６年間の工期予定だったものが約２年短縮されるという、その原因といいますか、どういうところからそうなったのかということと、地域住民の方にしてみれば、２年短縮されるということは４年後になるわけですが、４年といっても相当長い期間ですので、その内容によっては、それをさらに短縮するということが講じられるのかどうかという部分と。","respondent":"矢部下水道河川課長","answer":"その後、発進筒という形になりますので、立坑の築造工事の短縮というのはちょっと難しいという感じがしておりますので、４年をさらに短くというのは物理的に厳しいんじゃないかなというように私のほうでは解しております。","id":"exchange-010"},{"speaker":"田中委員","kind":"確認","question":"中延６丁目は、そういう意味ではカバーされるとは思いますが、５丁目の地域の方々にとっては、大半が公園よりも上流の部分に当たりますので、そういう意味では、代替地がないとするならばあそこが最適なのかもしれませんが、全体を網羅するということで言うと、先ほどは少し奥まったところにお話がございましたが、再確認を含めて、上流部分で、中延５丁目の方も大きく網羅できるような用地というのは。","respondent":"矢部下水道河川課長","answer":"私も、流域について先ほど申し上げました。よく調べてみますけれども、荏原町公園以外、流域に近い流域で適当な公園はなかったというのが現状です。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう意味では、工期短縮をなされて、地元の皆様にご理解をいただけると思いますし、また、荏原町公園を活用することによって、上流地域の皆様にも大きな効果が見込まれますし、引き続きぜひご尽力いただきたいという観点で、再確認ということで、意見を言わせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"船波委員","kind":"質問","question":"公共の道路とか、公園とか、そういうところなら行政側もやりやすいにしても、民間の土地でも、そういう舗装ができないかなと思うような駐車場とか結構あると思うので、民間の土地にも浸透しやすい舗装を広げていくことはできないかと思うんですけれども、そういったことに関して影響が何かないのかどうかお伺いします。","respondent":"松代道路公園課長、矢部下水道河川課長","answer":"私のほうで、道路の維持管理、表面排水の処理等をやっております関係で、先ほどご覧いただきましたように、あそこの地域では横断側溝をすぐに設置するということで、今設計等に入りまして、既に着手するようになっておりまして。１点は、下水道のほうにもお願いしていきますけれども、今回の浸水エリアの中で、半地下の部分も何件かありますので、半地下の部分に浸水をして困っているという方もありますので、一つは、半地下にしないというＰＲも必要でしょうし。","id":"exchange-013"},{"speaker":"堺委員","kind":"質問・要望","question":"参考までに１点だけ教えていただきたいんですが、この図面の中に荏原の雨水調整池がありますね。あそこの効果はどうなんですか。","respondent":"矢部下水道河川課長","answer":"貯留状況については、今回の８月４日の大雨のときにも満水状態になっております。ですから、そこに調整池がなければ、下流側の中延５・６丁目を含めて、もっと浸水被害が大きかったかなというふうに考えております。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問・要望","question":"さっき田中委員がおっしゃっておりましたけれども、ある程度質疑が出ましたので、今日決をとっていただいて、私としては採択というふうにお願いをしたいと思います。請願理由の中にも、近隣住民の人たちが毎回大変な被害を受けている中で、やむにやまれずこのような請願事項５項目を出されてきたと思います。ぜひこの請願について採択をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"４年前に大雨が降ったときに、水が実際に出た地域で、半地下というか、何段かおりてから玄関がある住宅が増えている地域があるんですけれども、建築申請がされたときに、規制をするというか、その辺の注意をするというのか、実際にこういう方は知らずに買っているわけですけれども、その辺を規制するような手だてというのはとれないものなんでしょうか。","respondent":"山室住宅指導担当部長","answer":"規制といっても、いろいろな設備対応等もできますので、一方では、きちんとした設備対応をすれば支障なく活用することができるわけですので、当面の課題としては、窓口で十分理解してもらうように努めていくというのが現実的ではないかというふうに考えてあります。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"上流部は一応やるという計画はあるけれども、具体化になっていないだけであって、それだったらば、中延５・６丁目、中延幹線と合流しているあの地域に被害が大きいという面では、第二立会川幹線のところの上流部をもうちょっと先に延ばしていただいて一挙にやり上げるというのが本当に効果があるのではないかなと思うので、その辺を含めてお伺いします。","respondent":"矢部下水道河川課長","answer":"その後、区長名で局長あてに文書を出しております。そういうことで、前にそういう話は聞いておりますけれども、こういう請願も出されております、皆さんがこういう意見ですので、さらにその辺を再検討をお願いしたいという話を要望しています。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"請願にこれだけの切実な要求が出されている。都と区と協力をして、より早く具体化して、皆さんの意に沿うという格好を出していただきたいと思います。採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"船波委員","kind":"質問・要望","question":"私も水害と言えば、西品川のほうでよく被害に遭って、掃除とか苦労しましたので、やはりそういった被害が起きないようにしてほしいと切実に感じますから、ぜひ被害を防ぐことが少しでも早くできるように、この請願は採択していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"本間委員","kind":"質問・要望","question":"先ほどもお話にありましたように、この地域の部分も個別の名称は出ていないけれども、大きな工事絡みの中で含まれているというふうなお話もありましたし、実際に既にこの請願が出て以来、東京都へ要請文を届けに行ったとか、あるいは現地で立会川幹線の内部視察をするなど、土砂堆積等々の調査をしたとか、既に前向きな取り組みがなされておりまして、東京都との関係を大事にしながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問・要望","question":"１点だけ教えていただきたいんですけれども、今、区内でもいろいろなところで随分マンションが増え続けてきているんですけれども、この間やってこられた演題、講師のところですけれども、実際にセミナーに参加をされた方から意見を聞いたりして決めていらっしゃるのか、それとも区でその状況に応じて決めておられるのか、そこだけ教えていただけますか。","respondent":"田村住宅課長","answer":"ですから、それは毎年やっていますから、それを全体調整して、あと、私たちもほかのブロック、城南ブロックも聞いておりますので、講師として話もうまいし、おもしろいような形で、総合的に勘案して、毎年１回の講師を決めておるです。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"1)の１７.８６倍、4)の２３.４１倍、この辺で、間取り構成についての考察ですか、荏原とかを今つくっておりますけれども、世帯構成とか、間取り、平米の広さとか、その辺についての考察はあるのでしょうか。","respondent":"田村住宅課長","answer":"今飯沼委員がおっしゃったように、この表を見ますと1)と4)が、もちろん募集戸数が、2)については６２戸ですから、倍率だけで云々というのはできないですね。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"親在住ということでは、今後介護の問題とかもいろいろあるので、いろいろな要求をもとに聞いて、構成を考えていってほしいなと思います。イのところは、子どもを育てるという面で、戸数が３倍あった。やはりこの辺の要求もきっと高くなるんじゃないかなと思いました。私は荏原に住んでおりますけれども、荏原地域が何でこんなに４５.３３％もあったんでしょうか。","respondent":"田村住宅課長","answer":"あくまで申込用紙の在住の住所要件で引っ張っているだけなので、申込用紙に、例えば都営住宅ですと、今の居住環境はどうですかというようなのがあれば、何が申し込むきっかけになったのか分かるんですけれども、今回はあくまで住所要件が荏原の地区だけで。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問","question":"今まで区民住宅は直接区が管理していたんですが、管理形態が多少変わりましたね。今まで、例えば何カ月間か家賃を滞納をした方は追加承認という形でこの委員会に出てきていましたけれども、これからはその辺はどうなっていくのか。家賃を滞納する人を想定して考えるのもおかしいですけれども、ちょっとそこだけ教えてください。","respondent":"田村住宅課長","answer":"ところが、今、菊地委員がおっしゃったように、あくまで行政の財産ですから、入居者管理、例えば３カ月未満の滞納督促等は品川宅建管理センターでやってもらっておりますが、法的な措置は行政処分ですから、それは行政でなければできない。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/296109?Template=document&Id=3744#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":23380,"voices":79}},{"id":"h15-20030120-9","meetingId":"h15-cm01","date":"2003年1月20日","dateIso":"2003-01-20","committee":"文教委員会","time":"午後１時０３分～午後３時８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高星委員","kind":"質問・要望","question":"どちらの学校もグランドはどういう形状になっているのか、要するに周りの関係で、土であればほこりがたつとかということがあるので、形状について教えていただきたい。","respondent":"鷹倉庶務課長","answer":"今、委員ご指摘のとおり、私どもは今回学校改築検討委員会をそれぞれやっていた中の一番のポイントは、新しく入ってくる子どもたちはいいんだけれども、在校生に対する配慮をできるだけしてほしいというのがあります。迷惑をかけないようにです。","id":"exchange-001"},{"speaker":"高星委員","kind":"質問・要望","question":"グランドは、基本的に人間は生きている動物である以上は土が望ましいのかなと思うんです。できるだけそういうふうに近づけていただきたいと、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"原委員","kind":"質問・要望","question":"１点確認させていただきたいと思うんですけれども、荏原第五中学校の仮校舎計画図を見すると、学校エリアで囲まれるような形になっています。ただ、台場小学校の場合、屋内運動場が別から入ってきていますね。その辺の安全性はどういう形で配慮されているんですか。屋内運動場は使っていながら工事もしていくという形ですよね、それは配慮があるのかないのか。","respondent":"鷹倉庶務課長","answer":"台場小学校の場合については、屋内運動場を使う関係で若干説明します。この建て替え計画の下の2)をご覧になっていただきたいんですけれども、おっしゃるとおり工事中のエリアと屋内運動場が重なるような形になってあります。","id":"exchange-003"},{"speaker":"原委員","kind":"意見","question":"仮設ブリッジは立体的になるのか、形状はどういう形でつくられるのかどうか。","respondent":"鷹倉庶務課長","answer":"今のところ立体的なものを考えているところです。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"プロポーザルで事業者を決定したというのは、何社の参加で、決定した事業者名を教えていただきたいというのが１点。それから、それぞれ台場小学校と荏原第五中学校の学年別の教室の数をどう見ているのか教えてほしいんですが。","respondent":"鷹倉庶務課長","answer":"書類審査の上、９事業者に絞りました上で選定させていただいたのが(株)桂設計になってあります。そして、それぞれの改築検討委員会のメンバーですけれども、校長、教頭、ＰＴＡの代表の方、台場小学校については同窓会が入っております。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"もう１点だけ、確か台場小学校は地域に開放された立派な和室があったと思うんですけれども、地域開放というのは、これまでやられたことを意識し受け継ぐのは、どういう考え方なんでしょうか。","respondent":"鷹倉庶務課長","answer":"奥に和室がございまして、そこで学校改築検討委員会をやっていただいております。","id":"exchange-006"},{"speaker":"石田委員","kind":"質問","question":"台場小学校の工事工程だけを伺いますと、計画通知があって、工事着工があって、校舎引渡しがあるということなんですが、予算の関係もあるのか私はわからないわけですが、例えば９カ月前倒しをして新校舎工事期間を９カ月みて、これを早めに始めれば１２月の終りに引っ越しをして、最終的なグランド整備が終わるのが９月の終りだということですが、そういう形で前倒しをしていけば、夏休みの間に終わるとか。","respondent":"鷹倉庶務課長","answer":"私どももできればそうしたいなと思ってあります。実は、考え方の上で７月となったのは、工事契約議案を定例会にお願いするという前提を考えれば、このような形になる。これを例外的に前倒しするような形、債務負担でやるようなことは例外です。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"今のお話はわかりましたので、これは要望にしておきますが、子どもたちのことを考えれば、やはり節目節目というのが、例えばお休みが入ってそれが節目になると思いますので、そこの段階で終わるとか、その学年の子どもたちは１年間これだと全部だめということになるわけですから、その子どもたちのためにもそういうことが可能かどうか。","respondent":"鶴委員長、青木指導課長","answer":"他にございませんか。他になければ、本件を終了します。(2)の小・中一貫校における教育課程等の考え方についてを議題といたします。本件について、理事者の説明をお願いいたします。一番上に書いてあります「子どもに合った学び方で学力を伸ばすとともに、自らの行き方を主体的に拓く」。説明が終りました。ただいまの説明にご質疑等がございましたら、ご発言を願います。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"これから具体的なものの検討に入るということですけれども、一番心配するのは、できる子どもは伸ばすということは変なことだし、わからない子どもはわかるようにきめの細かい指導をということでやられているんですけれども、その考え方は今言われた習熟度別学習の徹底ということなんでしょうか。","respondent":"青木指導課長","answer":"必修科目のみならず選択科目においても、習熟度的な考え方でコースを選べるような、そういうカリキュラムの編成に心がけていきたいと考えております。","id":"exchange-009"},{"speaker":"沢田委員","kind":"質問・要望","question":"先ほどで言いますと、必修科目と習熟度別科目にもわたって習熟度別学習をやると、これをやればやるほど能力別学級に近づいていくと思うんですけれども、そうするとますます子どもたちが学校の中にあって、できる子ども、できない子どもという言い方が正確かどうかは別として、子どもたちの負担は半端じゃなくなるんじゃないかと思うんですけれども、そこはどうしようとしているんでしょうか。","respondent":"青木指導課長","answer":"要するに、私が今説明をしているチャレンジというのは、より習熟度の高い、非常に創意工夫の富んだ学習内容でありますし、がっちりというのはチャレンジまで至らなくても、とにかく今やっているような内容について、さらに習熟を図りたいというグループになるわけでして。","id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"前に私はこの委員会で一貫校の小学校部分というか、ここで言うと４年生部分から上がってきた子どもの中にも差がつくでしょう。中学校から２クラス全然一貫校でなかった７年生のときに合流をしてくる子どもとどういうふうにバランスを取っていくのかと言ったら、三つぐらいの教育課程をつくることがという話があったんですけれども、それは検討した上でどうなっているんですか。","respondent":"青木指導課長","answer":"７年生で編入した際の学力差ですが、大きく学力差が生じるということは一般的には考えられるかと思いますけれども、私どもは編入者に対しても必修においても、選択においても、学力差に対応できるようなカリキュラムを検討していくということは前回もお答えしていますが。","id":"exchange-011"},{"speaker":"原委員","kind":"質問・要望","question":"今、お話をお伺いして、教育課程編成に向けての案ということで、それぞれのところで熱い思いのお話をされているようですけれども、お話を聞いていて、発達の特徴にしても、発達過程にしても、考え方にしてもかなり考えられていて、しかもそれを教育的内容とか教育方法に分けて詳しくお話をいただいたんですけれども、果たしてこれをどう具体化していくのかなと思っているんです。","respondent":"青木指導課長","answer":"現在教育課程等検討部会で内容については検討してきてありますが、来年度から具体的にカリキュラム編成委員会をつくっていきたいと考えています。そこで各教科の内容についてのカリキュラムを打ち出してまいります。","id":"exchange-012"},{"speaker":"原委員","kind":"質問","question":"そうすると、今、日野中学校と第二日野小学校でやられている現場、今実際どの辺までやられているかわからないんですけれども、そういったものが現場でいろいろ形としてつくり出されてきて、それがこの中でフィードバックされてきますということなんですか。どのぐらいまでやるとかいろいろあると思うんですけれども、そういうところはどう考えていらっしゃるんでしょうか。","respondent":"青木指導課長","answer":"現在、今目指している教育課程というのは、小・中一貫校がすべてできあがった形のものを想定してやっておりますので、当然移行期間がございまして、第二日野小学校、日野中学校の研究というのは、そうした意味で移行的な段階になるかと思うんですが。","id":"exchange-013"},{"speaker":"原委員","kind":"質問","question":"今お伺いしたのは小・中一貫校に向けて文部科学省で考え方の土台になるようなことが言われたと思うんですけれども、そういったことはこういう中ではどういう形で反映をされていこうかと考えていらっしゃるんですか。","respondent":"青木指導課長","answer":"文部科学省でもさまざまな研究開発ということで、私どもは小・中一貫校という形で研究開発を進めているわけで、文部科学省に対しても研究開発の中でかなり自由な研究ができますので、今までの６・３制といった考え方も。","id":"exchange-014"},{"speaker":"上山副委員長","kind":"質問","question":"今までは６・３制ということで小学校、中学校でやってきて、今後一貫校については４・３・２制という形で分けたという案だと思うんですけれども、こういうふうに幾つか子どもの発達の特徴ということで考えているというのがあったんですけれども、今までの６・３制との違いというんですか、利点あるいはこれによってこういうことを変えられるんだとか、その辺の基本的なことを、最初にお伺いしたいと思います。","respondent":"青木指導課長","answer":"もしくは、中学２年生をスムーズに迎えられるというような、生活面でのプラス面も期待しているところであります。","id":"exchange-015"},{"speaker":"上山副委員長","kind":"質問","question":"それからもう一つ、こういう形で４・３・２制という形でやっていく計画だと思うんですが、実際に１クラスの生徒の数。例えば、今品川区では４０人学級をやっているかと思うんですけれども、今度の一貫校の中では１クラスはどれぐらいの予定というんですか、今いる方々が入る人数もあると思いますけれども、実際上は何人ぐらいで運営していこうと思っていらっしゃるのか。","respondent":"青木指導課長","answer":"１点目の、４・５制と６・３制のメリット、デメリットというご質問かと思いますけれども、先ほどのご説明の中でも、子どもの変化に合わせたフレームを変えていこうという考え方で、新たな取り組みとして４・５制というふうにしたわけです。","id":"exchange-016"},{"speaker":"上山副委員長","kind":"質問・要望","question":"いずれにしても、今までの６・３制からすると、前にもこういう案が少しは出たことがありますけれども、具体的な話としてはっきりしたのは今回初めてなので、そういう意味では大きな変化というか、変わり目だと思いますので、そういうものを含めて経過をもう少し明らかにしていただきたいという要望なんですけれども、最初の質問に答えいただければありがたいんですが。","respondent":"青木指導課長","answer":"この中でも、こうした提案についてはいろいろなご意見をいただいておりますが、現在各学校でも低学年、中学年、高学年、例えば１・２年、３・４年、５・６年とした分け方で考えてみたり、１・２・３年と４・５・６年というような区分で考えてみたり。","id":"exchange-017"},{"speaker":"上山副委員長","kind":"質問","question":"大きな変化というか、変わると思いますので、もう少し文教委員会も含めて、この間の検討事項などの報告を、全面的にはいろいろ難しいと思うんですけれども、報告をしていただければありがたいと思うんですけれども、その辺はどうでしょうか。","respondent":"青木指導課長","answer":"前回は基本像をお示ししたんです。目指す学校像とか、何故に小・中一貫校の検討しているのかというような形で、こちらでご説明をさせていただきました。","id":"exchange-018"},{"speaker":"高星委員","kind":"質問","question":"入ってきたいという人は二けたもないという数字を聞いているわけですけれども、そういう中で、本当に小・中一貫校の品川区独特の「プラン２１」の計画が本当に丸二年経過して３年目に入ってくるわけですけれども、こういうところに来て、自信のほどを改めてお聞きしたいなと思うんです。","respondent":"青木指導課長","answer":"１点目ですけれども、先ほどもこの取り組みが新しい学校のあり方ということで、現在の６・３制のそれぞれの学校に対して、このアイデアや考え方、そしてその方法などが生かせるものであれば生かしてもらえるような。","id":"exchange-019"},{"speaker":"沢田委員","kind":"質問","question":"その事実関係は、我々は大体データを持っていないんですから、もしつかんでいるデータは教師しかつかんでいませんので、わかれば教えてほしいということ。それから、今の答弁の中で、「都教委に特別な要請をしている」とおっしゃっていたじゃないですか。そうすると、私が言うのは正しいんじゃないのかなと思うんですが、その辺がどうか、まず３点を教えてほしいんですけれども。","respondent":"若月教育長、青木指導課長","answer":"こういう公的な場でお答えしてしまうと、こうだというふうに決まってしまいますので、お答えするのを非常に躊躇されるんですが、例えば、現在の段階で私あるいは都教委が考えているやり方というのは。もう１点、カリキュラムのことですが、今年度は教育課程検討部会ですけれども、平成１５年からはカリキュラム検討委員会を立ち上げまして、それぞれの２校の学校と連携を取りながら、平成１７年度末には完成させたいと考えております。","id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、日野中学校の現在の先生たちにはどのような説明をしているのでしょうか。もう１点、教育課程に関する問題ではないんですが、以前報告のあった用地の問題は、その後どうなったんでしょうか、用地買収の話です。","respondent":"青木指導課長、鷹倉庶務課長","answer":"教員の問題ですけれども、先ほど教育長の話もありましたけれども、具体的な形で決定しているわけではございませんので、教員にはそのようなことは話しておりません。具体的な買収等は来年度予算にも絡むこともあって、発言は控えさせていただきたいんですけれども、準備をして詰めているという段階とご理解をいただきたいと思います。","id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、小・中一貫校と教員の異動に対しては、何ら説明もされていないということですね。それから、今の用地の件なんですが、基本的には合意したということなんですか。準備という言い方をされていたんですけれども、売買契約がまだされていないのはわかったんですけれども、概要としては了解を得たという段階なのかどうなのかだけ。","respondent":"鷹倉庶務課長","answer":"何人か地権者がいらっしゃるわけですけれども、一部の方について条件の部分が若干折り合わないということです。","id":"exchange-022"},{"speaker":"石田委員","kind":"質問・要望","question":"どうしてこういうことを聞くかというと、品川区に追随してきたのであれば文部科学省は、今都教委の話もがあったけれども、直接文部科学省にいろんなことを言いながら、一体となってこうやろうよと言えば、また動きか変わってくるし、そこに教育長が行くのか、だれが意見を言ってくるかは別としても、そういうふうに一体となってやってこれれば。","respondent":"富田教育改革担当課長","answer":"ただいま石田委員のご発言で、おそらく１月の読売新聞の記事を見まして、学校教育法の改定ということで、小・中一貫がやりやすいように学習指導要領を大いに弾力化してというような記事のことをおっしゃったのかと思いますが。","id":"exchange-023"},{"speaker":"石田委員","kind":"質問・要望","question":"記事だけを読むと、文部科学省はそういう形で小・中一貫を推進していくみたいなところがあれば、そこを飛び越えて、せっかく品川区が発信をしたのであって、あれが追随してくれて追い風になるのであれば、教育長を含めて皆さんがその辺の検討委員会をつくるのか、どういう審議委員会をつくるのかわからないけれども、逆にこちらからアプローチをかけて、おれたちを使えみたいな動きがあって。","respondent":"指田教育次長","answer":"県費職員の問題は、非常に難しい問題を抱えていることは事実です。","id":"exchange-024"},{"speaker":"中島委員","kind":"質問","question":"先ほど沢田委員と高星委員が質問されたことに関連してなんですが、品川区から出ていく先生方が三けたで、入ってくる先生は二けたに満たないといううわさというのは、教育委員会でもキャッチされているんでしょうか。","respondent":"青木指導課長","answer":"そういうようなうわさをいろんなところで立てられているという事実は受け止めております。","id":"exchange-025"},{"speaker":"中島委員","kind":"質問","question":"現実はそうではないわけですね。それに対しての対処というのは、考えていらっしゃいますでしょうか。","respondent":"青木指導課長","answer":"対処というものは、私どもは意欲ある教員が品川区を志してくださるという事実もありますので、転出する教員がいれば転入する教員もいるわけですので、やはり同じような人数になるのは当然ですから、そういうふうに考えていけば。","id":"exchange-026"},{"speaker":"中島委員","kind":"質問","question":"ある学校で８年ぐらい前に起きた事件があったんです。「とんでもない、お父さん。子どもたちに品川区はすごいんだよという、こういううわさはいいと思うんですが、逆に子どもたちに不安を与えるようなうわさというのは、事実をしっかり確かめてから流すべきだと思うし、そういううわさが流れたらきちっとそれはくい止めていくというのも行政の役目じゃないかなと思うんですが、いかがでしょうか。","respondent":"青木指導課長","answer":"今、それぞれの学校で必死になって学校の質を改善しよう、向上しようと取り組んでいる先生方の努力というのも私たちはアピールしていかなければいけませんし、またそれぞれの学校の校長がそうした意味で、うちの学校はこうなんだ、品川区の教育はこうなんだということも。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"関連で。不安を、あるいは事実と相違したことを吹聴しないために聞きたいんですけれども、先ほど区外の転出が１５１人、区内の転入が１２５人とおっしゃったと思うんですが、これはいつの時点なんですか。","respondent":"青木指導課長","answer":"平成１４年度の４月の段階です。要するに、年度明けの段階で、教員の人事の結果です。","id":"exchange-028"},{"speaker":"沢田委員","kind":"質問","question":"出ていったまま補充されていないのでは、大変なことになってしまうから、４月１日の時点では当然足らず人を集めるということになると思うんですが、ちょっと聞きたいんですが、この中でベテラン教師と新任教師の割合というのはわかりますか、転入をしてきた中でデータを取ったものはあるんでしょうか。","respondent":"青木指導課長","answer":"先ほど申し上げましたように、必異動という制度があります。ですから、４年間他区でやってきた新人、まさに新規採用が５年目に品川区に来るというケースもありますし、それから２校を経験した８年目の方が来るということもあります。","id":"exchange-029"},{"speaker":"沢田委員","kind":"質問・要望","question":"これは数字で言ったのではわかりずらいので、できれば次回に出て行った人の年齢構成、入ってきた人の年齢構成、わかる範囲で資料をつくっていただいて説明願いたいと思います。一応、要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"沢田委員","kind":"意見","question":"知りたいのは、ベテラン教師が品川区を離れていないかと、ちょっと不安なところなんです。それで教育の実態というか、新しい先生と入れ代わっていないかということがちょっと不安なところなので、例えば平均年齢でもいいです。ただ、不安があるので、正確なところを知りたいということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"沢田委員","kind":"質問","question":"ベテランという言い方が正確じゃないと思うんですけれども、年齢構成の変化があるのかないのかと。例えば、入ってきた１５１名で、総年齢を足したものを割れば平均年齢が出るだけじゃないですか、それでいいですよ。それは簡単ですよね。それと出ていった人を数で割れば平均年齢が出る。","respondent":"青木指導課長","answer":"そういう意味で、その数字が示すところは何かとなると、私どもがもし提供するならば、そうしたことで説明をしなければならないと思いますけれども、そうした意味で説明が非常に難しいというふうに考えます。","id":"exchange-032"},{"speaker":"中島委員","kind":"質問","question":"関連なんですけれども、さっき質問の途中で関連で手を挙げられたので。今の沢田委員のご質問ですが、先ほど青木課長がおっしゃっていましたように、力量と年齢とは違うというのは、全くそのとおりだと思うんです。このデータを沢田委員がどういうふうにお使いになるのか、そっちのほうが疑問なんです。意見だけ申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"こだわるわけではないですけれども、異動の状況の中でどういう変化が先生方の中で起きているのか、どういう先生方の勤務年数がどう動いているのかというのを知りたい。数だけの問題だけれども、数は最後に帳尻を合わせなければしようがないんです。だから、その変化を一人ひとりやったら大変でしょうから、大まかのところでいいからわかればいい。それ以外の何にもないです。","respondent":"青木指導課長","answer":"たびたび恐縮ですけれども、新しい先生が入ってきているのか、それとも年配の先生が入ってきているのかということは、平均年齢でわかります。","id":"exchange-034"},{"speaker":"沢田委員","kind":"質問","question":"だけど、これが正確かどうかはわからないです、途中段階だとすれば。それは構成がどう変化したのかというのが出てこなければ、私は問題ないと、例えば品川区が先生方から選ばれたのか選ばれないかという、ある意味ではそこで一つの指標になるわけですから、だからその傾向がわかるものを示してくださいということを言っただけのことです。出すべきではないという意見があるならば、それはそれで結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"石田委員","kind":"確認","question":"今の公園の件なんですが、もちろんこれはインターネットに載ってくると思うんですが、貸切利用がない時間帯は一般開放をするというのは非常にいいことで、私は大賛成なんですが、その利用上の制限等かあると書いてあるんですが、詳しくはお問い合わせくださいということですが、基本的には利用上の制限もインターネットに載せて。","respondent":"上川内生涯学習課長","answer":"多目的広場ですが、当面は管理画面しか出ないので、もう少しこれから検討しまして空き情報を見るにもプログラム修正をしなければなりませんので、そこはちょっとお時間をいただきたいと思います。","id":"exchange-036"},{"speaker":"石田委員","kind":"質問","question":"管理画面という意味がよくわからないので、空き情報は多分それに載らないとなると、もちろん先ほども言ったように、利用上の制限は載らないのかなと思うけれども、例えばそういう意味のことを言っているのであって、フリーマーケットとかそういうことを言っているのではなくて、例えば学校ですまいるスクールがあったり、野球のチームがあったり、空き情報を見ながら。","respondent":"上川内生涯学習課長","answer":"画面では見られませんが、公園のところに管理事務所があります。その隣に大きな掲示板をつくって、空いている時間帯を書くようなことを考えているとお伺いしています。は電話で問い合わせていただくとか現場に見に行っていただく。","id":"exchange-037"},{"speaker":"石田委員","kind":"質問","question":"私の質問は、現場に見に行くわけではなくて、学校で画面を見て、じゃみんなで行こうとか、野球のチームの監督とかだれかが見て行こうとかなるわけです。そういうのは予定としてここに書いてありますけれども、予定としてはいつごろまでに空き情報から含めて、画面を見て制限をわかるわけですから、そういう画面がいつごろまでに整備しようとされているのかなと、それだけを最初から聞きたかった。","respondent":"上川内生涯学習課長、指田教育次長","answer":"まだ、いつごろまでと期限が出ていないんです。今、管理画面だけをやっているので、空き情報はなるべく早くやっていきたいと思いますが、それはプログラム修正とか仕様変更等々時間がかかりますので、今後前向きに検討します。できる限り早めにそういうものを出したいと考えています。したがいまして、今日の時点ではいついつできるという形は言えません。したがいまして、わかり次第、また委員会等にご報告を申し上げたいと考えております。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/380076?Template=document&Id=4462#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":34876,"voices":109}},{"id":"h15-20030121-6","meetingId":"h15-cm01","date":"2003年1月21日","dateIso":"2003-01-21","committee":"区民委員会","time":"午後１時０４分～午後３時０１分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"やはり、一番問題になっているのは、前回も問題になりましたけれど、官民一体に加え、議会関係者も参加検討できる会ということで、前回いろいろ質疑が出まして、そのお答えの中で、課長のほうから公的な検討機関、公的な組織を通して、こういうことを設けるのではなくて、あくまでも地域の中での私的な検討組織としてこういうものを具体的に申し上げれば、地元の議員の皆さん方にも協力してもらいながら。","respondent":"市川産業振興課長","answer":"この辺は、商店街の役員の皆さんも思いは思いとしてあろうかと思いますけれども、実際に、特に商店街振興組合が活動の主体となっている限りは、振興組合というのも公的な組織ですので、ましてや、区内あるいは議員という公的なものがそこに加わるとなると。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この審議の中にも書かれているんですけれども、ここの残地を区が買い上げて、例えばこれの店舗をつくって、そこに若い人たちなんかも入りやすくするような、創業支援のような形も含めて、そういう形でやっていくというふうなことなんかも含めて、ちょっとやはり１６３号線というのは、商店街の方の意思ではなくて、１６３号線が通ることによって立ち退きをせざるを得ないというふうな状況になるわけですから。","respondent":"市川産業振興課長","answer":"その活動に、あるいはそういった事業に、どういういい環境づくりをしていくかということが私どもの役割になろうかと思いますけれども、そういった事業そのものをどういうふうに組み立てていくかということで、今商店街の皆さんが。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だけど、そのところの支援を、例えば商店街の方がずっと研究して、こういう商店街をつくっていきたいと、そういった方向が出されたときに、その支援として、こういうふうなことが商店街のほうから求められた場合は、そういうことに対して区としてはできる限り支援をしていくということで応じるという、そういうふうな考えとしてはいかがでしょうか。","respondent":"市川産業振興課長","answer":"これは今まで折に触れて申し上げてきたところなんですが、区としては地元の商店街の方々がこれからなさろうとしていることについて、区としてできることについては協力をしますということは、これは商店街の皆さん方にもお伝えしてきているところですので。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"区としてできることというのが、今提案をしたような中身のことというのは、区としてできることだと思いますので、そういう点では、商店街のほうからぜひそういったことを商店街、その地域からそういうふうな要望が出された場合はぜひ前向きに検討していただいて、そういう支援もしていただく、検討していただくというふうなことで確認をさせていただいてよろしいですか。","respondent":"市川産業振興課長","answer":"区としてできることというのは、区は商業振興ももちろんですけれども、市街地の整備、いろんな総合的な観点から最終的に区がやるべきことということは結論を出すものですので、そういった意味では。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"これから商店街の方たちもそういうふうなところで検討していくところでの研究、そのための会合の立ち上げに積極的に協力していただきたいというのが今回の請願の２項目めですので、そういうところで、これからいろいろな研究をされる中で、そういう提案もされていくと思いますので、そのときにはぜひ西大井とかなんかでもされてきた、その具体的なところでも。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"それは残地というよりも、そこで建て替えますよね。問題は大体２０平米ぐらい、６坪ぐらいのところが建つか建たないかということで、それ以下の部分は、当然残地を買ったって、花壇になったりすることになるわけですから、その残地の部分を区で買い上げるというのは、私はおかしいというふうに思うんですね。そういうのでしたら、商店街の方たちが補償金によって６坪余った。どなたか、答えられれば。","respondent":"市川産業振興課長","answer":"そういう意味で、今回商店街のほうが、まず組合としてこういう学習活動を立ち上げて、そういった要するに地域的な視点から、どういう街づくりができるかということも一つの大きな視点の中に加えて検討を進めていきたいということをおっしゃっているのは。","id":"exchange-006"},{"speaker":"松澤委員","kind":"質問","question":"ほんとうに商店街がなくなるというようなことで、身につまされる、大変な中でのいろんなことをしたいという意欲があるということは、大変私たちも買っているんですけど、その意味では、なかなか、今収容法そのものでは、建物の一部がかかってしまっても全部取り壊して、それで取り壊して収容を含めて出しますよという形になっているものですから、そういう意味では、街づくりの方向性。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"本田委員","kind":"質問・要望","question":"議員は、それは建築の専門の方もおられるかもしれませんが、しかし、素人ではあっても、複眼でいろいろな角度から見ることができるというふうに思っておりますから、この２番の項目で議会関係者もという点で、議員の方々が少しでも街の商店街の方々の要望に応えるようなアイデアなり、何らかのサジェスチョンをできるような役割が果たせれば私はいいと考えていますので、今日はこの２番のところは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"本多副委員長","kind":"意見","question":"１６３号線の拡幅に対しては、この請願理由にも入っておりますけども、事業に反対するのではなく、公共に寄与する目的でということで、商店街さんのほうで自助的にされていくということで、これまでの前回の委員会では請願の１を街づくり特別委員会の様子を見ながらということで、１、３、４、それぞれが趣旨採択というような方向づけになって、議会もその商店街の支援をするという方向で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"本田委員","kind":"質問","question":"もちろん品川区だけじゃなくて、東京都に対しましても強くそれは働きかける必要があるんではないかなというふうに今説明を聞いておりまして、いつ来るかわからないと言われている大震災等に対応していくためには、どうすればいいかというふうに考えて、ふと今言ったような点が手っとり早いんですが、どんな検討状況なんでしょうか。","respondent":"久保田防災課長","answer":"学校のほうですけれども、今広域避難所の避難場所等のご説明をさせていただきましたけれども、基本的に第一次の避難所につきましては、学校というふうに品川区は定めておりまして。","id":"exchange-010"},{"speaker":"本田委員","kind":"質問","question":"そうすると、一次避難の学校について、防災課としては全部の学校が大丈夫ですよと。これだとあまり費用もかからないんだけれども、そういう耐震診断、耐震補強の手だてというのを、私は街づくり委員のほうということではあるけれども、防災課のほうで関係するところが一元的に掌握して進める必要があるんじゃないかと思うんですけれども、いかがでしょうか。","respondent":"久保田防災課長","answer":"防災課のほうではですけれども、これまでも防災課の役割としましては、いわゆるそういうような防災上の対応なりということは、それぞれの、例えば街づくりですと街づくりの所管になりますし、それから火災における消火活動ということであれば、消防署になるわけですけれども。","id":"exchange-011"},{"speaker":"本田委員","kind":"質問・要望","question":"じゃあ、小学校４０校、中学校１８校の一次避難所の学校については基本的に安全であると。それからもう一つ、木造建築物については、耐震補強策を自治体の助成制度などを加味しながら、ちょっとこれは新しく政策の展開になるかもしれませんが、ぜひ品川区で震災が起きて、大きな被害が起きてからでは遅いわけですから、できるだけ早く政策的な手段を講ずるように、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もし、聞き損なっていたらごめんなさい。廃止になった地域がありますよね。その地域の方たちに対しては、通知というのはこれからどのように、どのような状況で扱っていくのか、その辺を一つ教えてください。","respondent":"久保田防災課長","answer":"この説明資料にあります２月１０日施行というのは、いわゆる避難場所と避難道路との指定の施行です。これまでも大きく避難場所の指定について係わる町会等の皆さんにつきましては、私どもこういう形でのパンフレットを用意しています。","id":"exchange-013"},{"speaker":"三上委員","kind":"質問・要望","question":"特に若い人たちのひとり暮らしをしている人たちだとか、こういった人たちが昼間は全く家にいない、夜中、いつ帰ってくるかわからないような人たちが、結局夜帰ってきたときに、何かあった場合に避難場所がどこへどうしたらいいのか、こういうようなことが起こりかねないということが心配されるわけですから、やはり、個別的にもきちっとした形で目にできるものをやはり何らかの形で考えてもらえないかな。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問","question":"表の見方なんですけど、５,０７３町会のランクをつけて、品川区の町会も含めた中で、ワーストテンに４町会入っているということでよろしいですか。","respondent":"久保田防災課長","answer":"全町会数の５,０７３は多摩地域も含んだ数です。その中で、順位づけをしたところ、ワーストテンというんですか、その中に四つの町会が入っているです。","id":"exchange-015"},{"speaker":"松澤委員","kind":"質問","question":"すさまじいというか、びっくりするような表を見せていただいて頭が痛い。ワーストテンに４町会も入って、何か総合的な大きな話の時にでも。やっぱり、密集住宅再生地区事業なんかをやっていますけれども、あれはなぜこの辺が指定されていないのかちょっとわからないですけど、ここはやっぱり特別な施策をしなくちゃいけないように思うんですけどね、どうですか、防災課長は。","respondent":"久保田防災課長","answer":"街づくり事業部のほうでも、こうした状況の中で、どの手法がやっぱり有効な手法として防災に強い街づくりをやっていけるのかということを、今早速検討に入っているところですので。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この調査というのは５年ごとに一遍やる調査ですよね。その５年前のときの調査と比べると、やっぱりワーストテンには、５年前だとどれくらい入っていたんでしょうか。","respondent":"久保田防災課長","answer":"前回との比較なんですけども、冒頭も申し上げましたとおり、評価のやり方が違いますので、順位レベルでもっての比較というのは単純比較できないということが一つあります。あえてお話し申し上げますと、前回１０位以内に入っているところというのはないです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"密集市街地の指定を受けるというようなところでは、また旗の台四丁目、五丁目は今までもずっとそういうふうなところで取り組まれてきたと思うんですけども、それ以外に今後そんな方向というのは出されている地域というのがあったら教えていただきたいんですけど。","respondent":"久保田防災課長","answer":"これは密集市街地事業というふうな今お話が出たので、あえてお話し申し上げますと、東京都の防災都市づくり推進計画、この中に反映されるということになってございまして、先ほど出た二葉三、四丁目につきましては。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"じゃあ、その方法というのは二葉三、四丁目だけですか。","respondent":"久保田防災課長","answer":"先ほどお話ししたとおり、旗の台四丁目、中延五丁目と連檐している地域になっていて、この辺の一帯というふうに要望しているというふうには聞いております。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"年末の融資が減っているということ、この減っている理由というのはどういうことなんですか。","respondent":"市川産業振興課長","answer":"一つ大きな理由として考えられますのは、先ほど新規のお客様の数が前年３３％に比べて２２％、約１０％落ち込み、もとの数字が違うので、一概に１０％の低減とは申し上げられないんですが、これは金融機関から紹介をされて、この資金の利用をなさるお客さんが減ったと。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"それともう一つ、なかなか借りられない。中には、個人破産というんですか、申請するのにお金がかかるので、そのお金を借りたんじゃないかなんていう声があるぐらい、そういうのが増えている。あるいは保証協会の利率が上がるというんですかね、ほんとうに金融機関が金を貸したくても借りられないという状況は相当あるような気がするんですね。その辺、どういうふうにとらえているんですか。","respondent":"市川産業振興課長","answer":"先ほど申し上げた金融機関によって、プロパー融資もそうですけど、制度融資の取り扱いについても、金融機関による取り扱いの違い、温度差というのがかなり出てきておりまして、私のほうはなるべく温度差が出ないように、つまり、温度が高いほうに。","id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"制度融資で保証料の補助をしながら融資をしていく。その中で、先ほど言いましたように、倒産する件数、返済不能になるという、そのような数字はしっかりととらえているんですか。","respondent":"市川産業振興課長","answer":"定期的にこの品川区の所管ですと、東京信用保証協会の五反田支所というところが、私ども品川区と目黒区を所管してございまして、定期的にその年度の区全体、制度融資だけではなくて、市中金融機関の融資も含めた全体の保証承諾の件数、金額。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"意見","question":"前からずっといろいろしている件で、全体の枠が減ってきているというのは、冒頭の説明の中にあったと思うんですが、返済の負担が大きいという話、都の制度融資はたしか年度内に一本化、まだ品川区は当然実施していない状況で、今後の、この年末とちょっと別件になりますが、全体の話の中で、今後の見通しとして、品川区としてどういうふうに考えているか、一つだけちょっと。","respondent":"市川産業振興課長","answer":"私ども、東京都の制度融資に合わせて、区での実施はどうかということで検討していますけど、今のところ、もしご利用希望の方がいれば、東京都のまず制度の案内をさせていただいて、その動向を見た上で、考えていきたいというのが現状です。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう一つは、３,０００万円というお話がありましたけど、区内の中小企業ですと、３,０００万円の負債を抱えてしまうと、かなり大きな負債になると思う。ですから、ちょっと今の課長のお話は、少し規模の大きい企業じゃないかなという感じもするんですけど、もうちょっと零細を考えた場合、制度融資の中で、区の制度融資の中で考えてあげることはできないのかなと思うんですが、いかがでしょう。","respondent":"市川産業振興課長","answer":"今年度もまだ全体の状況の把握はできていないながらも、なかなかそのことでお使いになる方がいらっしゃらないというのが、その辺がさっき申し上げたあえて区としてメニューをつくるかつくらないか、今の時点で判断をすることをしないというのは。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区の中はできないよというのが出ているわけですね、現状で。ですから、希望を聞いてもできないという前提になっちゃうんじゃないかなという感じがするんですけど、品川の金融機関側でどういうふうにとられているか、計算上、金融機関側ではまずできないんだよということは当然話は行っていると思うんですよね。少しでもできないかなという自分の考えなので、その答えは結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"三上委員","kind":"確認","question":"本人確認の際に、写真がついている運転免許証とかパスポートだとかという、これは確認できますよね。だけれども、健康保険証だとか、年金証書だとかというのは顔写真がなければ、本人確認といっても、果たして本人なのかどうかというのは、どこまで確認できるかということになりますよね。それとも、きっちりと２点以上は見せてもらいますよというようになるのかな。それで、これは品川区だけですか。","respondent":"冨田戸籍住民課長","answer":"運転免許証あるいはパスポートということであれば、官公署が発行しているもので写真つきですので、これらのものにつきましては、１点で確認をします。","id":"exchange-026"},{"speaker":"三上委員","kind":"意見","question":"写真が入っていれば、それは一番いいと思うんだけどね。もう一つ、私なんかが一番これから困るのは、本籍が品川じゃないんですね。今までも郵送でやってきているわけです。向こうに送って、記載事項に必要なものを書いて送ってもらっているんです。それは、ほかの自治体はできるんだけど、品川の場合、そういった場合、どうするの。","respondent":"冨田戸籍住民課長","answer":"こういった取り扱いにつきましては、私どもも、言ってみれば後発的なやり方になりますけれども、他区なり他市もほぼ同様の形をとっているように思っております。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区民に配布するというのは、どういう形で配布されるのか、このことを一つお聞きしたいのと、それと、こういうふうにやられるというのはすごい大賛成で、これがほんとうに進んでいくと、住民の意識にとってもすごくいいなというふうに思うんですけども、対象のところで、今の１、２、３、４、５、６、７、８番目まで書いてあるんですけど、ここのところに安全な食品とか、低農薬の野菜とか。","respondent":"金井環境課長","answer":"それから配布方法ですが、直接区民の皆さん全員に配るというふうにはなかなかまいりませんので、私どものところに一応置いていく予定でもありますが、今考えたのは２,０００部ほどしか予算的にはないものですから、２,０００部ぐらいを作成したいと考えていますので。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"身近なところで、買い物するところのお店がわかればいいななんても思ったので、品川区全体のお店でどういうところを、そこのところで利用するときにはあまり関係ないのに、利用する範囲なんかでこういうふうにどうなっているのかというふうなのがわかるような、そこら辺のところは工夫してやっていただけるといいなというふうに思ったのと、安全な食品というのは、あまりやっているところがないということで。","respondent":"金井環境課長","answer":"このリーフレットの件ですが、これはエコクリーン店という、区が認定したお店だけを載せるものなんですが、もう一つは、今区商連のほうでノーレジ袋運動をやっておりますが、ノーレジ袋をやっているお店の紹介も含めて、それと一緒にこちらも挟み込みながら。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ここに説明ある部分なんですけど、認定後に環境清掃事業部のホームページに掲載するということが出ているんですが、これは各個店の名前をホームページに掲載していくということなんですか。","respondent":"金井環境課長","answer":"一応そういう予定にしておりますけども、当然ながら、そのお店の了解もとらなきゃいけませんし、そういうことは私のほうは考えておりますが、今後広報の担当の者とも十分協議をしてやっていかなくちゃいけない問題も含んでいるかもしれませんが。","id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"質問になるのか、答えられるかどうか、ちょっと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-02","title":"行政視察の報告書についてを議題にします。 太川区民生活事業部長だけお残りいただき","agenda":"行政視察の報告書についてを議題にします。 太川区民生活事業部長だけお残りいただき","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"行程表的なものが、視察場所と視察事項というのは当然ありますけど、どんな行程だったか、結構ハードな行程ですよね。そういうのをせっかくだから入れておけないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その視察場所がどこでとか、どの辺にあるか、時間帯も余りないですよね。だから、実際にかなり質疑した部分も、そういうのが見えないじゃないですか。そういうのがつけられないのかなと……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/302915?Template=document&Id=2350#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":32786,"voices":103}},{"id":"h15-20030121-5","meetingId":"h15-cm01","date":"2003年1月21日","dateIso":"2003-01-21","committee":"総務委員会","time":"午後１時０９分～午後３時５１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件抜き出しています。","topics":[{"id":"topic-01","title":"平成１４年請願第３１号、旧正田邸についての請願","agenda":"平成１４年請願第３１号、旧正田邸についての請願","exchanges":[{"speaker":"土井委員","kind":"意見","question":"テレビ取材等々を含めて、どういう取材をなさる形なのか。例えば、いわゆる最初の頭撮りのような形で、後はいわゆる録音なり何なりの中から取材をされるという形のものなのかどうか、その辺はいかがなんでございましょうか。もし頭撮り程度のお話ですと、まあいいのではないかということも考えられるんですけれども。","respondent":"伊藤委員長","answer":"許可申請書に書いてあるものにつきましては、取材をしたいとしか書いてございませんので、委員長としては、そのことしかお答えできかねるです。","id":"exchange-001"},{"speaker":"土井委員","kind":"意見","question":"我々が、開かれた議会をつくっていくという形の中に、宣伝活動、ＰＲ活動の一つにでもなっていくことも必要な部分はあろうというふうに思うわけです。頭撮り程度だったら、私は許可されてもよろしいのではないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"桜井委員","kind":"確認","question":"基本的には、私は公開すべきだという立場なんです。それをちょっと危惧するんです。だから、もし個人の議員の発言を放映されるとすれば、本人の発言内容も確認いただければ、そういう条件であれば。意図的な編集ということはないでしょうけれども、真意が伝わらないようなものであればちょっと。ですからそこが条件的に満たされれば、私はいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"桜井委員","kind":"確認","question":"新聞報道のところでの、今の課長の説明ですけれども、国のほうからは、区に対して、こうして差し止めをされたりという、今の経過の説明というのはあったんでしょうか。区のほうはとりあえず、公園として買いたいと言っているわけですよね。そうした国に対して申し入れている区に対して、国のほうからは説明というのはあったんでしょうか。そこだけ確認しておきたいんです。","respondent":"中尾根企画部長","answer":"この間、国からは１月１４日に、もうそれはマスコミ報道されて、局長が談話を発表したその日の午前中ですけれども、財務省としては、そのような判断で、新しい業者を決めて、１５日からそういう作業に入るということを、一応、地元の品川区に対してご通知いたしますと。","id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"裁判の専門用語ですので、ちょっとわかりにくい部分がありますので、差し止めの仮処分を申請したということがどういうことで、２４日に双方を呼んで審尋というんですか、そういうことだそうですけれども、この辺をもう少し詳しく、手順的にどうなって、仮処分申請に対する結論がいつごろ出てというような、一般的な例でよろしゅうありますから、そこのところの流れといいますか。","respondent":"市岡企画財政課長","answer":"具体的な訴訟事件については、私どもも知るすべはございませんが、一般的に、差し止めの仮処分を求めるというのは、一定の行政庁の行為に対して、いわゆる事後救済では回復できないようなケースがあった場合に、事前に行政省の行為を。","id":"exchange-005"},{"speaker":"塚本委員","kind":"意見","question":"その後の、仮処分の願いが適当がどうかという判断をするのは、どのぐらいの時間がかかると考えられますか。","respondent":"市岡企画財政課長、伊藤委員長","answer":"一刻も早く解決しなければならないような事件であれば、緊急性の度合いで、逆に言うと、認めるにしても、認めないにしても、早く結論を出さなければ、その状態が不安定になるような場合には早く結論を出すし、そうでなければ。先ほど、冒頭、お話をさせていただきました進め方に基づいて、次に、紹介議員より、請願の趣旨、内容説明等をしていただきます。順次、ご発言いただきます。","id":"exchange-006"},{"speaker":"高星委員","kind":"質問・要望","question":"請願第３１号の件につきまして、私と藤原議員が紹介議員になっていますけれども、この間のかかわり方からも含めまして、私のほうから、何で私たちが紹介議員に名を連ねたかという部分の理由めいたものについて、先にお話しさせていただきたいと思っています。請願者の皆さんからは、これまでの経過をお聞きした上で、さらに請願理由についての説明をいただいた次第です。残された時間的余裕がありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"二、三伺いたいことがあるので、お尋ねします。請願事項は３行ということで、文章としては短いんですけれども、私の理解では、大変輻輳していると思います。一つは、「品川区は」ということで、続くわけですけれども、「旧正田邸の跡地購入ののち」と、「跡地」という表現がどういうことなのかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"高星委員","kind":"質問・要望","question":"私がお答えさせていただきたいと思います。今、理由の中で述べさせてもらったんですが、全体のこの請願理由を読んでいただければ、大体思うところの骨子はわかっていただけるんじゃないかなと思います。その意味での、その跡という意味も含めて、全体としては、これはその土地というふうなご理解をしていただきたい。特にこれこれといった手法が用意してあるということではございません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"藤田委員","kind":"確認","question":"ちょっと確認なんですが、終りから３行目、「品川区におかれましては土地購入後、しばらくの間当該建物が取り壊されることのないよう」云々と書いてありますね。この辺の意識といいますか、認識をどのようにされていたのか。区のほうに、何らかの確認をしたのかどうか。この辺だけちょっとお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"高星委員","kind":"質問","question":"ごもっともな質問だと思うんですけれども、当時既に、マスコミ等でしか知らないわけですけれども、品川区は建物のない形で取得するんだという報道がされていました。先ほど、私、申し上げましたけれども、やはりここは品川区の議会なんですね。財務省は国の機関です。だから、その意味で、議会というのは、正しく品川区民から選出をされた議会で、区民の意思を最も尊ぶべき機関だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"桜井委員","kind":"質問","question":"一つは、区長が国に対して購入ということを言っているのが１１月１２日ですよね。それで、今、藤田委員からもお話しがあったように、建物つき土地を購入をしてほしいと、さっきちょっとそう言い方をされましたよね。だから、この請願の真意というのが、建物がついた土地を購入してほしいということであると、区が公園としてというのとちょっと真意が違いますよね。大きくは二つです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"高星委員","kind":"質問・要望","question":"２点目のほうから先に。それから、動いている運動体というのは、私はこう思うとか、それぞれ皆さん私見が違うものですから、そこのところは、今私が言及するのは難しいのかなと思いますので、現時点で、どういうような動きがあるかということについては、ちょっと差し控えまして、私のほうから言えないだろうと思います。このことをお願いしようと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"桜井委員","kind":"質問","question":"それで、運営を委託をするというところが、ちょっとわからないんですが、そういうところまで考えていくと、どうも建物がすごくありがたいということはわかるんですけれども、この請願には、あまりそういうところまでなかったんですけれども、今の説明でお話があったものですから、何かもう少し具体的に考えられていること、お話があれば、もう少し聞きたいと思うんですけれども。","respondent":"伊藤委員長","answer":"念のためにお話ししておきますけれども、お二人の紹介議員に来ていただきましたのは、この請願の内容につきましての質疑ですので、現在の動きとか、その後の動き、それから、品川区がこういうふうにしたという過程の話については、紹介議員からお答えしないということですので。","id":"exchange-014"},{"speaker":"高星委員","kind":"意見","question":"答えられる部分に限って話したいと思います。それから、ことの重要性を鑑み、請願者はじめいろいろと苦心されている方々が、それぞれの委員なり、関係する方々のところに、いろいろな意味でお電話でお願いしたり、足を運んでお願いしたりしておりますので、できれば、その細かいところ、より確かなところを、請願者の皆さん、運動体の皆さんと話していただければありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"土井委員","kind":"質問・要望","question":"前回の質疑のときにも、私のほうから、文化財というものに対するお話をさせていただいたと思うんです。それは、どうなんだろうか。したがって、そこら辺について、この前の理事者側のご発言等、お話を伺っておりますと、何か価値がないということを認めちゃっているようなふうにも聞えたんですけれども、再度確認をさせていただきたいと思います。","respondent":"市岡企画財政課長","answer":"私どもが、文化財であるかどうか、あるいは価値があるかないかということを申し上げたわけではありませんで、国の説明によれば、文化庁が国の見解として、度重なる改造等が行われて、現在、文化財保護法にいう文化財には該当しないという見解を持っているので、取り壊しについて。","id":"exchange-016"},{"speaker":"土井委員","kind":"質問","question":"それは、いわゆる文化庁がきちんと調査をして、調べて、学者、研究者等々も含めてのご意見を伺って、その結果、出した結論であるのかどうなのか。そしてまた、それを文化庁がおっしゃるなら話が見えるんですけれども、それをおっしゃったのが財務省の方だとすれば、それは果たして何なんだろうか。財務省に文化の価値を云々する状況があるのかないのか、こういうことになるんですけれども。","respondent":"市岡企画財政課長","answer":"説明がなかなか難しいんですが、要するに、私どもは、財務省から、文化庁がそのような見解を出しているということをお聞きしたわけで、これ以上申し上げると伝聞になりますので、私は、そういう事実そのものということを申し上げたということです。","id":"exchange-017"},{"speaker":"土井委員","kind":"質問","question":"今の話を伺いましてね。あるいは、国の文化財としてのものが、それぞれの都道府県等の文化財、品川区などの地方自治体の文化財、あるいは、そのまた下の部分の何とか町という部分の文化財ということは大いにある得る話ですから、そこら辺についての検討、研究はどのようになっているんですか。","respondent":"中尾根企画部長","answer":"前回も、たしかそのようなご質問があったと思いますけれども、私どもは、そのときにもお答えしましたのは、持ち主は国でございまして、国が責任を持ってやることで、しかも、文化財にするかどうか、持ち主の承諾がなければ、そのことはたとえいくら価値があったとしてもならない。","id":"exchange-018"},{"speaker":"土井委員","kind":"質問","question":"要するに、財務省の方が、文化的価値の問題を云々される。だから、そこら辺の段階からいきますと、今、少なくともその文化財的価値をもう認めるべきだという議論が起こったわけですから、そのものに対して、どこかで何らの形の答えを出していくということがなければならないんだろうと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"土井委員","kind":"質問","question":"半分意見です。要するに文化財としての価値を認める、品川区に文化財保護審議会を開いてくださいとは、今、申しているわけではありませんけれども、そういう道筋をたどらなければ、この問題の本質的な解決に向かわないんではないかと、こんなふうに思うんです。したがって、そこら辺に対する見解があるのかないのかをお聞きしたい。","respondent":"中尾根企画部長","answer":"そういう国民的な立場の疑問に対しては、持ち主であるところの国がきちんと説明すべきだというふうに、基本的にはそのように思ってあります。","id":"exchange-020"},{"speaker":"塚本委員","kind":"意見","question":"土井委員の心配、それから答弁もよくわかりますけれども、この件に関してではなくて一般的に、国の所管にあるものが文化財であろうというふうに国民から指摘が起きた場合、文化財として認めてくださいという手続はどのように踏んだらいいかということは、皆さん方は答えられますか、同じ行政マンとして。","respondent":"市岡企画財政課長","answer":"都条例によるもの、区の条例によるもの、あるいは、前回、桜井委員のほうから指定文化財というお話がありましたが、いずれも所有者の同意がなければ指定ができないものですので、その点で、私ども品川区として、手続も含めてお答えがなかなかしにくい。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"何を聞いたかというと、こういう願いを持っている人が多くいたと、この人たちはどういう手続をとればいいのかということを教えてほしいんです。どこにどういうふうに働きかけるのが筋ですよ、ここからすべてが始まるんだというものが何だか教えてもらおうかなと思います。","respondent":"市岡企画財政課長","answer":"例えば品川区の場合ですと、文化財保護審議会が、そういう指定について諮問を受けて、審議をするという手続になりますので、これも教育委員会にそういう希望を述べるという道はあろうかと思いますが、先ほど言ったような基本的な要件で。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"国というのは、ある意味で、国民が集まってできているわけですから、それぞれ自分たちの財産だということも可能なわけです。そういう疑問に対して、自分たちのものなんだから、こういう扱いをしてほしいということを、もっと間口を広げて受け入れるという姿勢があってもいいんではないかなという疑問は、この件に関しては、初歩的な疑問だろうかとも思いますけれども、持っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"桜井委員","kind":"確認","question":"今、裁判というか、とりあえず工事差し止めということがあるわけですから、そういう点では、現時点に立って、先ほど来、財務省としてはこうなんだという言い方もしているんですけれども、逆に、区民からこういう請願が出されたという側面からすると、文化庁に対して、機関としては行政機関じゃないにしても、価値の部分もそうなんですけれども、住民の皆さんからの。","respondent":"中尾根企画部長","answer":"ただ、一般論として言えば、そのことについて、当然いろいろ区も考えてきたわけだし、そういうやり取りは、財務省のほうの方針がどうなるのか、私どもの買う意思の中で、こういうことなんだけれどもというやり取りは、それなりにはさせていただいたわけで。","id":"exchange-024"},{"speaker":"桜井委員","kind":"質問","question":"筋論としては、わからなくもないんです。あくまでも所有者は国ですからと、そういうことだけで扱うというふうにしないで、議会でも苦労しているところなんですよ、率直に言って。そういうことからすると、これは、客観的に区のほうに何らかの段取りをしていくのが一番筋かなとは思うんですけれども、その辺もうひと言いかがでしょうか。","respondent":"市岡企画財政課長","answer":"部長が今申し上げたとおり、いろいろ難しい状況を考える中で、この更地をあとあと悔いの残さないように、少なくとも品川区が確保することが最も区民の皆さんのご理解が得られるし、長い目で見て、現状の中では一番いい方法だという判断をしたから、そう申し上げたわけです。","id":"exchange-025"},{"speaker":"塚本委員","kind":"質問・要望","question":"解体の囲いがしてあるというのが現状で、皆さんのほうから、取り壊しということに関して、品川区、行政自治体としては、どういう実務上のかかわりというか、問題ですとか、インターネットで契約や何かも見れるそうですけど、私は特に詳しくないので、この辺のところは、どういうふうになっているのか、公になっている部分を教えていただきたい。","respondent":"市岡企画財政課長","answer":"この場合、国、官公庁ですので、通知という形を取りますが、この通知が１月１４日付で私どもの建築主事のほうに出されました。と同時に、これは建築統計上のことになりますけれども、この解体に関する除却届けというものも同日出でいます。","id":"exchange-026"},{"speaker":"塚本委員","kind":"意見","question":"私、解体にはそれなりに詳しいんですけれども、大まかに手壊しと機械壊しというのがありまして、機械で壊すのは安くなるんですけれども、機械で壊すことはないという。その仮定の話ですけれども、この件に関してじゃなくて、解体をしたときにこのものは、通常、どういうルートで処分されますか、もしわかれば。","respondent":"中尾根企画部長","answer":"一般的には、解体業者が産業廃棄物として、それなりにきちんと処理をするというのが普通のルートだと、私ども受けとめております。","id":"exchange-027"},{"speaker":"土井委員","kind":"質問・要望","question":"私も契約の内容を見させていただいて、財務局にもしつこく聞いて、後からこんな公表の仕方じゃだめだから、新しい別なやり方を考えなさいと言ったんですが、それはそういうことです。当該建物の、先ほどは文化的価値のお話などしたわけですけれども、これの歴史的価値、評価というものをどう見るのかということがあろうかと思います。歴史的価値について、少しご議論いただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"藤田委員","kind":"質問","question":"そうした中で、先ほども説明がありましたが、１７日に住民の方々が東京地方裁判所に仮処分を申請したということで、我々もそこまでやるのかなと、ニュースを受けとめたわけです。これについて、区としてのどのように受けとめているのか、その辺をちょっとお伺いしたいなと思います。難しいかもわからないけれども。","respondent":"中尾根企画部長","answer":"そうすると、それぞれの皆さんのものの考え方なり、どういうふうにすればいいのか、ないしは思想的なものなんかも含めて、Ａといえば、全くそれに真っ向する反対の方もいますし、当然ながら、税金なんか投入するからいけないんだという考え方の方なんかもいらっしゃるわけで。","id":"exchange-029"},{"speaker":"塚本委員","kind":"質問","question":"土井委員から、歴史的価値という議論もすべきだというご意見がありまして、どうなのかなと思っているところです。今回は、いろいろな要素が加わって、一地方議会、あえて品川区議会の中で議論するには荷が重すぎるなという思いもありますけれども、その機会を与えられたんですからということも踏まえて、受けとめなければいけないと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"桜井委員","kind":"質問","question":"先ほどの１月１７日に提出されて、２４日に東京地方裁判所で審議がされるということなんですけれども、こういう審議の最中には、もちろん出した当事者と相手方になるんでしょうけれども、区のほうは、いわば第三者という形なのか、あるいは一定程度の事情を含めて、そういうところがあるのか。そのあたりはどういうふうになっているんでしょうか。","respondent":"市岡企画財政課長","answer":"訴訟は当事者間の紛争を解決するものですので、品川区は当事者ではありませんので、この裁判手続については、第三者と言われましたが、訴訟上の当事者ではありません。したがって、どのような形でも、その訴訟そのものに品川区が関与するということはありません。","id":"exchange-031"},{"speaker":"林（宏）委員","kind":"意見","question":"基本的に、きょう、この委員会でこの請願をどうしようかという話については、ちょっと流動的になるんだけれども、裁判の手続が踏まれたということで、先ほどの説明の中で、早急に答えが出されてくるものだろうというような発言がありましたけれども、公正に裁判所が、今回、出された請求に対応してもらうという意味からすると、裁判になるのか、ならないのかも含めて、継続にしてもう少し見守るというのが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"桜井委員","kind":"質問","question":"非常に取り扱いに苦慮するところなんです。先ほど、区のほうに何らかの、当事者ではないけれども、住民の皆さんの、取り壊しをもうちょっととめてほしいという気持ちは受けとめておきたいなと思うんです。ですから、私たちは私たちの立場で、そういうことについての考え方を示して、独自の働きかけをしたいと思っていますけれども、この請願については、継続です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"土井委員","kind":"質問・要望","question":"そこの意見といいますか、態度を求められているということ。したがいまして、ぜひともここで、この内容については採択、もしくは趣旨採択という形で、今現時点での、品川区議会の総務委員会の意思をしっかりと発表しなければ、裁判所に従属をした形の議会になってしまうという点からも、そのようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"川西委員","kind":"質問","question":"今、請願書の中に出されているのと、暮れから正月にかけての経過、理事者の皆さんも随分ご苦労なさっていることも十分踏まえつつ、あるいは、私が少ない住民の皆さんとの新年会等でのご意見、品川区が、土地を買ってくださるなら、しばらくの間、残しておいてもいいんじゃないですかという、簡単に言うと、外野的といいますか、わかりませんよ、これは、一般の区民の声を、私が尊重すると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"土井委員","kind":"質問・要望","question":"今、申し上げました議会のあり方、要するに、裁判をながめているということはどういうことを意味するのかということについては、ぜひ、各会派の皆さんのご議論をいただきたいと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-02","title":"でございます。 (1)の第１５回品川区世論調査","agenda":"でございます。 (1)の第１５回品川区世論調査","exchanges":[{"speaker":"嶋委員","kind":"意見","question":"これは３,０００部ということなんですが、活用方法とか、また、どういうところに配られるのか。","respondent":"山田広報広聴課長","answer":"３,０００部ですけれども、区民の皆さん方にごらんいただけたらということで、当然、資料コーナー、図書館、それから文化センターや地域センターと、地域のところの部分に配付をするというものと、それから、モニター週間で改めてモニターになっていただいた方であるとか。","id":"exchange-037"}]},{"id":"topic-03","title":"(2)の公職選挙法の一部改正等","agenda":"(2)の公職選挙法の一部改正等","exchanges":[{"speaker":"土井委員","kind":"質問","question":"一番最後のところにございましたが、寄附の制限のところで、もうちょっと詳しく教えていただけますか。","respondent":"野田口選挙管理委員会事務局長","answer":"その中の３点目の、講習会等における必要やむを得ない実費弁償については、任期満了の前の、今回の場合については、４月２７日の９０日前からそれができないということになってあります。実費弁償であってもできませんという規定です。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"そういうことを寄附というんですか。ちょっと具体的にどういうことなんですか。その一番最後に触れられる場合の寄附というのは、研修会を開いて、お土産を出さなきゃいいんですか、飲食は実費をもらったらいいんですかという話になるわけですよ、寄附じゃないんだから。そして、会場費が、さっき言ったように１００円かかると、会費として３,６００円もらえばいいですか。そこなんですよ。","respondent":"野田口選挙管理委員会事務局長","answer":"ですから、概念は広いです。ただ、さっき言ったように、会場を借りたお金を払う会場費とかいうのは債務の履行ですので、そういうものは寄附とは言わないんです。それから、９０日あるないにかかわらず、飲食の提供については、先ほど言いましたように、禁止されています。","id":"exchange-039"},{"speaker":"林（宏）委員","kind":"確認","question":"確認しますけれども、９０日以内に飲食を伴う会を開いてもいいんですね。","respondent":"野田口選挙管理委員会事務局長","answer":"ちょっと具体的な事例については、個別に相談してほしいんですけれども、飲食については、いいということよりも、飲食を提供することは、公職選挙法で禁止されています。ただ、１,０００円の弁当を１,０００円の会費を取って払うことは、これは寄附ではないです。","id":"exchange-040"},{"speaker":"林（宏）委員","kind":"意見","question":"だから、９０日以内というのは、飲食を伴った会合というのはできないというふうに言われているんですよ、会費を取ろうと取るまいと。今の解釈だと、１,５００円のお弁当を用意しておいて、お酒を出すとややこしくなるから、ウーロン茶１本１００円でつけて、１,６００円の会費で、後援会を集めてやるのはいいんですね。","respondent":"野田口選挙管理委員会事務局長","answer":"今言っている、いわゆる候補者等の寄附ですけれども、候補者等が１,５００円を弁当を出す、これは寄附です。だから、寄附についての制限ですので、今回、寄附の９０日の部分で該当するのは、講習会等において……。","id":"exchange-041"}]},{"id":"topic-04","title":"の平成１５年４月執行の東京都知事選挙、品川区議会議員選挙および品川区長選挙における開票","agenda":"の平成１５年４月執行の東京都知事選挙、品川区議会議員選挙および品川区長選挙における開票","exchanges":[{"speaker":"桜井委員","kind":"意見","question":"だから、当然、わかっていることかもしれませんけれども、職員の任用、給与等に係わる見直しも、なぜ必要なのかというところも、できれば住民の福祉向上とか、サービスを充実させていくとか、そういうところの文言を入れていただければと思うんですけれども。意見を申し上げておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"今、桜井委員が言われたのは、下から５行目のあたりの話をもっと具体的に書くと、「独立性を発揮した区政運営が求められている」というだけではわからないと、そういう意味ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"手順というか、こういう決定でどういうふうに、時間的なことも含めて、それを教えてほしいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"塚本委員","kind":"意見","question":"そうすると、そのペーパーそのものが直接上のほうに行くということではないんですね。修正があれば修正をして、それを議長に出して、これが区側なり議長会に出るのか。あるいは、それを踏まえて議長が発言するのかによって、扱いがちょっと違ってくるんだと思うので心配するんですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"林（宏）委員","kind":"意見","question":"もう１点、区長にというのはあったんですけれども。口頭では、何回かこれに近いものを言っている部分がありますので、総務委員会で決定したという言葉は入っていませんけれども、品川区議会議長として考えていくべきだというような発言はしますので、全く同じじゃないですけれども、どうかなと思うんです。","respondent":"濱野助役","answer":"差し出がましいようで申しわけないんですが、この案件につきましては、二団体の見直しをしたときに、いずれかの団体で、共通基準については見直しといいますか、具体的な検討をするということになっていました。","id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"今、助役の説明を承りますと、ある種の経過になっていて、わかりやすく一定以上の強さで意思を出してくれたほうが進みやすいと、目的にかなうんだということのようですから、ただいまの指摘もある部分納得できますから、それに加えて文書を出すということがよいのかなと、私は今のところ思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"どこまでいくのか、文章化したときに、それが決議文になるのか、要望書という形にしてどこかに発信する、そういうケースがいろいろ考えられると思うんです。そんな中で、決議として上げるか、要望書として出していくところを助役会にするのか、区長会にしたほうがいいのか、あて先の絞り、選択が必要になってくるのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"桜井委員","kind":"意見","question":"最初、想定されたことは、議会としてこういうふうな方向だということを、今までの流れだと、議会側から区長に渡す。区長のほうで、各関係機関ということなんだから、しかるべきところに議会のほうから届け出ると、今までの流れだと、そういう感じですよね。決議にするのは、もうちょっと議論していかないと、議会の決議……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"塚本委員","kind":"意見","question":"委員会レベルで、委員会の意思表示を決議という表現にしていいのかどうか、ちょっとわからないけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"桜井委員","kind":"意見","question":"今、言ったのは、今までの総務委員会、あるいは、行財政改革特別委員会でのまとめ方というのは、それは行政に対しての場合ですよね、今までは。だから、委員会でこういう話し合いもして、こうですよということで、区長あてに議長を通して出していたわけですね。今、新たに出されたのは、議会の意思として、例えば議長会なり、そうすると、またもう一つ違う別の意思決定というか、しますよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"だから、従来やっていたルートというのか、委員会でまず決めて、議会運営委員会に諮って、議会意思として取りまとめて、意見書、あるいは要望書という形で議長名で、それぞれあて先を決めて、総理大臣から都知事から、いろいろ方向が決まる。だから、そういう手順を踏むとなると、やっぱり議会運営委員会にという、議会意思とするとそういうことになってくる。","respondent":"福田区議会事務局長","answer":"したがいまして、僣越ではありますけれども、まずそれは議長にご報告をし、そして２３区の内部機関の委員長同士がお集まりになっている２３区の委員長会の中で、とりあえず委員長が品川区の総務委員会としてはこういうことを考えているんだということを。","id":"exchange-052"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"時間的にないから、持ち帰って、今、局長が説明されたようなルートと、意見書とか要望書という形とを、できるだけ早い時期に委員長に、会派の考え方を伝えてもらったらどうですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"桜井委員","kind":"質問","question":"そうしますと、委員長のほうには、会派の意見は次回の総務委員会でいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"法務局のほうの話で、確認です。そうすると、これが最終的な説明と要望である、いわゆる行政。これが来て、区側としてどういう、もう一度アクションを起こすのか、要するに、口頭で来たのに、区としては、助役をはじめいろいろ口頭とか、文書も一部入って申し入れをしたと。改めて、文書で向こう側からこういうことが来たと。内容としては、そんなに変わってないというお話だったけれども。","respondent":"本間総務部長","answer":"この文書は、当初から、口頭で説明だけがなされておりましたので、当初から、それをきちんと文章で出してくださいということを言い続けていたものが、ようやくこの時期になって、おそまきながらということで出されてきたというものです。","id":"exchange-055"},{"speaker":"桜井委員","kind":"質問","question":"それで機能的に、郵便局が窓口を設置とか、これは具体的に書いてありますよね。というのは、平成１５年度中ということは来年度中ということですね、来年度というか、もうすぐです。ということは、もう既に、平成１４年度には何からの動きを始めるわけですから、何かもう少し、いわゆるアクションをここで起こすべきではないかなという気がしないでもないんですけれども、その辺はどうなんでしょうか。","respondent":"本間総務部長","answer":"この点につきまして、前の委員会のときにもご説明申し上げましたとおり、向こうは、ＩＴを使ってとか、郵便局の窓口を使ってとかいうことを言ってありますが、それは、今の時代、成熟していなくて何らの代替措置にはなりませんよということは。","id":"exchange-056"},{"speaker":"桜井委員","kind":"質問","question":"だから、文書をもらっているわけですから、やっぱりこの時点では、何らかのアクションをする必要がある。だから、改めて代替というよりも、やっぱりここに残してほしいという旨を、はっきりしたものをきちっと文書なりにしてアクションを取る必要があるんじゃないかと、そういうことです。","respondent":"本間総務部長","answer":"いずれにいたしましても、この文書一つでも、もう２週間に一遍は相手方と常に連絡を取り合って、絶やさないようにということで、今までもやってきております。","id":"exchange-057"},{"speaker":"桜井委員","kind":"意見","question":"帰ってきて、委員会で意見交換をしましたよね。あれの議事録というのは乗ってなかった気がするんですけれども。行政視察の当地に行ったのは、まとめられたというのはわかるんですけれども、帰ってきて、ここで意見交換しましたよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/805080?Template=document&Id=1608#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":41257,"voices":159}},{"id":"h15-20030122-13","meetingId":"h15-cm01","date":"2003年1月22日","dateIso":"2003-01-22","committee":"清掃・リサイクル特別委員会","time":"午後１時０８分～午後２時５８分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"川西委員","kind":"質問","question":"材料試験の項目のことですが、焼却する以前はごみですから、材料に含まれる害になるようなものというのは既に除かれているというふうに理解してよいのかどうか。これらの絵にありますようなところに使われた場合に、吸水率というのがありますけれども、これの説明をもう一回お願いしたいと思います。良いのかどうかということですね、言い替えれば、浸透性についてどのぐらいの効果があるのか。","respondent":"中山清掃リサイクル課長","answer":"１点目の、ここに示されている物質以外の成分がどうかですけれども、この利用方針の中で定めている基準というものは、土壌の中で一定量以上になると有害になってくる物質を例示しているものでございまして。","id":"exchange-001"},{"speaker":"川西委員","kind":"質問","question":"内容は分かりましたが、浸透性が今までの素材より良いのかどうかというところは、今の説明からいくと、一言で言うと、どうなんですか。","respondent":"中山清掃リサイクル課長","answer":"スラグという考え方が従来はございませんでしたので、繰り返し申し上げるように、砂替わりとして公共工事、いろいろな土木工事に使われておりますから、それと同じように使えるかということですから、そういう意味では。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことでちょっと伺いたいと思うんですけれども、今は実際に環境基準以下にしているということなので、その限りにおいては安全なのかなというふうに思えるわけですけれども、本当にそこのところというのは私たち住民として不安が拭えないんですね。今実際問題、言問通りとか、蔵前橋通りというところで現実的に使っていたわけですから、ここのところの溶出試験はやられていなかったんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"余談ですけれども、大田清掃工場の場合は、若干初期の機械だということもあって、鉄分除去の問題であるとか、ハリといいまして、ガラス状の突起の関係があって、完全に民間に出すには少し成分的に調整、工夫が必要だということで。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"溶出試験というのは、既に試験的な実例のところでやられていなかったのかどうか、その辺を、先ほど質問をしたつもりなんです。","respondent":"中山清掃リサイクル課長","answer":"東京都時代からそのようにやってきております。今回の板橋清掃工場につきましても、早速第１回の試験を行いまして、すべてにおいて規格値を下回る試験結果になっているというデータは出てあります。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"私たちが日常生活の中で排出して、自分たちが排出してしまうもので、結果的に環境汚染みたいになってしまうということになるわけですから、暮らし方とか、物の捉え方というのは本当に認識を変えていかなければいけないということを大前提にしながらも、しかし、安全に保っていくための調査・研究、そして情報公開、そういうものを改めてきちんとしていただきたいということを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"嶋委員","kind":"質問","question":"インターロッキングブロックについてお聞きをしたいんですが、この中で使われているのはほとんど歩道に使われているということなので、歩道ですから、ほとんど自転車ぐらいか、人なのかなと考えていますが、重量はどのぐらいまでを想定しているのか。耐用年数はどのぐらいあるのか。１回敷いたら、インターロッキングを替えていくお考えがあるのか。","respondent":"中山清掃リサイクル課長","answer":"ＯＡフロア材としての利用は、これも詳しく認識してございませんけれども、多分ほかのものと混ぜていると思うんです。","id":"exchange-006"},{"speaker":"嶋委員","kind":"質問","question":"先ほど、クッション性があるということで、吸水性もあるということで、見た目もきれいですし、そういう意味では公園なども大変いいかと思います。角的に強い部分があって、減る部分があるので、それでお聞きをしたんですが、もし何かありましたら、もう一度お願いいたします。","respondent":"中山清掃リサイクル課長","answer":"煉瓦の角の部分でというのは、スラグ成分そのものというよりは、形によってそういう危険もあるということで、例えばこのイラストを見ますと、従来の四角型のインターロッキングブロックと少し、波状のタイプがあったりというふうなことで。","id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"すべてが在庫になっているのか、どうなっているかということを聞きたいと思います。それと、ここで言う値段は、経費が相当かかっているものだから、一般の業者から見て、砂よりも絶対得だというものなのか、それとも一般の砂よりは１０分の１ぐらい安く出て、これを使わないともうからないんだという、そういう部分の値段の設定なのか、そこのところをちょっと聞かしていただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"公共工事の利用については、６の１のところに書いておりますように、公共工事に使用する場合については別途協議ということで、これは政策的に入れようということですから、この間に利用する側と、現在は東京二十三区清掃一部事務組合から排出されますから。","id":"exchange-008"},{"speaker":"横山委員","kind":"質問","question":"一般よりも安くということでは、無料でということですか。それが結局下水道の詰まりなどにつながっていくという、いろいろなところに思いが発するものだから、比重がどういうふうかということをお尋ねしました。","respondent":"松本環境清掃事業部長、中山清掃リサイクル課長","answer":"公共工事ですけれども、この基本的な考え方は、この基準を定めたそのものが、できるだけ埋め立ての量を減らしていこうということが根底にあります。要は、一定密度以上ということですから、水よりは１.５倍以上重い状態になっているものという基準になってあります。","id":"exchange-009"},{"speaker":"横山委員","kind":"意見","question":"砂よりも軽いということ、その点を聞きたっかんです。さっきの用途の部分でね。そういう心配があるなというのと、これがどのぐらいの生産量になってくるのか知らないけれども、これを使っていくとすると、品川区が私道舗装をやるとき、かなり制約をかけている。それより相反した形での品川区の私道舗装のやり方だから、委員会が違うから結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"違う観点から言うと、現在民間の砂を扱っている業者がいらっしゃるわけで、そういう業者に対しては、官が民を圧迫するようなことにつながるので、それで一般市場等の価格との兼ね合いで価格を設定していくものだというふうな理解を当初していたんですが、今のご説明では、ちょっと違うご説明だったんですが、再度お伺いをしたいと思います。","respondent":"松本環境清掃事業部長","answer":"スラグを使う場合にはただということになりますと、この格差が大き過ぎる。その辺を少しバランス的に考えていこうです。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"ですから、コストが幾らかかろうが、延命につながるのであれば、それはその時点でコストがかかったことの意味合いは十分果たしていて、そこから生まれた二次的な産物を活用できるということであれば、積極的に、事前のそれまでの経過の中でコストが幾らかかっていようが、そちらにコストを転嫁するというのは、そもそものスタートが違うのではないか。","respondent":"中山清掃リサイクル課長","answer":"民業を圧迫とかという面も考えなければいけないと思うんですけれども、実際に流通、買っていただいて、利用できるコストというものは市場を見ながら決めていくという形に現実的にはなっております。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"ですから、単に需給バランスではなく、一般の市場動向も、ここには書いてなかったので、そういうものも見据えながらも、また有効活用をしていただくほうにつなげていただきたいという意味なので、ご理解いただきたいと思います。","respondent":"松本環境清掃事業部長","answer":"議論の中ではそういう主張もありましたし、できるだけ使ってもらえばただでもいいじゃないかという意見もありました。検討経過の中でそういう結論に至ったということだけはご承知願いたいと思います。","id":"exchange-013"},{"speaker":"辻委員","kind":"質問・要望","question":"平成１４年に板橋清掃工場の一部で、この中でできたスラグの含有量はどういうふうになっているのか、教えていただきたいと思います。","respondent":"中山清掃リサイクル課長","answer":"平成１４年１２月１９日に試験検査をいたしまして、含有量基準ですと、カドミウムが９mg以下の基準に対して０.０００５mg未満ということで、ほとんど検出できない。それから、鉛が６００mgですけれども、１８mg。","id":"exchange-014"},{"speaker":"辻委員","kind":"質問・要望","question":"このスラグ自身の出し方を見ると、家庭から出るごみを燃やして、それを１,２００度に処理してできるものですね。これは正確につかんでいただきたいということ。これはインターロッキングをやられて、子どもたちが遊んだりしたときに、何なんだとかじゃないんだという、これは一つ、こういう書き方、説明のあり方というのは、どう考えるのか、お考えを示していただきたい。","respondent":"中山清掃リサイクル課長","answer":"確かにこれからいろいろな場面でＰＲ、具体的に流通する際に、これまでは基準ですけれども、まして市場にという段階になると、そういう誤解のない、通常あるものが安全基準以下ですよという説明をきちんとした資料なり、説明の仕方を心掛けていくようにしてまいります。","id":"exchange-015"},{"speaker":"辻委員","kind":"質問・要望","question":"まさしくこれは、例えばどういう出し方をするのかわからないですけれども、袋だったら袋、まず原材料を出していく格好をするんでしょうけれども、そのときに内容証明書を出すべきではないかなと思うんです。５年間保管するということですから、一区民から、この公園であそこにインターロッキング式でどうなんだと言ったときには、これについては安全的にも使っていますという、この辺をもう一回お願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"今の関係で、伺っていて、確認したかったんですけれども、重金属等の含有量基準という、カドミウム９mg以下、こういう数字というのは国際基準なんですか、日本の基準なんですか。","respondent":"中山清掃リサイクル課長","answer":"国際的にこういう土壌の基準がどうなっているかということについては把握してございませんが、当然、国際的にも問題ない基準を国として定めているものであると思いますけれども、この数値そのものは当時の環境庁で定めた数値です。","id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"例えば大気中にあるダイオキシンの問題とか、そういうものも日本の基準というのは外国とは全然違う、ひどい状況が現実的にありましたよね。ですから、そこのところは心していかなければいけないと思いますので、改めて私も調べたいと思いますけれども、もし何かの機会で分かったら教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"石田副委員長","kind":"質問・要望","question":"そのシミュレーションをやったから、有償とか、例えば公共工事については、さっき埋め戻しという話もあったけれども、そういうことが出てきているんだと思うんだけれども、全体１,１８０ｔになったときに、日量それが出てきて、全然埋めないでスラグとしてどこかへ使うというような計画というのはどこで組まれて、どういうふうに。","respondent":"中山清掃リサイクル課長","answer":"逆に、そういうことを考えると、当然有効利用が促進される方針、考え方、先ほど来申し上げているような、安心して使っていただける基準、説明、このようものが必要だということで、この方針が出たです。","id":"exchange-019"},{"speaker":"石田副委員長","kind":"質問","question":"たまたま埋め戻しというのがあったのかもしれないけれども、これは確実に捌けていく計画になっているのか、６月から多摩川清掃工場３０ｔで、２１０ｔ出てくるわけですけれども、ここら辺まではもうすぐだから、ここら辺が２１０ｔ毎日捌ける計画ができているのか、できていないのか、そこを教えてください。","respondent":"松本環境清掃事業部長","answer":"それが全部使ってもらえれば確かにはけるかと思いますけれども、今の状況ではまだそこまで目処が立っていないというのが実際です。できるだけ今後こういう形で普及啓発をして、各区にもできるだけ使っていただこうということで、今働きかけている最中です。","id":"exchange-020"},{"speaker":"石田副委員長","kind":"質問・要望","question":"伺うと、今やっているとか、今から普及啓発をするという話なんだけれども、それは非常に遅い話じゃないのかなと私は思っていますし、長く使おうということであれば、そこら辺のところは前もって準備をして、公共事業の埋め戻しなどというのは分かっていることだし、民間の建物でも埋め戻しなどというのは、それをどうやってやっているかというのは分かっていることで、あるところに山をつくって。","respondent":"松本環境清掃事業部長","answer":"そういう意味で東京都の指針です仕様書の中に盛り込む働きかけを１点はしています。それと同時に、板橋清掃工場ですので、板橋区の土木部に対しても働きかけをやっております。そういう形でできるだけたくさん使っていただくような努力は私どもはしてきたつもりです。","id":"exchange-021"}]},{"id":"topic-02","title":"続きまして、２の特定事件調査","agenda":"続きまして、２の特定事件調査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"集団回収のところに入る前に、前文のところで一つ意見なんですけれども、前回、新しいリサイクルカレンダーをいただきました。中身が凄く充実しているので、これが活用されることがリサイクルの意識向上ですか、リサイクルがさらに進むということで、本当にこれが活用されたらいいなと思っているんです。住民との協働でいろいろな解決をしていくというシステムをとっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"古着と廃食用油はここでしかやっていないですよね。だから、凄く貴重な場だと思うんです。もう１点は、生ごみのリサイクルの検討というので出ましたけれども、その他のところのリサイクルの拡大に入るんでしょうか、ぜひ生ごみをごみじゃなくて資源と考える意識を大きく持っていくという意味では、生ごみのリサイクルの具体的な検討を進めていくというようなことで載せていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"川西委員","kind":"質問","question":"審議会の中で不燃ごみの減量化についてはどんな意見が出たのか、お伺いしたいと思います。もう一つ、説明の中で、減量対策として家庭ごみの有料化の意見が出されたというような話ですけれども、ほかの問題を先おいて家庭ごみの有料化が減量に本当につながるんだろうかというのをどういうふうにお考えでしょうか。","respondent":"中山清掃リサイクル課長","answer":"審議会のご論議ですので、あまり踏み込んだご説明は難しいのですが、根本的な分別の有り様というのは、例えば清掃工場の機能というものも、今後方針が出たものを視野に入れながら考えるべきではないかというのが当初ございました。","id":"exchange-024"},{"speaker":"川西委員","kind":"質問・要望","question":"この委員会で中央防波堤を見させていただきまして、大変勉強になりました。発生源対策があるんですけれども、毎日の生活の中で不燃ごみが増える一方、可燃ごみは、溶融スラグの問題も含めて、減量対策というものが、啓蒙活動の効果でしょうか、やや私たちの周りでも減ってきていますし、工夫が比較的容易であるというふうに思うんです。どこかに加えていただきたいということが、私の意見です。","respondent":"中山清掃リサイクル課長","answer":"プラスチック製容器中心に、本来リサイクルができるものが、今は不燃という形になっているので、先ほど申し上げた、工場の機能を含めてどうなのかということは考えていくべきだと思います。","id":"exchange-025"},{"speaker":"川西委員","kind":"質問","question":"ちょっとご答弁が漏れていた点が、ペットボトルの回収場所の拡充という点について、いかがでしょうか。","respondent":"中山清掃リサイクル課長","answer":"先ほど口頭の説明で申し訳なかったんですが、集積所の拡大という中に、現在ペットボトルは店頭回収が主ですが、拠点が一番ですけれども、ここは大きな課題になってくるという、当委員会でもご意見があったかと思いますけれども、同じように。","id":"exchange-026"},{"speaker":"嶋委員","kind":"質問","question":"エコボックスの回収でお聞きをしたいんですが、これは時間に制約されず、いつでも出せるというのは凄くうれしいことですが、回収単価が高くなっている。品川区の中で駅頭とか、商店街でそういうのを置いて、人を集めていくということがあると思うんですが、どのぐらいあるんでしょうか。","respondent":"中山清掃リサイクル課長","answer":"エコボックス自体は現在は区内２８カ所に設置しております。","id":"exchange-027"},{"speaker":"上山委員","kind":"質問","question":"まとめの中のその他のところで、三つ目に、「事業系資源の清掃事務所回収の有料シールの扱いを検討する必要がある」とありますが、これはどういう意味だったか、意味がよくわからなくなったので、お聞きしたいと思います。","respondent":"中山清掃リサイクル課長","answer":"それが同じでいいのかと。事業者だからといって、資源回収をしようという努力を、有料シールということで意欲をそいでしまうということにならないのか、これは研究すべきじゃないか、こういうご意見がありました。","id":"exchange-028"},{"speaker":"上山委員","kind":"質問・要望","question":"やはりそういうのはいいと思っていないわけなので、区民の協力が必要だと思いますので、最初のどこに書いたらいいかわからないんですが、書けるのであれば、全体のまとめの前のほうの文章の中か何かに、たとえばですが、区民の意識調査みたいなものを、協力を求めるみたいなことがないと、別に若い人ばかりでないように私は聞いたもので、若い人だから。","respondent":"金井環境課長","answer":"今年度は環境課で商店、工場、一般の区民全体、それらも含めて、環境だけの調査を実施をいたしました。区民委員会にはご報告しておりますけれども、こちらではご報告しておりませんが、一応今年度は緊急雇用のお金もいただきまして、大々的にやっております。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、そういう意味で、もう少し具体的な一人ひとりの認識をさらに飛躍させるための意識調査をやったらどうかという、そういう趣旨の意見だというふうに私は思うんです。やはり現実的にはそういう状況がまだ一般的なんだろうと思うわけです。したがって、１０月にはこういう項目で丁寧には書いてあるんですけれども、そこをもう少しかみ砕いて、全区民対象にやっていただきたいなというのが一つ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"川西委員","kind":"質問","question":"これのまとめですから、委員会のまとめですね。ですから、意見があるんですけれども、郵便局の利用者というのは、一般の住民の方が、世代を越えて、銀行よりも利用する。ペットボトルの回収場所の拡充というところに、ぜひ郵便局の入口を入れていただければと思います。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"ちょっと確認だけしたいんですが、先ほどのまとめをする際の、特定事件調査の冒頭に、廃棄物減量等推進審議会も同様の審議を行っているので、その推移を見ながらという、あまり突っ込まずにというようなニュアンスのお話しがあったというふうに受けたんですが、審議会のほうは区長の諮問機関ということですので、私の理解が間違っていたのかもしれませんが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"家電リサイクル法が施行されて、まち中の不法投棄の現状を教えていただきたいんです。私のところは電気屋という商売をやっているんですけれども、小さい電気器具でも五千幾らという、１万円台、２万円台ぐらいのものだから、相当リサイクル料金がかかってしまうので、ああいったものの不法投棄が現状でどうなっているのか。そういうものを役所で負担を余儀なくされていると思うんですけれども、現状でどうか。","respondent":"中山清掃リサイクル課長","answer":"このときに不法投棄も多かったんですが、平成１３年度はかなり買い替えも含めて、家電法の駆け込みにより抑制があった。平成１４年度はそれが平準化してきているのかなと。買い替えにあたって、総数がこのときも増えつつあるのかなというふうには認識しています。","id":"exchange-033"},{"speaker":"横山委員","kind":"意見","question":"心配する動きなんだけれども、今半減しているとか、減少傾向という言葉は分かるんだけれども、台数で聞かしてもらわないと、もともとの数字が幾つで、それに対して半減しているという、頭の中で整理できないので、どのぐらいの台数、それぞれ四品が分かればお願いいたします。","respondent":"中山清掃リサイクル課長","answer":"いずれにしましても、平成１２年度においては１２月段階で３６０台になっておりましたから、１年間を通じても２００台弱ということで、半減です。今申し上げた、１年間に２００台というペースだったものが、平成１４年度は１２月までの段階で三十～四十台増えております。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"後でいいですが、できたら、冷蔵庫は幾つ、テレビは幾つ、洗濯機が幾つ、クーラー幾つというような数が分かると大体の傾向が分かりますので、教えていただきたいと思います。もう一つ、ビルなどの取り壊しなどが今凄くまち中でされているんだけれども、産業廃棄物業者がいますね。ああいうのはどういう形で受け入れているのか。","respondent":"中山清掃リサイクル課長","answer":"建設リサイクル法の実施について、昨年５月に建設委員会で建築課のほうよりご報告をしていますけれども、昨年５月３０日から建設リサイクル法が施行されました。","id":"exchange-035"},{"speaker":"横山委員","kind":"質問","question":"その先でされているのな、受け入れるところにちゃんとそのようにされているのかなと、ちょっとその先が心配になるというか、どういう状況になっているのか知りたかったものですから、お聞きさせていただきました。今もそういった中で行われているものだと思いますけれども、一応お尋ねだけさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/654244?Template=document&Id=5680#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":31544,"voices":77}},{"id":"h15-20030122-16","meetingId":"h15-cm01","date":"2003年1月22日","dateIso":"2003-01-22","committee":"街づくり特別委員会","time":"午後１時０８分～午後３時０６分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","topics":[{"id":"topic-01","title":"補助２０５号拡幅事業進捗状況と電線共同溝地中化事業","agenda":"補助２０５号拡幅事業進捗状況と電線共同溝地中化事業","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"ちょっとおさらいの意味で知りたいんですけれども、２０５号線の総事業費と、それから、いろいろ用地買収の面積はわかりましたけれども、地権者の状況を知りたいんです。今、手元にあれば教えていただきたいんです。ちなみに、土地所有者、借地、借家、あと店舗、営業されている方。そのあたりの状況を知りたいと思っています。","respondent":"中島街路事業担当課長","answer":"この中には、例えば先ほど言いましたように、大地主の方がいらっしゃいますので、１人の地権者が１０軒、２０軒分に関係しているということがございまして、全体とすれば３５件ございまして、大体８０人から９０人ぐらいの方が権利者としていらっしゃるかなと考えています。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問","question":"３５件のうち、今、お話があったように、店舗をやっている半数の方というのは、ほとんど借家、借地ですか。","respondent":"中島街路事業担当課長","answer":"いろいろな方がいらっしゃいます。自分で土地を持っている方もいらっしゃいますし、借家の方もいらっしゃいますし、借地権を持って建物を所有しているという方もいらっしゃいます。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問","question":"そういうときに、今現在、１６３号線の問題もそうなんですけれども、区として、例えば、店舗を持っている方に対しての対応というのはどういうふうに考えているんでしょうか。２０５号線も、区のものですよね、１６３号線と同じですよね。ですから、そこでの困難性を抱えている中で、この３５件はいろいろな内容があると思うんですけれども、どういうふうに考えられているのか。","respondent":"中島街路事業担当課長","answer":"そういった意味では、一概にこういうパターンが多いですとかは言えませんけれども、さまざまな方法を、権利者の方と相談させていただきながら、生活再建するのに、権利者の方にとってどういう形がいいのか、意向ももちろんありますので。","id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"分けられないのかもしれないんですが、ちょっとそこらがわかったら教えてほしい。それから、どこだって共同化したいと。そうすると、その判断はどこでやるのか。要するに、財源構成との兼ね合いなんですけれども、ちょっと総事業費と共同化、地中化がどれぐらいの割合かということと、総事業費の財源構成はどうなっているのか。そこら全般の仕組みを、ちょっと教えてほしいんです。","respondent":"中島街路事業担当課長","answer":"２０５号線と１８号線、３０号線、３２０号と１６３号線とありますけれども、都市計画道路につきましては、基本的に整備する段階で、電線類の地中化をすべてしていきたいと考えています。","id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"そうすると、残る２分の１は都市計画交付金になるのかしら。財調ではないですよね。それが一つ。それから、実際にこの共同溝に東京電力の電力線が入りますね、ＮＴＴは入るけれども、そのほかにどんなものが入るんですか。それだけなんですか。","respondent":"中島街路事業担当課長","answer":"現時点で、財源の部分でいきますと、２分の１は国庫が入りますけれども、それ以外につきましては残りの２分の１のうち４分の３が財調対象、４分の１が都市計画交付金の対象となっております。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"これは素人判断なんですけれども、例えば下水道と共同溝にして一括してやるようなことはできないんでしょうか。下水道をやって、終わったら、その後今度は電線の地中化だとかって、二重、三重の負担になっちゃうんじゃないかなという気がするんですけれども、その辺はいかがでしょうか。","respondent":"岩田管理工事課長","answer":"いわゆる共同溝というのは、国道なんかに設置しておりますけれども、あれはほとんど車道の真下に巨大なカルバートみたいな、人が入れるような、場合によっては電気機関車が入るような共同溝で、そこにはガス、水道、電気。","id":"exchange-006"},{"speaker":"中島委員","kind":"質問","question":"先ほどの桜井委員の質問にちょっと関連しているんですが、今、借地で借家でお店を借りているという方たちもいらっしゃるわけですが、当然、立ち退きに当たっては店舗を移転したときの顧客損失とか、そうした部分も補償されているようなんですが、これは大体何年ぐらい先までの見通しをされているんでしょうか。お店をどこかに移しますよね。そうした部分なんですが。","respondent":"中島街路事業担当課長","answer":"ただ、それにつきましては、数カ月という単位で、今、現在どのぐらいの営業があるのか、売り上げというんですか、そういったことをもとにして計算して、半年分ぐらいというのが通常の補償です。","id":"exchange-007"},{"speaker":"中島委員","kind":"質問","question":"それともう１点は、かなり高齢になって、今まではお店を経営されてきている。ですけれども、今のところにいれば、店舗もあるわけですから、生活は安定していくんですが、ここから補償金をもらって出て、ほかのところにお店を出すだけの気力はないとした場合に、その先の生活というものがどの程度まで補償されるのか、その辺のところをちょっと。","respondent":"中島街路事業担当課長","answer":"そういった部分では、例えば借地の方、借家人の方もいらっしゃいますけれども、そういった補償金をもとに、今後の生活の再建の仕方というのも検討していただけるようになるのかなと考えています。","id":"exchange-008"},{"speaker":"中島委員","kind":"質問","question":"その場合は、そういう細かいところまで少し話し合いをする余地があるんでしょうか。","respondent":"中島街路事業担当課長","answer":"そういった意味では、あらゆる形で相談に応じしています。","id":"exchange-009"},{"speaker":"中島委員","kind":"質問・要望","question":"そうした場合に、年齢であるとか、家族構成とか、いろいろ考えたときに、この金額ではちょっと、今後この方たちが困るんじゃないかと思われるような相談も受けたものですから、その辺のところを、また再度、相談に乗ってあげていただきたいなと思いますので、要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"塚本委員","kind":"意見","question":"用地買収から道路整備のつながりぐあいなんですけれども、どう見ても用地買収が終わって、早く道路整備してほしいなと思って、我々は、どうしてこんなに間があくんだろうと、当事者もそう思っていられると思いますが、その辺の手続とか、ネックとか、考え方を聞きたいんです。そういうことが可能かどうかということが一つ。この期間がどのぐらいあいて、その間、何をしたのか。","respondent":"中島街路事業担当課長","answer":"ですから、現在、Ｉ期区間につきましても、大体２００ｍの区間でやってあります。今回も約２００ｍです。来年時実施区間につきましては、大体、北側１２０ｍ、南側１６０ｍですので、そういった目安でやっております。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"Ｉ期工事の小野学園の上のほうは、もう買収が終わって随分経っていますね。それから、今、理由の中に、地下の埋設物と他の事業の予算系というお話があった、いろいろなこともかかわってくるというような答弁で、下水道とかそういうものも関係してくるんだというお話でしたが、その辺の何がネックかということを、予算なのか、各省庁との連絡、あるいは仕事の取り合わせが問題なのか、ネックを列記してほしい。","respondent":"岩田管理工事課長","answer":"先ほど、街路事業担当課長がご説明したのは、あそこは、６ｍを切るような現況の幅員の道路のところを、１５ｍの幅員に一発で広げるので、１５ｍに広げた場合も、下水道管はちょうど真ん中に持ってくるようにします。","id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"くれぐれも、行政機関の内部の調整のおくれで工事がおくれることがないように、見通しを持ってネゴシエーションをしっかりしてほしいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"三上委員","kind":"質問・要望","question":"ここらあたり、あまりに突然であり、また２月の都議会で可決されればなんて、かなり準備が進められているんじゃないかななんていう感じがするんです。きょうは視察に出かけますので、時間がなければ、次回の委員会ででもきちっと報告していただきたいと思いますけれども、若干、わかる範囲ででもご説明いただけますか。","respondent":"山室住宅指導担当部長","answer":"この新聞報道によりますと、都の第１回定例会で建築安全条例を改正して、新しい制度を盛り込んでいきたいと。私どものほうには、まだ概略しか説明がありませんが、それを簡単にご説明しますと、知事が新しい制度を指定することができる仕組みを考えています。","id":"exchange-014"},{"speaker":"三上委員","kind":"意見","question":"時間がありませんので、今後の問題として大事な防災まちづくりという観点から考えても、そういう意味にあって、正副委員長にお願いして、今後、そういういろいろな状況のことで検討することが出てきたら、当委員会でお話ししていただければとお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１１月のこの委員会の中で出た、大崎駅西口の開発の中地区の保留床の買い手の件なんですけれども、年明けには具体的な会社名について報告ができるんじゃないかというご答弁をいただきましたので、そのことについてお聞かせいただきたいと思います。","respondent":"南雲都市開発課長","answer":"今、具体的に２社ほどの会社と絞り込みを行いまして、今、準備組合のほうで最終的な事業登録を行う上での条件について詰めているという状況です。その条件が確定いたしましたら、具体的な会社名をご報告していきますけれども、もうしばらくお待ちいただきたいと思います。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"前回の１１月の委員会でもそれと同じような中身で、ほぼ決まって、年明けには具体的な報告ができるというご答弁をいただいているんです。もう少しということでしたら、じゃあ、見通しはいつぐらいでしょうか。","respondent":"岩野まちづくり事業部次長","answer":"１１月の本委員会でご答弁申し上げましたのは、事業協力者、フジタとアズマということですが、それと一緒にやる事業協力者を準備組合のほうで探していまして、それが大体、条件的にめどがついたですので、具体的な条件を詰めるとともに。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"前のときにも、そういうふうに総会で確認されて正式に決まったらということだったんですけれども、その総会がまだやられていないということで、では、具体的に決まったら、またご報告をよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"沢田委員","kind":"質問・要望","question":"空室率ががっと増え、賃料が下がり、それでいわゆる２００３年問題ですね。きょうは時間がないので、できたら、品川区が絡んでいる開発の中での空室率と、オフィスの賃料、それから既にできたところの空室率がどうなのか。だから、わかろうと思えばすぐにわかるはずでから、わかる範囲でいいですから、ぜひ、当委員会に報告をしていただきたいと思います。","respondent":"岩野まちづくり事業部次長","answer":"次回という意味ですか。","id":"exchange-019"},{"speaker":"桜井委員","kind":"質問・要望","question":"これも次回でいいんですけれども、りんかい線の関係なんですけれども、都が１４６億円の損失補償ということで報道されていますよね。いろいろまちばでは、一体どういうふうにお願いされていて、区の税金なんかはどうなのかとかいう声も出ているんです。区のかかわり方としても、重要なところにあるので、全体像をちょっと教えていただきたい。これは次回でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/903397?Template=document&Id=6248#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":16476,"voices":62}},{"id":"h15-20030123-14","meetingId":"h15-cm01","date":"2003年1月23日","dateIso":"2003-01-23","committee":"行財政改革特別委員会","time":"午後１時０６分～午後３時２８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"す。 まず、継続となっております請願・陳情審査を行いまして、特定事件調査その他と進めていきたいと思います。 本日は２８名の傍聴申請がございましたので","agenda":"す。 まず、継続となっております請願・陳情審査を行いまして、特定事件調査その他と進めていきたいと思います。 本日は２８名の傍聴申請がございましたので","exchanges":[{"speaker":"鶴委員","kind":"意見","question":"前回いろいろいただいた資料で、未定というふうなところがあった、確定していなくて定数削減を行った議会も２３区内でもあるんじゃないかと思うんですね。去年の１２月も各地方で圧倒的多数の勢いで定数の削減が行われました。","respondent":"福田区議会事務局長","answer":"それから次は荒川区でありますが、３４人に対しまして３２人、それから葛飾区４６人対４６人、同数であります。江戸川区が５６人対４６人、このような状況です。","id":"exchange-001"},{"speaker":"鶴委員","kind":"意見","question":"議員定数削減の自ら議会の議員の良識に基づいて、あるいは法律に基づいての対応もあったというふうに思うんですが、いずれにしても陳情とか、あるいは請願という形が出てこなければ何もしないというような議会、あるいは時間がなさ過ぎるとか唐突過ぎるというような、そういうようなことをほかの議会で、そういう住民の理解を得ることのできないような、そういう言いわけをしたようなところはありますか。","respondent":"福田区議会事務局長","answer":"ただいまご報告を申し上げましたのは、その区の審議経過を踏まえて、私どもが聴取等によって把握をした状況でございまして、今委員がご指摘のようなことについてまで言及した、具体的に言及したというところは見られない状況です。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"都議会の場合は選挙区がありますので、また違いがあるのかもしれませんけれども、少なくとも２年とか３年とかかなり長期間にわたって論議をして、この議員定数の問題については決めていくという流れがあるそうですけれども、私ちょっと改めてこの間出ている時間的な問題にしても、陳情の内容の問題にしても、それから本質論、議会そのもののあり方の本質論、こういう問題にしても。","respondent":"福田区議会事務局長","answer":"さらに足立区におきましては、平成１２年第１回定例会の議決というような、かなり以前に議決をしているところがある一方で、例えば、杉並区におきましては、平成１４年第３回定例会の議決、それぞれその議会の個性と申しましょうか、進行状況あるいは論議の成熟度。","id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"今、事務局長が言われた論議の成熟度、これは最初の論議のときに出していただいた、８年前の状況というのがいろいろ出されていて、私は時間的な問題もそうですし、内容的な問題、それから本質論の問題、十分に全体で、区民の皆さんと一緒に論議をする、こういう成熟のさせ方が何よりもやっぱり必要なんではないかというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問","question":"ですから、そういうふうなここにいるメンバー以外の４２名の、ある意味そういう内容に係わる内容については、もう少し慎重に考えていく必要がある。ですから、繰り返しになりますけれども、時間的な制約が非常にあるということを私どもずっと感じております。ですから、方向づけになってしまいますけれども、その前提条件は今のところ変わっていないというのが私ども自民党の会派の考えであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"原委員","kind":"質問","question":"今、伊藤委員のほうからお話がありましたけども、全くそのとおりだろうと思うんです。行政がそれにどうのという話ではないわけですので、議会意思でもって、その定数を云々しなきゃいけない。それともう一つ、先ほどの関連のお話の中で、局長にお伺いをしたいんですけれども、平成１４年の第４回定例会で意思決定をしたというところは、何カ所あるんですか。","respondent":"福田区議会事務局長","answer":"間違っていたら申し訳ないんですけども、そういう点で申し上げますと、１、２、３、４、５、６、７、８、９、１０区であろうかというふうに思われます。","id":"exchange-006"},{"speaker":"原委員","kind":"質問","question":"先ほど局長がお話しされていた地方自治法改正による法定数の改正と、それから社会情勢云々という話と両方出ていますが、何区が地方自治法の改正に沿った改正なんですか。","respondent":"福田区議会事務局長","answer":"名前を申し上げます。中央区、港区、新宿区、文京区、台東区、それから渋谷区、それから豊島区、それから葛飾区であります。６区であります。ちょっと訂正します。１区、２区、３区、４区、５区、６区、７区、８区であります。すみません。","id":"exchange-007"},{"speaker":"原委員","kind":"質問","question":"今後の中で、もう一つ局長にお伺いしたいんですけれども、行財政改革特別委員会でそれをはっきり決めて表に出さなきゃならないような場合には、手続的なものがありますよね。今後の中で、しっかりその手続が踏める時間があるのかないのかということだと思うんですが。わかる程度で結構です。","respondent":"福田区議会事務局長","answer":"すみません。手続、条例定数に関する手続のお話でしょうか。条例改正の手続。〔「周知」と呼ぶ者あり〕周知徹底のお話ですか。周知徹底につきましては、これから始まろうとしております第１回定例会の議決、これを踏まえれば、その後が周知期間になるというふうに考えております。","id":"exchange-008"},{"speaker":"原委員","kind":"意見","question":"あくまで手続的には周知徹底をするところまではいかないんではない。私たち自民党としては、行財政改革特別委員会で議員定数について論議することはやぶさかではございませんけれども、今ここの時間の中でその結論を出していくというのは、非常に困難な作業をしなければならないのではないかというふうに思っておりますので、それは今後の中の参考にしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"堺委員","kind":"確認","question":"ただ、前回、昨年の１１月１２日、また１１月２８日の行財政改革特別委員会のときにも確認したかなと思ってはいるんですけれども、そもそもこの件については、陳情が出されてから、あるいは陳情が出されたから検討する、そういう趣旨の性格のものではなかった。どういう理由があったかわかりません。ですから、極論かもしれませんが、第１回定例会が２月から３月にかけて始まります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"鶴委員","kind":"意見","question":"例えば、この陳情書、昨年１０月１１日に定数４人を削減しなさいという、これもお一人の方から出たとしても、たった一人の意見ではないということですね。その人はどう答えるのか、その声に。平成６年のときに、あれだけ１年の間に都合９回、そしてそれぞれの政党の意見というのがある。変えてはならない。だから、明確にこの議会で、この陳情については結論を出すべきであると、こういうふうに私も思います。","respondent":"福田区議会事務局長","answer":"大変申し訳ございません。先ほど第４回定例会における議決が１０区というふうに申し上げましたが、ちょっと私勘違いいたしまして、正確には港区と豊島区、この２区です。大変申し訳ございませんでした。","id":"exchange-011"},{"speaker":"原委員","kind":"質問","question":"今、お話がありまして訂正されましたけれども、確かに第４回定例会ではそんなにやっていなかったなという意識があってお話を聞いたわけですけれども、それは時間的な割合の部分をお伺いする材料にさせていただいたです。例えば、この議員定数にしても、４８人を４４人にし、４４人を４２人に、時間的な経緯はあるものの、他区に先駆けて議員の定数の削減をしてきているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鶴委員","kind":"質問・要望","question":"だから、結論をやっぱり出すべきだ。４月の選挙からやれと求めていらっしゃるわけですよ。そのことが求められているんですよ、今。だから、私たちは、１０月の時点でこういうご指摘を受けた、ご提言を受けた。時間は短いですが、しっかりやっていきましょう、このぐらいの姿勢があってこそ、ほんとうに区民のいろんな声に応えていく、生きた品川区議会だなと言われるんじゃないですかね、私はそう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今、直近に私たち議員がなすべき仕事は何かというと、品川区議会の直接の仕事、日々さまざまにある品川区議会の議員としての責務を間違いなく１００％より以上果たしていくことが一番に求められている。それをまずするべきことが大事だと思っています。ですから、それがもし十分に円滑に行われていたならば、多分この陳情に書かれているような競争原理も働かずとか、その表現はなかったと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"藤田副委員長","kind":"質問・要望","question":"一方、今日議論しています陳情は、品川区議会議員定数を４人削減し、定数条例を３８人に改め、来春の区議会議員選挙から施行することを求めると、この趣旨なんですね。ですから、議会として何らかの結論をきちんと出していかないと、施行することを求めるんですから、これは時間があるとかないとかという話ではなくて、十分昨年の１０月以降我々議論をずっとしてきているわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"ですから、私ども、議員を減らして、議会の機能を弱めたら、これは逆行するというふうに思っています。ですから、私は前回も聞きました。時間の問題じゃなくて、中身だというふうに先ほどおっしゃっていましたけれども、それならば、私が前回質問したことに何で答えないんですか。この採択を主張するんであれば、これはこうだというふうに思うんですけど、どうでしょうか。これはぜひ公明党に聞いております。","respondent":"福田区議会事務局長","answer":"こちらは陳情です。したがいまして、紹介議員はございませんので、陳情のそれぞれのフレーズにつきまして、具体的な説明を求めることは若干無理があろうかというふうに考えられます。","id":"exchange-016"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"一つは、事務局長に質問しているんではありませんので、これは前回も質問しました。だれも答えませんでした。私はさっき言ったように、この採択を求めるんであれば、ここが一番の中心の論点ですから、このところで私はそういうふうに聞いたこともないと、見たこともないと、ですから、これを主張するんであれば、まず前回全く質問に答えていないこの問題を答えていただきたいということを言っているんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鶴委員","kind":"質問","question":"新人の人たちもそうですよ。そんなに陳腐な比較が通るんですかねというふうなこと。その人は、真剣だったかもしれないけども、多少何かちょっと的確かどうかわからないみたいな言葉がついているから、あれじゃないですかというふうにお話ししたことがありますけども、いずれにしても、例えば議員定数が大きければいい、少なければいいと、今日の新聞報道でありますように、埼玉市は１００人から６４人ですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"それはその問題と議員を削減して、スリム化して活性化した問題、これは全く別問題ですから、ここのところは整理して考えていただきたいというふうに思います。でも、その声の裏側は、もっと議会をちゃんとやってくれよと、そういう気持ちが裏側にあるんですから、ここのところもよく意見をくみ取らないと、表面に出てくる言葉だけ聞いていたら、公明党のような主張になるかなというふうに私は感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鶴委員","kind":"質問・要望","question":"議会の、品川区議会のお仕事はということで、小学生にも中学生にもわかるように、パンフレットにはちゃんと書いてあるじゃないですか。そんなことは当然やった上で、今緊急にという意味だというふうに思うんですよ、求められているということは。先ほど副委員長の立場にある宮崎委員もおっしゃったように、議会の議員が多過ぎるという話も聞いたと、現実に聞いていらっしゃるんじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"意見","question":"今ね、私何回も同じことを言いますけれども、鶴委員は、先ほどからいろいろ言いますけれども、私は議会のスリム化による活性化、これは一体どういうことがあるんだということを聞いているんですけど、それについては一言も答えがありません。私はこれも改めて聞く機会があったら、いつか聞きたいものだというふうに思いました。ちょっとこれでやっていると長くなりそうなので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"鶴委員","kind":"意見","question":"一言も言っていないなんて、そんなこと言わない、断定的に。言ったじゃありませんか。競争原理はこういうことで働くということをね、あるいは、自分も切磋琢磨していかなきゃいけない、自己錬磨もしていかなきゃいけないということになるということを説明したじゃありませんか。一言も説明していないのではありません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"原委員","kind":"意見","question":"今のお話ですね、大事なお話かもしれません、それぞれのお立場に立てばね。でも、この中で、やっぱりこれは一応どういう形にするかというのは、もう少しほかの人の意見も聞かなきゃならないし、それから時間的なものもありますから、その辺のところを配慮して、議事進行してください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"佐藤委員","kind":"質問","question":"法定定数を上回っているんであれは、先ほど局長から説明があったように、それぞれその法定定数に最低限合わせる条例改正は必要なんでしょうが、品川区の場合は、既に４６名の法定定数を４名下回って４２名、条例改正の必要もないというような状況ですから、私としてはこの請願の内容は必ずしも賛同はできないという立場、前回も申し上げておりますので、ダブりますけども、一応そういう私の考えです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"金高委員","kind":"質問","question":"ですから、もっと踏み込んだ各論の部分、ほんとうにそれが一人減らすのか、二人減らすのか、今回は陳情でもって４人ですけど、ほんとうに４人がいいのか、４人になったときに、ここに出ている効果として、果たして議員がどういう形でもってできるのか、その辺のところがまだちょっとよく見えていないような感じがいたしましたので、その辺について、ちょっと意見を述べさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"本多委員","kind":"質問・要望","question":"当時は、平成１３年度では取り上げられなかったんですが、やはり、今後もそういった動きは必要ですし、現実的に、例えば今年の統一地方選挙の区長選の立候補説明会が２月１９日、区議については２月２０日でしたか、区の選挙管理委員会のほうも準備を進めている段階であると思いますので、自民党としては行財政改革を進めていく中では、当然積極的にやるという意思を意見として、例えば改選された議会に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"伊藤委員","kind":"意見","question":"私どもの会派といたしましては、今ずっとお話をさせていただいていますとおり、今日結論を出すのではなくて、継続の取り扱いをお願いしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"堺委員","kind":"意見","question":"私は結論を出すということで、取り扱いについてはお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"堺委員","kind":"意見","question":"先ほどもちょっとお話が出ておりましたように、また、私も、あるいは鶴委員もおっしゃっておりましたように、一つは、昨年の１１月２８日請願第２５号、これは現行４２人を守る請願については、不採択という取り扱いになっております。したがって、今論議されましたこの陳情、４人削減し、条例定数を３８人に改め云々という、この陳情について私は採択すべきであると、こういうふうに思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"菊地委員","kind":"意見","question":"今回も同様に、今日の論議の中で時間の問題やら、内容の問題というふうに出されましたけれども、私は今回の陳情について、改めて不採択にすべきという流れで決をとるというふうにしていただければというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"金高委員","kind":"意見","question":"私ども、先ほど意見を述べさせていただきましたけれども、やはり、この人数ということにしばりを入れますと、はっきり言って、行財政改革の中で人数、どれがほんとうにふさわしいかという論議は一切されていなかったような気がいたします。したがいまして、この件については、やはり継続という形でもってやっていきたいというふうに思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"佐藤委員","kind":"意見","question":"大体結論が出たようですけども、私が何を言おうとあれですが、前回私どもはこの陳情に対しては賛成できないというふうな発言をいたしております。したがいまして、本日結論を出すと。内容については反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"菊地委員","kind":"意見","question":"委員長、すみません。今、不採択ということで主張しましたけども、自民党ですとか民主党、こういう流れの中で継続という流れもまたあるということで、継続という流れの中で改めて主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"菊地委員","kind":"質問・要望","question":"もう一つは、学校給食の点について述べられているんですけれども、この点は、この間ずっと学校給食が業務委託をされてきて、私どもの飯沼議員が一般質問の中で、全園が民間委託になったときに、実際にはこの業務費、委託費もはね上がっている、こういう意見なんかを述べさせていただいたことがあるんですけれども、目先の、この行財政改革特別委員会が始まったときに、人件費が半減をされた。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-02","title":"続きまして、2)の行政サービスとＩＴ化","agenda":"続きまして、2)の行政サービスとＩＴ化","exchanges":[{"speaker":"伊藤委員","kind":"意見","question":"すみません、すぐ終わります。先ほどやればよかったんですが、行財政改革特別委員会のまとめについてはこのとおりで結構です。私どもが言いたかったことで強調します。そういうことを正副委員長としてまとめてくださったと考えていますので、そういうところまでぜひ読み込んでいただいて検討していただきますようにお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"伊藤委員","kind":"確認","question":"その後段のほうで、ちょっとだけ気になったのが、となれば、区民以外の方が区民になりすまして、言葉がおかしいですけどもね、登録することもできる可能性があるわけですよね。となれば、現場でどういうふうな確認をするのかということをもう一つ教えてください。そういう厳しい現状もあったということ。ですから、将来的な構想になってしまいますけど、あわせてお答えいただければと考えています。","respondent":"田中情報システム課長","answer":"２点目のＩＣカードの利用、それから端末の整備等の話ですが、ＩＣカードの利用については大変難しいところが、委員ご指摘のように決め手になるようなアプリケーションがなかなかない。魅力的な業務がないというところが大きな問題になっています。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"確認","question":"便利になる反面、こういうふうな、言葉を選んでいかないといけないですね。窓口の本人確認をしなさいとか、それは十分現場でやった上で、パスワードとか番号の管理をぜひお願いします。ですから、こういうふうな、これからＩＣカードなりを構築していく上に当たっては、当然品川区民も同じ可能性があるわけですから、ましてカードというのは私もそうですが、何枚も持っていらっしゃるわけで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"鶴委員","kind":"質問","question":"施設の予約システム等の一部を見せていただきました。そのことについては、どういうふうにして判断というか、チェックしていって、そういうことの後になってのトラブルを防止していく策というものを事前に立てておくのかどうかという点がちらっと便利な反面、そういうふうなことが懸念事項として頭をよぎったので、お伺いしておきたいというふうに思います。","respondent":"田中情報システム課長","answer":"これは４月以降になりますが、予約が平成１６年４月以降の予約受け付けに、１年前から受け付けるものですから、ちょっと実際の、平成１５年の４月では、平成１６年４月以降の抽選となりますが、運用としては今のきちっと窓口で適正な受け付けをしていくという運用については。","id":"exchange-038"},{"speaker":"藤田副委員長","kind":"質問","question":"すみません、教えてください。例えば土曜日とか日曜日とか、一気に申し込んじゃって、次に申し込みたい人がもういっぱいで、あれを見る限り、もうだめなんだなと、こういうケースが起きないのかどうか。早い者勝ちになってしまうんじゃないかなというふうに思うんですが、そういう心配はないんでしょうか。","respondent":"田中情報システム課長","answer":"スポーツ施設の予約は確かにテニスコートですとか、野球場ですとか、たくさんの申し込みがありますので、これは利用のたしか３カ月前だと思いますが、抽選でやります。抽選をやった上で、確定の期間を２週間ぐらい持ちます。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/229695?Template=document&Id=5724#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":30496,"voices":79}},{"id":"h15-20030228-3","meetingId":"h15-c-budget","date":"2003年2月28日","dateIso":"2003-02-28","committee":"予算特別委員会","time":"午後４時２２分～午後４時３０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"田中副委員長","kind":"意見","question":"ただいま副委員長の大任を仰せつかりました自民党品川区議団の田中豪と申します。今期４回目の予算特別委員会ですが、過去３回の委員会の経験をもとに、堺委員長を支えながら円滑な委員会運営に務めていきたいと思いますので、各委員の皆様方のご協力のほどよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/819589?Template=document&Id=800#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":2091,"voices":17}},{"id":"h15-20030303-6","meetingId":"h15-cm03","date":"2003年3月3日","dateIso":"2003-03-03","committee":"区民委員会","time":"午前１０時０５分～午後３時４５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を87件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私も、きのうニュースをテレビで見まして、夜のニュースとかでずっとやっていましたので、ほんとうに驚いたんです。この職員が、文化振興事業団に派遣されて業務を行っているということで新聞に書かれていますけれども、やっぱりこれを今回の報告だけに終わらせないで、文化振興事業団と言えばアルゼンチン債の問題もありましたし、きちっとこれからも調査をしていったほうがいいんじゃないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"平塚橋会館のこの間の利用状況について、一般の集会所としての利用と葬儀の利用の件数について、この間の流れというか、そこら辺のところを教えていただけますでしょうか。","respondent":"宮地区民課長","answer":"平成１２年度になりまして、集会所の利用が９８８件、葬儀の利用が１７件。平成１３年度は、集会所の利用が９３１件、葬儀の利用が２７件。ただいま、平成１４年度は途中ですが、１月末で、集会所の利用が９１１件、葬儀の利用が２９件となっています。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"集会所が、平成１１年度から１２年度にかけてずっと伸びていますけれども、集会所がもっと全面的に利用されるとなると、どれぐらいまで使えるものでしょうか。","respondent":"宮地区民課長","answer":"平成１２年度に約1,０００件になっていますが、これで１３％の利用率ですので、ちょっと逆算しますと、１万件以上の利用ができるはずだということです。","id":"exchange-003"},{"speaker":"三上委員","kind":"質問","question":"この際ですから、ちょっとお願いしておきたいんですけれども、駐車場がありますよね。使用申請を出した場合、利用者がどこまで借りられるんですかね。","respondent":"宮地区民課長","answer":"駐車場につきましては、こちらに住んでいらっしゃる方との関係で、基本的には使用できない形になってあります。どうしてもということですと、シルバー人材センターに委託しておりますので、そちらのほうの方が便宜を図ってお貸しすることができます。","id":"exchange-004"},{"speaker":"三上委員","kind":"意見","question":"あれだけの駐車場台数とすれば、普通の乗用車だったら１０台ぐらい無理すればとめられるでしょう。ときたま消防だとか、警察かなんかそんな官公庁の車をとめていたり、今、税務署が使っているけれども、税務署の車をとめているのかどうかわからないけれども、とにかく、見ていても、門扉を閉めちゃって、なぜ使用できないんだろうかと、やっぱり皆さんそう思っていますよ。","respondent":"宮地区民課長","answer":"今言われましたように、利用できる形について、ちょっと検討させていただきたいと思います。例えば一部有料とか、いろいろな方法がありますので、敷地の有効活用という点からも、少し検討させていただきたいと思います。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今のお話で、平塚橋会館だけじゃないですが、集会をやるときに、ほかの場所でもそういうところがあると思うんですよ。確かに利用を制限しているということで書いてあるんですけれども、使える部分をセンターの方の判断にゆだねてしまうと、そのほうがトラブルのもとになってしまうと思いますので、ここに限らず全体のところで考えていただきたいということだけお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"本田委員","kind":"質問・要望","question":"日曜日だったんですけれども。使えないというのも変だと思うんですね、スペースがあいているのに、施設を利用する方々の便宜を図るというか、どうしても車でちょっと物を運んだりすることはあるわけですから、そこのところはすべての区民集会所についてきちっと明確に、シルバー人材センターにその場その場でゆだねるんではなくて、はっきりして線を引いていただきたいと思うんです。","respondent":"長田地域活動課長","answer":"品川第二地域センターですけれども、確かにあそこには４台ぐらいとめられるスペースがあります。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと要望なんですけれども、地域の方から、何となく平塚橋会館の雰囲気が暗いというか、ふさがっているというようなイメージもあるのかもしれないんですけれども、暗いのと、何か寒々しているような雰囲気があるので、もうちょっと何か工夫をして、使いたいという雰囲気が出るようなことを検討していただけたらという要望が出されていましたので、ご検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"三上委員","kind":"意見","question":"その話が出たんですけれども、要するにメインになっていた斎場の二つの大きな部屋が、やっぱちょっと暗いんですよ。やっぱり暗いから、私だってどうしても使いづらいですよね。皆さんに聞くと、何か会合をやろうとしても、照度がちょっと暗すぎるんで、どうも会合向きではないということになって、大きな部屋が使いづらいんですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"松澤委員","kind":"質問","question":"区の収入源の中でたばこ税というのがありますけれども、これは扱っているたばこ商、自分たちが商売をしながら税金を納めながら、なおかつ悪者にされてはたまらんというようなことを聞かないこともないんですね。そのような中で、たばこ商組合なんかとの話し合い、そんなことはどのようになされているんでしょうか。","respondent":"長田地域活動課長","answer":"実は、この条例の施行をするに当たりまして、平成１５年度の予算のプレスの中で発表しています。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"今も話がありましたけれども、年２回ぐらい町会で地域清掃なんかをやっているわけですけれども、今度新たにこのような形で、歩行喫煙、ポイ捨てを禁止、罰則を取りますという形の中で地域清掃をしていく中で、地域美化ということで補助金も出ていますけれども、その補助金をある程度増額するとか、あるいは、地域清掃に当たって、特別にこういうことに注意してほしいとか、清掃の中で。","respondent":"長田地域活動課長","answer":"結論からちょっと申し上げますけれども、今のところ、平成１５年度につきましては、各町会自治会に出ている、これは連合町会単位で出てありますけれども、こちらも、補助金について増額する予定はございません。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"今、課長からいい言葉を聞きました、捨てられない環境づくりと。たばこに限らないんですけれども、よく商店街なんかですと、カラー鋪装に一番の敵はガムなんですよね。このキャンペーンとして、そういうこともやめましょうみたいなことができるのかどうか、たばこに限らず、そういうことまで踏み込んでいくのが環境に対する啓発かなと思うんですけれども、その辺はどうでしょうか。","respondent":"長田地域活動課長","answer":"これはタイルらしいんですけれども、タイルにべったりついたガムを取るのに、ケレンというんですか、ヘラみたいなものなんですけれども、それで一つずつやっていくより手がないというようなことで、これも１m2当たりの単価に直すととんでもない金額が出てくるということで。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前の審議のときに、罰則規定を設けていながら適用していない区というのが、新宿区、世田谷区、渋谷区、豊島区、足立区というところで、ほかのところは適用していないということでご報告を受けたんですけれども、ここのところは、何で適用していないのか、また、適用していなくても。","respondent":"長田地域活動課長","answer":"今現在実施をしているところにつきましては、千代田区だけだろうと思います。現在、品川区が準備を進めているということのほかに、もう一つ杉並区も、今回の第１回定例会で提案をするというようなことで、情報はいただいています。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"５区が罰則は設けているけれども、適用はしていないということなんですが、やっぱり罰則を設けただけだと、全くというぐらい、効果は変わりないということでしょうか。","respondent":"長田地域活動課長","answer":"ただ、私どもは罰則をもちろん規定をしまして、適用もする予定ですけれども、これはあくまでも罰則を科することが目的ではありません。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここでも、「悪質な違反者に対して行政罰である過料を罰則として適用する」となっていますけれども、悪質な違反者というのは、具体的にどういうことを悪質と言うんでしょうか。これが実際、全体で何人ぐらいが回るようになるのか、その具体的なところもちょっと教えていただきたいと思います。","respondent":"長田地域活動課長","answer":"後にお答えしますけれども、巡回指導員がかなり定期的に回るということで想定をしていますので、そういった中では、常習といいますか、前日に注意したのにまた次の日に吸っていたとか、そういった常習と思われるような人については、やはり過料で懲らしめというと。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"基本的には１回吸ったらすぐに罰金ということではなくて、１回吸って、そこで注意を受けて、注意に従わないということに対して罰金ということになるということでいいんでしょうか。考え方としては、こういうことになるのかどうかを、ちょっと一つ教えていただきたいと思います。","respondent":"長田地域活動課長","answer":"ちょっと歯切れが悪い答弁になるかもわかりません。これから検討していかなきゃいけない部分も含みますので、そういった形で答えていきたいと思うんです。例えば、この条例以外にも、道路上にごみを捨てるということにつきましては、道路法上の制限があります。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"では結局、決められた区域内であれば、吸ったというその行為だけでも罰則はかけられる条例だということで理解していいわけですね。わかりました。それともう一つ、第４条の２番の「自主的な地域美化活動を推進するよう努めなければならない」ということなんですけれども、これは区民の責務ですけれども、「自主的な地域美化活動に努める」というその中身についても、ちょっと教えていただきたいんです。","respondent":"長田地域活動課長","answer":"「密接に連携を」ですけれども、こちらにつきましては、まずこの条例施行に当たりましては、線引き等もしなければいけないというような形の中で、当然、線引きをした中で、過料の適用も含めて実施をしていくわけです。","id":"exchange-017"},{"speaker":"本田委員","kind":"質問","question":"日本政府はこれにどういうふうに対応していくのか、これから決まっていくわけです。2,９００万円の予算が出ているわけで、先ほど、６グループで１８人とありましたが、指定する場所は２カ所だけ固有名詞が出ましたが、これで言うと６カ所になるのかなと、６グループですから。それから、過料は具体的に何千円にするのか、１万円なのか、ちょっと具体的なことを聞きたいんです。","respondent":"長田地域活動課長","answer":"ですから、当面は合計４カ所ぐらいでスタートしたいと思ってあります。それから、過料につきましては、今後、規則で定めてまいりますけれども、事務局の思いといたしましては、たばこ５箱分ぐらい、1,０００円ぐらいでどうだろうかと思っているところです。","id":"exchange-018"},{"speaker":"本田委員","kind":"質問","question":"予算は計上しているわけですから、４カ所ということですけれども、名前が出せないのは、いろいろ調整が手間取ったということですか。その辺の調整がおくれているから、あとの２カ所は発表できないということなのかなと思うんですが、どうなんですか。","respondent":"長田地域活動課長","answer":"ただ、今のところ私どもで想定しているのは、青物横丁周辺と武蔵小山、この２カ所はやっていきたいということで、今は考えております。","id":"exchange-019"},{"speaker":"本田委員","kind":"意見","question":"そうすると、平成１５年度は五反田駅と、大井町駅周辺、青物横丁駅周辺、武蔵小山駅周辺と、４カ所をとりあえず指定区域にかけていこうということですね。過料は1,０００円相当を考えているということですね。先ほども、過料について話がありましたけれども、自動車なんかでも、駐車違反をなかなか払わないとかいろいろありますが、そういう徴収方法について、逃げている場合はどうするのか。","respondent":"長田地域活動課長","answer":"その場で直接取ることも可能です。そうんいった手続で進めていかなければいけないということで、イメージとしては、交通違反の反則切符といったようなイメージだということでご理解いただけばと思います。","id":"exchange-020"},{"speaker":"本田委員","kind":"質問","question":"わかりました。当然だと思いますが、払込みというやり方をとって、なかなか払い込まない、それが半年、１年、２年経つということだって起きてくる可能性はあると思うんですね。そういう場合は、どういう対処を考えているんですか。","respondent":"長田地域活動課長","answer":"納入しない部分について、それ以上法的な手続を取るということはできません。あくまでも過料ですから、例えば、警察庁に告訴をするとか、告発をするというような手続というのはできません。","id":"exchange-021"},{"speaker":"本田委員","kind":"質問","question":"そこのところを、私はきつく願っているわけではないんです。ただ、納入方法で、後で金融機関に払い込むということで、いくらでも逃げられるというようなことになってはいけないし、追っかけるために区が金をかけてもおかしな話ですよね。ここのところはひと工夫必要だなと、今、感じるんです。その辺はどうですか、もう一度、申しわけないですが。","respondent":"長田地域活動課長","answer":"先ほどの答弁で、言葉が足りずにすみません。未払いになって、悪質な場合につきましては、税金と同様に強制的な徴収をする方法があります。これはまた別の手続によってやらなければいけないという問題は生じることになろうかと思います。","id":"exchange-022"},{"speaker":"本田委員","kind":"質問・要望","question":"さらに最近では、学校を全部禁煙区域にしてくださいという要望も来ております、そういう問題提起もしているところです。学校の敷地内の禁煙については、きょうは論議する場所じゃありませんけれども、ほんとうにしようがないなと、精神条例だけで済めばよかったのに、６年前のときにも、これでうまくいきますかという議論をしたことを記憶しているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"確認","question":"そこら辺で、広げていく上で、もっと柔らかい表現方法は何かないのかなというのがまず１点です。それから、巡回指導員、さっきのお話だと、2,３００万円ぐらいで、これは６グループで、区の職員が６人ということは、その数はもう既にこの経費には含んでいないわけですか。要するに１２人分の経費ということで考えていいわけですか。さっき１８人とおっしゃった部分を、もう１回ちょっと確認したいんです。","respondent":"長田地域活動課長","answer":"巡回指導員の経費ですけれども、先ほど、３人の中で１人は区の身分を持たないと過料処分ができないという形で説明をさせていただきました。３人のうちの１人、区の身分を所有する部分については、非常勤での採用といったことで考えてあります。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"非常勤の職員のことはわかりました。身分を持たない人というのは、どういうことなのかなと、それを教えていただきたい。それからもう１点、公共の場所の管理者の責務ということで、道路管理者という文言があるけれども、さっき、都とか国という問題がありましたけれども、道路管理者としての東京都とか国に、品川区がどういうふうに働きかけをしていくのか、その点を教えてください。","respondent":"長田地域活動課長","answer":"身分の問題ですけれども、一つは、先ほど、３人のうちの１人を区の身分ということ、それから残る２人は、実際にまだ詰めていませんけれども、例えば委託になるのか、アルバイト的な形でやるのか、どちらかになろうかと思います。","id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"質問","question":"身分を持たない２人が委託になるか、アルバイトになるかということですけれども、委託がどうこうじゃなくて、どんな人がやるか。例えば、よく区でいうと、シルバーの方をお願いするとか、シルバー人材センターという言葉も出てきますけれども、ご高齢の方に言われたときに、逆にその方が被害を受けてしまうとか、そっちのほうが心配で、ちょっとお聞きしたんですが、その辺をもう１回。","respondent":"長田地域活動課長","answer":"これにつきましては、私ども、今のところまだ決めてございません。ですから、どこへ、どういう方にお願いをするかという部分は、今後、詰めさせていただきたいと思います。","id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"要するに、その方に被害がないような形で、この条例をやったことであとあとに問題が起きないような形を警戒しているという、その辺だけ気をつけていただきたいということでの要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"三上委員","kind":"質問","question":"第９条の喫煙者の責務というところで、「何人も、公共の場所において、歩行中（自転車乗車中を含む。だから、子どもたちだって、いたずらして、小学生は吸うのかどうか、中学生とか高校生あたりなんか公園で吸っていたって、私だって１０人ぐらいいたら注意できないものね。当然、今までいいのがだめになるわけですから、そこらあたりもきちっと丁寧にやってもらいたいと、直に私は言われましたよ。","respondent":"長田地域活動課長、太川区民生活事業部長","answer":"ただ、私ども、そういった部分も含めまして、少しでもポイ捨てがなくなるような形での対応は図っていきたいと考えています。たばこ税の関係でもお話ししていますけれども、これから、特に実施の段階が具体的に規則等に盛り込まれてまいりますので、それにつきましては、たばこ商の方とは緊密な連絡の中で。","id":"exchange-028"},{"speaker":"三上委員","kind":"質問","question":"立ちどまってそこで喫煙しているという場合は、果たしてそれは歩行中と言えるのかどうか。だけれども、やっぱり２時間も３時間もたばこ吸ってないんだから、どうしてもここで一服吸いたいんだと。だから、立ちどまって、自分の灰皿等も出して吸った場合、それで罰則を取られるなんていう話になったら、これはトラブルになるんじゃないですかね。理事者の中でもいられるんじゃないですか。","respondent":"太川区民生活事業部長","answer":"ですから、朝の一定の時間、また、夕方の一定の時間を区切って監視するようになると思いますので、その余の部分につきましては、やはりこの条例の趣旨にのっとって、各人が努力していただくととっていただきたいと思ってあります。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今の話を聞いていて、ちょっとよくわからなくなっちゃったんですけれども、ここでは、原則として、道路、公園などの公共の場所では、区内全域を歩行喫煙の吸い殻・空き缶の投げ捨てを禁止すると書いてあるんですけれども、例えば、先ほど出ているように、お花見をしていて、公園で座ってたばこを吸うということも禁止となっちゃうのかどうかということを、ちょっと。","respondent":"太川区民生活事業部長","answer":"ただし、いずれにしましても、１０月の実施まで４月から６カ月設けているということは、やり方も含めて、詳細な部分につきまして、区民の方に十分理解していただきたいということで、６カ月間というＰＲ期間を設けてありますので、その中で、十分に周知はしていきたい。","id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"歩行喫煙じゃなくても、公園で座ってたばこを吸うというのも、原則禁止ということになっちゃうんでしょうか。","respondent":"太川区民生活事業部長","answer":"それにつきましては、きちっとＰＲをして、なぜ、こうしたのかという部分につきましても、わかるように表示はしていきたいと考えています。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうなると、「歩行喫煙」というんじゃなくて、「喫煙」としないとまずいんじゃないかなと思うんです。ここでは、「原則として、歩行喫煙」というふうに歩行中の喫煙となっているんで、原則として、公共の場の喫煙はもうだめだとなっちゃうということなんですか。","respondent":"長田地域活動課長","answer":"条例の第９条につきましては、「努めなければならない」という、区内全域では、区民に対する努力義務です。ですから、言ってしまえば禁止という話になるんですけれども、区民の責務として努める、要するに喫煙してはいけませんという努力義務です。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"歩行中ということであれば、これでちょうどいいかなと思います。","respondent":"長田地域活動課長","answer":"ただ、公園の場合につきましては、通路という話にはなりませんから、この辺については、ちょっと疑義が生じるかもわかりません。私どもも、この部分はもう一度確認をしてまいります。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その辺のところは、ぜひわかるようにしていただきたいと思います。それから、地域を区切って指定するということなんですけれども、「区民等」という中身は、区内を通過する者も区民等と書いていますよね。そういう方には、この地域はそういう地域として指定されているんですよということがわかるようなお知らせというのは、どういうふうな形でされるんでしょうか。","respondent":"長田地域活動課長","answer":"一番やっぱり問題なのは、たまにしか来ない人、例えば、きょうはたまたま大井町駅前に買い物に来たというような人、こういった人たちについては、やっぱり事前の周知というのはなかなか難しい面があろうかと思います。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっと何点かお聞きしたいんです。そこら辺のところが、回る人によって判断が違うことがないような、そういうものというのはどういうふうにして確保されるのかということを教えてほしいと思います。","respondent":"長田地域活動課長","answer":"まさに、委員ご指摘のとおりだと思います。回る人によって対応が違ったということにつきましては、公平性の問題からいっても、非常な問題になるだろうと理解はしています。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう１点だけ、ごめんなさい、いろいろわからないことが多くて。第１１条の４番なんですけれども、指定地域を指定するとか、変更するとか、解除をするというところでは、「当該地域の公共的団体および関係行政機関の意見を聞くものとする」となっているんですけれども、これはどういう仕組みで聞かれるのかということを、ちょっと教えてください。","respondent":"長田地域活動課長","answer":"第１１条の第４項につきましては、特に過料を伴うものだけに、行政側で勝手に線引きをして、これでやりなさいというわけにはいかないでしょうというところから出てきた規定です。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"その意見の聞き方なんですけれども、例えば、区の職員が聞いて歩いて決めるのか。それともそういうふうな話し合いの場みたいな形で、多少そんな場が保証されて決められていくのか、そこら辺のところをちょっと。","respondent":"長田地域活動課長","answer":"この辺の調整については、当然、それなりの会議を持つ形になろうかと思います。ただ、生活安全条例なんかと違うところは、そのための協議会をここでは持ちませんから、必要に応じて関係者の方々とその辺の協議は行っていくという形になろうかと思います。","id":"exchange-037"},{"speaker":"本多副委員長","kind":"質問・要望","question":"１０年以上前から、自民党の渡辺敏正元議員が、分煙の推進ということで、ずっと発言をしてきて、当時にしてみれば、やはり賛否両論というんでしょうか、そんな時代だったと思うんです。担当の区の職員が出られて、本業がおろそかにならないという部分、ちょっとそこの確認だけを聞かせいただきたいと思います。","respondent":"長田地域活動課長","answer":"私どものほうは、基本は、原則、先ほど、予算のところで説明させていただいたように、３人×６組で対応をしようかと思ってあります。これで十分かという議論はあるにしても、当面はそれでいこうと思っています。","id":"exchange-038"},{"speaker":"本多副委員長","kind":"質問・要望","question":"もう１点だけ、ちょっと確認をさせていただきたいんですが、よく品川区内の福祉施設とか、玄関を入ると喫煙コーナーがあるとか、そういった部分を見直しできないかという意見も出ていたんですが、直接はこの条例のあれはマナーということなんですが、その辺の区内施設、特に福祉施設なんかについて、もし把握されていたら、ちょっと担当が違うからあれなのかもしれないんですが、当然。","respondent":"太川区民生活事業部長","answer":"これを条例で実施していくということですと、今、委員おっしゃいましたように、相当な時間がかかりましたけれども、やっと区役所も分煙ということになりましたけれども、やはりこの分煙でいいのかどうかということが、またいろいろ議論が出ているようなこともあります。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は、たばこの迷惑はほんとうにかけてほしくないなと思いますし、たばこを吸わない人が、ぜひもっと増えてほしいなと思っているんですけれども、今回の条例については、いろいろと今お聞きしても、まだまだなかなか初めてというようなこともあって、具体的なところでまだ見えない部分もたくさんあります。本来であれば、やっぱりモラルが向上してそんなものはなくなってほしいというような思いがあるんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"高木委員","kind":"意見","question":"ちょっと意見を。これはマナーという非常に抽象的というか、難しいことなんですが、これは国外なんですが、中国へ行って、議員団で来て、前だったか、とにかく罰金をやられたことが。でも考えてみると、これは１万円ですね。安くない金額ですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"高木委員","kind":"質問","question":"いずれにしても、即断即決にしても、どういう方法であれするか知りませんけれども、これは裁判ですから、だれがどういうところでどうするか、私は言及しませんけれども、非常に難しいだろうなと。難しいことだけに、よく手がけたと申しますか、突っ込んで取り組もうというんですから、その努力はしていくしかないと思うんです。私は、可とすることに異議はありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ継続にしていただきたいと思ったんですけれども、継続にならないということであれば、ちょっと私は意見を保留させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"松澤委員","kind":"質問","question":"今、昭和４１年からということですけれども、参考までに、そのころ金利は幾らぐらいで貸し出していたのか。今現在は幾らですか。","respondent":"市川産業振興課長","answer":"金融機関と私どもで結ぶ協定金利で答えします。現行、都市銀行から信用組合まで全部一律の協定金利ですが、これが１.９％で提携しています。昭和４１年、この制度が始まった当時は、おおよそ６％前後の協定金利となっています。","id":"exchange-044"},{"speaker":"松澤委員","kind":"意見","question":"わかりました。昨今、ペイオフという言葉が叫ばれておりますけれども、この基金を廃止したというのも、一つにはペイオフ対策というものも含まれているのかどうかということ。それから、この基金を廃止してしまってなくなると、１３億3,８０４万円というこの金はどこへ行ってしまうのか、その辺をお教え願いたいと思います。","respondent":"市川産業振興課長","answer":"したがって、同日付で廃止をいたしまして、平成１５年度の一般会計歳入予算に基金繰入金ということで、この基金にあります金額を、区の歳入として基金のほうから繰り入れるという措置を予定させていただいてあります。","id":"exchange-045"},{"speaker":"松澤委員","kind":"質問","question":"それじゃあ、この基金を繰り入れて、これをどこかに使いますという明確な方針があるというわけではないんですね。とりあえず入れておくということでよろしいんですか。","respondent":"市川産業振興課長","answer":"これは、本来、私のほうから説明申し上げることではないのかもしれないんですが、財政当局からの今回の私どもの基金の取り崩しに伴う措置といたしましては、来年度予算に計上していますベンチャー創業支援事業で約５億円の経費を計上していますが、この経費に一部を充て。","id":"exchange-046"},{"speaker":"本田委員","kind":"確認","question":"確認の意味で、こういう基金制度を持って、金融機関に預託をして、担保のない中小零細企業も制度融資ができたというのでずっときたわけですが、今のご説明だと、この基金をなくしても金融機関との間では、品川区が行っている制度融資と、今後どういう制度融資が出てくるかもわかりませんが、それは円滑に。","respondent":"市川産業振興課長","answer":"大変申しわけありません。先ほど、説明申し上げればよかったんですが、お配りした資料の一番最後の７番のところ、融資あっ旋事業の維持・継続のところにお示ししていますが、あくまでも現行の事業内容を維持する。","id":"exchange-047"},{"speaker":"本田委員","kind":"質問","question":"どうして今、これを廃止するのか。なぜ今なんだろうというふうに、ちょっと考えたんです。どうしても金が足りなくて、事業部制の中で、やり繰りでこの基金を取り崩そうとなったのか、その辺の裏事情というのはどういうことなんでしょうか。","respondent":"市川産業振興課長","answer":"あくまでも、区の財源を有効活用する中で、私ども産業振興の施策を所管する担当部署としては、できるだけそれを私どもの施策の主要経費として使わせていただきたいということで、財政当局のほうに申し上げ、また、その意向がくまれて。","id":"exchange-048"},{"speaker":"三上委員","kind":"質問","question":"だけれども、今、そういった形で、融資については、今かなり政府が突っ込んでやっていますよね。だから、そういったことがあるがゆえに、品川区だってここまでやらなくてももう済むようになりましたというふうに、私は思って、これは当然だなと思っているんですよね。そこらあたりはどうなんですか。","respondent":"市川産業振興課長","answer":"先ほど、冒頭の説明で申し上げたように、昭和４０年代と、今一番変わった事情というのが、特に信用保証制度の充実ということで、これは中小企業の金融をめぐる環境の中で、一番大きく変わった点です。","id":"exchange-049"},{"speaker":"三上委員","kind":"質問","question":"流れ的には、そういうことでしょうから、廃止にするということについては、私は結構と受けとめております。そこだけお願いしておきたいと思います。","respondent":"市川産業振興課長","answer":"ご指摘にありましたように、国や東京都、あるいは金融機関と、あるいはまた場合によっては信用保証協会と連携して、私どもの窓口でもできる限り、区内の中小企業の皆さんにわかりやすいＰＲを心がけてまいりたいと思います。","id":"exchange-050"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"当初、担保不足を補う部分の預託金というお話だったと思うんですが、ここ直近で言えば、その効果は全然なかったというのがほんとうだと思うんです。確かに産業振興部分で残していただけるんでしょうけれども、基本的には、一般財源のところに戻ってしまうのが主になってしまうと思うので、ぜひ、この基金の活用を図っていただきたいので、その辺をもう１回、ちょっとお願いいたします。","respondent":"市川産業振興課長","answer":"２番目の件につきましては、今回、こういう形でご審議いただいて廃止をするわけでございまして、今後、私ども産業振興を担当するセクションとしては、強く財政当局に、一般財源ではなくて、こういう特定財源的な意味合いを持ったお金として使わせていただけるような。","id":"exchange-051"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"施策的に考えていただいて、いいものに使っていただきたい思います。この基金がなくなったことによって、各金融機関の考え方が変わらないように、今後も融資制度が維持できるものもおいていただきたいと思うので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]},{"id":"topic-02","title":"さて、引き続いて第１６号議案にいきたいと思います。 第１６号議案、品川区手数料条例の一部を改正する条例","agenda":"さて、引き続いて第１６号議案にいきたいと思います。 第１６号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"三上委員","kind":"質問","question":"要するに、従来は、台帳そのものが紙だったと、請求があればそれをコピーして渡していたと、この違いなわけでしょ。紙のものというのは全くなくなってしまうということなんですか。要するに、考え方として、磁気ディスクから出力するという形にすべてなっちゃうということなのか、それとも紙からのものも、請求すれば出てくるという二段構えということになるんですか。そこのところを。","respondent":"冨田戸籍住民課長","answer":"出力する場合もそのイメージとして出力することになります。現在戸籍については、全部縦書きの表記をしていますけれども、戸籍電算化した後につきましては、横書きの表示になります。それが違いということになります。","id":"exchange-053"},{"speaker":"三上委員","kind":"意見","question":"新たに新設すると、４５０円というこの料金も変わってないわけでしょ。だから、そこらあたりをきちっと説明してもらって、こういうふうになるんで、新しくこういうふうに新設しなきゃならなくなったんですよという説明をもらわないと、そっちのほうがよくわかったなという感じがするんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"本田委員","kind":"意見","question":"今の関連で言えば、今度はやりやすくなったのかなと。スピードアップして、人件費もかからなくなって、４５０円が４００円ぐらいに、電算化することによって安くなりましたというと聞こえがいいけれども、そんなふうなことは無理なんでしょうね、これは。これはどんな利点があって、これはどういう使用の仕方でしたか、ちょっともう一度聞かせてください。","respondent":"冨田戸籍住民課長","answer":"そのほかに、住民基本台帳法上は、独自利用が可能ということで、例えば品川区で何々の事業に当たり住民基本台帳カードを使うということで条例で決めれば、その利用ができますけれども、現在のところ、その部分の条例については予定はしていない状況です。","id":"exchange-055"},{"speaker":"本田委員","kind":"質問・要望","question":"住民基本台帳カードの1,０００円というのは、これも全国一律になるんですか。自治体によって全部違うんですか。1,０００円にした根拠というのは、どういうことなのか、ちょっとお聞かせいただきたいと思います。","respondent":"冨田戸籍住民課長","answer":"ということで、お貸しする以上は、カード自体の値段を手数料に組み込むことは適当でないであろうということで、カードそのものの価格を除いた残りの人件費の経理相当分を、１件当たりに割返したもので算出をしますと、1,０００円程度という額になったものです。","id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問","question":"じゃあ、簡単に。今ちょっとご答弁の中で、返納という部分なんですけれども、効力がなくなったものを返納する、手続的にはちょっとよくわからなかったんです。どういうふうに返納するんですか。","respondent":"冨田戸籍住民課長","answer":"形態としては、いずれはお返しいただくという形は承知しています。","id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"確認","question":"まだ決まってないならあれですけれども、これ自体、ちょっとはっきりしなかったのは、写真付もできてきますね。そうすると、身分証明の一つにもなってしまうのもあるわけですね。そうすると、引っ越しして、品川区が証明書をつくったまま残っちゃうのかなというので、それをちょっと確認したかったんですけれども。","respondent":"冨田戸籍住民課長","answer":"いずれにしても、返納はいただくということになっています。要するに、有効期間としては１０年間を予定していますけれども、１０年間は一応通用してしまうことにはなると思います。","id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それがほんとうに返してもらえるのか。逆に言うと、各自治体で協力し合って、このカードに関しては移転を受けたときには回収するという取り決めをしておかないと、何か証明書が長い時間そのまま生きてしまうというのはちょっとおかしいんじゃないのかなという思いがあるんですけれども、その点はどうですか。","respondent":"冨田戸籍住民課長","answer":"これは全国的な取り扱いですので、仮に品川区が独自で転入届けの際に回収をする取り扱いをしても、他の自治体がそのようにしなければ意味のないことですので、何か機会があるごとに、もしそういう取り扱いになっていなければ、要望等はしていきたいと考えています。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"1,０００円というのが、原価を除いたということなんですけれども、原価というのはどのぐらいするのか教えていただきたい。それから、今、話を聞くと、それほど住民にとって、そんなに使いたい、持ちたいというものでないような思いがどうもしちゃうんですけれども、どれぐらいの方が欲しいと来られると想定しているのかということを教えていただきたいと思います。","respondent":"冨田戸籍住民課長","answer":"今のところ、３２キロバイトとか、五十幾つバイトだとか、あるいは１メガバイドだかと、相当容量の大きいものをいろいろ研究はされているようなんですけれども、容量の大きいものはまだ明確に出されていないので、実施時期も、例えば８月２５日に間に合わないとか。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと、私、３２キロバイトとかわからないんですけれども、いろいろと読むと、8,０００文字とか、2,０００文字とかが入るようなということをちょっと読んだことがあるんですけれども、新聞で言うと２ページぐらいとか書いてあるものもあるんですけれども、今回のカードが、そういうところでどのぐらいなのかと教えていただくとよくわかるかと思いますので。","respondent":"冨田戸籍住民課長","answer":"４月以降、例えば一般旅券、パスポートの発給事務ですとか、あるいは、恩給とか、共済組合の年金の生存確認とか、いろいろな形で本人確認情報の利用が予定されておりますので、その面からすれば、相当な行政事務の効率化に効果があるものと考えています。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"我が党は、住基ネットに関して、もともとやっぱり大きな問題を抱えているし、やっぱり個人情報の漏洩とかいうところでは、住基ネットのシステムそのものに絶対安全はあり得ないというところですので、そしてまた先ほども言いましたように、何が住民のデータの安全性を脅かすかというところでも、ＩＣカードが４０％を占めているという結果が出ている中で、この条例に対しては反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"}]},{"id":"topic-03","title":"第１７号議案、品川区証明書の交付、届出等に係る本人確認に関する条例","agenda":"第１７号議案、品川区証明書の交付、届出等に係る本人確認に関する条例","exchanges":[{"speaker":"松澤委員","kind":"確認","question":"条例のほうではないんですけれども、本人確認カードなんですけれども、発行のめどが立った段階でというんですけれども、これは品川区だけで通用するということですか。","respondent":"冨田戸籍住民課長","answer":"区民カードにつきましては、あくまでも、住基、戸籍等、品川区あてに出される申請等について、本人確認が必要である場合にご利用いただくのが目的です。それ以外の目的としては考えておりませんので、その目的に限定してお使いいただけるということになっております。","id":"exchange-063"},{"speaker":"松澤委員","kind":"確認","question":"有料で発行するのがいいというわけではないんですけれども、あまりぺらぺらで偽造されやすくなってしまっては困るんで、身分証明のカードを発行されればされるほど、安易に、見てああいいですという形で確認しやすくなる。あるいは、写真がしっかりはがれないようにするとか、いろいろなそういうことで、危険性というものはないと考えているんでしょうか。","respondent":"冨田戸籍住民課長、太川区民生活事業部長","answer":"偽造のほうなんですけれども、やはり本人確認をして届出を受ける、写しの交付をするということですので、カード自体を偽造されたのでは意味がないことになりますので、それ相応の偽造対策はしていきたいと思いますけれども。各所管でもいろいろなやり方をしておりますけれども、いろいろな身分証明を持っていらっしゃらない方もいますので、そういうときにはこのカードをお使いいただけるように、発行してスタートのときには。","id":"exchange-064"},{"speaker":"松澤委員","kind":"質問","question":"品川区だけで使えますよというのは、それはわかって質問しているんですけれども、やっぱり一番のポイントは偽造されないかということですよね。安直に偽造されるようなものだったら困るので、でき上がりを見たいと思いますけれども、そういう懸念があるということを申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"三上委員","kind":"質問","question":"住民基本台帳カードの役割は果たさないんですか、これは。","respondent":"冨田戸籍住民課長","answer":"住民基本台帳カードも２種類あるということは、先ほど申し上げたんですけれども、写真付でないものは身分証としてはちょっとお使いいただけないと思いますけれども、写真付であれば身分証明書として当然使える。国のほうも、そういう形で周知をしてきているところです。","id":"exchange-066"},{"speaker":"三上委員","kind":"質問","question":"要するに、全国的に使える住民基本台帳カードを製作しておきながら、あえてここで品川区民のためにということであれば、住民基本台帳カードに全部写真を入れちゃえばいいじゃないですか。それで個人の証明はできるんでしょ。","respondent":"冨田戸籍住民課長","answer":"住民基本台帳カードは有料です。本人確認だけで義務づけを行う見返りというか、ということでご負担をかけないような形で、無料で区民カードを交付するということにしたものです。","id":"exchange-067"},{"speaker":"三上委員","kind":"確認","question":"何だか屋上屋を重ねるような感じがしてしようがないんですよね。要するに自分で必要だと思うと、その都度、何か本人確認って、本来は運転免許証だけで十分足りるわけなんですよ。こっちの病院とこっちの病院が、レセプトとか全部そこのカードに出てくるようにして、二重診療はしませんとか、どういう薬がどうのとか、そこまで踏み込んだカードにするというんだったらわかるんですけれども。","respondent":"太川区民生活事業部長","answer":"そういう意味で言いますと、今、申しておりますとおり、非常に本人確認を急いでいるという状況がありますので、緊急避難的と言ったらおかしいんですけれども、まずはこのカードで対応を図りたい、住民基本台帳カードが普及してきた段階で見直しはしていきたいと。","id":"exchange-068"}]},{"id":"topic-04","title":"第１８号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第１８号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"賦課割合の件で、法令原則５０％対５０％になっている。結局、これが６３と３７というのは、現在、品川区としては低所得者の方の負担を軽くしていると判断していいのかが１点。それから、８ページの、特別区の５３万円の賦課割合が６３対３７で、これも品川区では現状、同じですけれども、１区だけ違うところがあったと思うんですけれども、そこら辺のところのご説明をいただきたい。","respondent":"太田保険年金課長","answer":"その分、じゃあどうなるかと言いますと、均等割が３７で、その分が多くなるわけですから、均等割額が引き上がるということで、必ずしも低所得者の対応ということではなくて、均等割額が上がる、一方、所得割の料率が下がるです。","id":"exchange-069"},{"speaker":"鈴木（真）委員","kind":"意見","question":"これは、区長会決定でしたよね。その辺が、今度は逆に、区の分でどうなるのかなというのがちょっと疑問で、そこら辺も。","respondent":"太田保険年金課長","answer":"ところが、一昨年、課長会、区長会等でそういう話がなく、結果的に１区が、先ほど申し上げたような理由も含めて、実体としては違った料率になったです。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"私も、国保運営協議会の委員のメンバーになっているんですけれども、委員会では、諮問どおり答申をいただいたというご報告だったんですが、そのほかにも、私も意見をいろいろと言わせていただいたんですけれども、私以外の方からも意見がいろいろと出ていましたので、諮問どおりというだけでなく、その中で出た意見も出していただけたらいいんじゃないかなと思います。","respondent":"太田保険年金課長","answer":"それからあとは、介護保険料２号分の算定の方式についてのご質問があったかと思います。主なものはその方で、あとは鈴木ひろ子委員のご質問だったかと思います。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区の収納率というところでも、この間、ずっと少しずつやっぱり下がってきていて、平成４年度に９１％あったのが、平成１３年度では８７.２％ということで、そのときにも私も聞いたんですけれども、滞納をされている方も、合計でたしか１万6,０００人ぐらいですか、かなりの方があって、その主な理由というのも、やっぱり失業だとか、病気だとか、営業不振、そういうやむにやまれずというところが。","respondent":"太田保険年金課長","answer":"なおかつ、高齢者の医療制度改革については、法改正後２年内に、国のほうで具体的な計画案を出して、実施後５年をめどに新たな高齢者医療制度を創設していくということで、今、いろいろ国のほうで試案をつくっている真っ最中と聞いてあります。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つは、差し押さえの件数について、ちょっと前に課長のほうからお聞きしたことがあったんですけれども、品川区の滞納者に対してのいろいろな電話だとか、預貯金とかの差し押さえの件数は、この間、品川区としては増えてはいないということで、お聞きしたときにはそういうお話があったんですけれども、どういう方を、どういう基準内容で差し押さえしているのかという点について。","respondent":"太田保険年金課長","answer":"どういう基準かですけれども、私どもとしては、基本的には１回督促をして、お支払いいただけない場合には、滞納、差し押さえすることは法的に可能ですけれども、そうは言ってもいろいろご事情はありますので、お支払いいただける資力があるにもかかわらず。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すごく国民健康保険というのは複雑な仕組みで、ほんとうに聞いても聞いても１００％理解するというのはなかなか難しい仕組みだと、いつも思いながら考えているんです。そういうふうに短期証を出しても、その中でまた高額の滞納をしているという人に資格証明証を出しているという説明を受けたかと思うんですけれども、それと差し押さえの関係はどういうふうになっているんでしょうか。","respondent":"太田保険年金課長","answer":"それは別です。今年度、ちょうど４月で保険証の切り替えになってあります。３月１日付の広報で、保険証の切り替えについては、とりあえず周知をさせていただきました。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"わかりました。ちょっと２３区のところでの差し押さえ件数の一覧表で見たら、品川区はほかの区に比べて多いということが出ていまして、どういうことでこんなに多くなっているのかなと思ったんですけれども、そこら辺のところは、何かありますか。","respondent":"太田保険年金課長","answer":"短期証ですとか、資格証についても、最終的には保険料を納めていただくことが趣旨ですが、接触できない方に対して、納付交渉、相談を得る機会をより広く求めているという趣旨から、先ほど申し上げたように、電話加入権についても、区としては、多く差し押さえをしているです。","id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ほかの区はほとんど差し押さえはないところが多い中で、品川区がそれだけ目立っているなと思ったんです。そういうふうに電話加入権を差し押さえて、それによって接触ができて改善したというのはどれぐらいなんですか。","respondent":"太田保険年金課長","answer":"ちょっと個々のあれについては、統計を取ってないんです。ただ、２月に実は電話加入権の公売を実施をいたしました。公売対象者は６７名でして、最終的に、電話を公売したのは４件です。","id":"exchange-076"},{"speaker":"本田委員","kind":"質問","question":"一つだけ。さっきの２３区統一保険料のことなんですけれども、これはいつまで続ける気なんですか。嫌だと言ったところもあるわけですけれども、品川区はこういうのが出てきているわけですが、最初の鈴木委員の質問と同じようなところがありますけれども、どのようにしようかというんでしょうか。","respondent":"太田保険年金課長","answer":"先ほどもご説明申し上げましたように、平成１２年度以降の都区制度改革に伴って、以後の国民健康保険事業をどうするかということで、一つは、先ほど言いましたように、平成１１年３月に区長会の総会で、そういう取り決めがあったということ、それとあわせて。","id":"exchange-077"},{"speaker":"本田委員","kind":"意見","question":"財調制度と切っても切れない関係にあると。スーパー補正と言われるようなものも、どうしても必要とするところもあると。こういうことについて、今度の場合も、スーパー補正がどのぐらいになるのかよくわかりませんけれども、ちょっと意見として申し上げておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"反対です。しかも、増加率を見ると、所得が低い世帯ほど増加率が高いというところで、低所得者の方がますます大変になる。こういう制度そのものを、それから改めて、税金の使い方を大もとから変えて、国に対してもそういうふうに求めていくべきだと思いますので、この条例については反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"}]},{"id":"topic-05","title":"第２３号議案、町区域の変更","agenda":"第２３号議案、町区域の変更","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この土地が7,３５１m2ということなんですが、この上部の利用はどういうふうな、計画とかがあったら、それについて教えていただきたいと思います。","respondent":"冨田戸籍住民課長","answer":"所管ではありませんので、特に聞いておりません、恐縮です。","id":"exchange-080"},{"speaker":"松澤委員","kind":"質問","question":"条例そのものは、今この委員会の中では審議し、継続にしたというのも、ちょっと様子を見ようということですから、条例でカバーされますので、今、理事者からお話を伺いましたので、趣旨採択か、採択、いずれにしても。趣旨採択かな、どうなんですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"三上委員","kind":"質問","question":"私は、これは採択でいいと思うんですよね。だって、強化するというのは、罰則等を科しというところで、それについての条例をきちっと定めると、当委員会では決まったわけですから、その目的は十分に果たしていると思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、条例でも保留ということで意思表示をさせていただきましたので、やはりこれは違反者に対する罰金等を科するというところですので、自治体が取り締まる罰金ということに関しては、それを進めていくというよりも、モラルを向上するというところをぜひ大きくしていただきたいなという思いがあるんです。その思いというのがあるところですので、条例と同じに保留とさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"松澤委員","kind":"質問","question":"この陳情者のほう、「違反者に対する罰金等を科する」ということですけれども、今回、私たちが審議した条例は、今のところ全区的ではないですよね。そういうことと、本来的には、罰金を取ること自体が目的ではなくてというお話がありましたですけれども、そのようなことから、私は、趣旨採択でいいと思っていますけれども、いかがでしょうかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"本田委員","kind":"質問","question":"陳情者の思いというのは、採択でも、趣旨採択でも、どちらでも、過料付の条例をつくったというところでかなえてあるんだから、私はどちらでもいいと思っているんですけれども、厳密に、言葉の解釈や何かから言えば、趣旨のほうがいいかなとは思ったりするんですけれども、趣旨を採択して何もしないでいるんではなくて、既に条例をつくるということが出たわけですから、趣旨採択でも構わないんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"本田委員","kind":"意見","question":"この方は南大井の三丁目ですけれども、品川全域を指して言っているのか、基本的に大森駅あたりか大井町駅あたりを言っているのかよくわかりませんけれども、場所限定とか、いろいろ必ずしも全部、もちろん思いは総体としては入っているだろうけれども、厳密に言えば、もっと厳しくだとかいろいろあるかもしれませんので、だから、議会側としては十分こたえているということで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"高木委員","kind":"質問","question":"今も伺っていると、趣旨というのは、まさに趣旨だけ受け取ればいいじゃないかという意味と、そうなると、全面的な採択には遠くなるような感じ。私もまさにそのとおりですから、採択でいいと思うんです。午前中、大変なご議論をされていますから、十分にこれは採択に値する施行をすることになったと解釈しますけれどもね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/302915?Template=document&Id=2352#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":73942,"voices":246}},{"id":"h15-20030303-7","meetingId":"h15-cm03","date":"2003年3月3日","dateIso":"2003-03-03","committee":"厚生委員会","time":"午前１０時０８分～午後２時５９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を77件抜き出しています。","topics":[{"id":"topic-01","title":"早速、議案審査を始めてまいります。 (1) 第１９号議案、品川区高額療養費等支払費用貸付条例の一部を改正する条例","agenda":"早速、議案審査を始めてまいります。 (1) 第１９号議案、品川区高額療養費等支払費用貸付条例の一部を改正する条例","exchanges":[{"speaker":"宮崎委員","kind":"確認","question":"大体、説明はわかりましたけれども、ちょっと何点か聞きたいと思います。今、基金が１億4,０００万円だということで、この運用益を充てていたということですが、実際に１億4,０００万円の利息というか、これからどのぐらい生み出されていたのかということを、ちょっと一つ確認をしておきたいと思います。","respondent":"黒田生活福祉課長","answer":"回転率がそのぐらいだったら、本来ですと、予算も１億4,０００万円でいいのではないかと、こちらのほうも計算をしたんですが、平成１２年度は１億7,０００万円あったんですが、その前が１億6,０００万円ぐらいがずっと続いておりましたので。","id":"exchange-001"},{"speaker":"宮崎委員","kind":"意見","question":"実際の件数で、どのぐらい利用が増えそうなのかという、そこのところをお願いしたい。利息のところも、高いときには一般事務費に相当する額ぐらいあったという説明だったんですけれども、実際の額で、わかったらお願いしたいと思います。","respondent":"黒田生活福祉課長","answer":"入っている金額なんですが、正確な数字を手元に用意してなくて申しわけないんですが、先ほどご説明しましたとおり、ここのところ２桁から１桁に下がっているということで、１桁も二、三万円というようなことです。１桁ということで、金額は申しわけございません。","id":"exchange-002"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。貸付件数のところは、実績は下がってるということなんですけれども、１億4,０００万円から１億6,０００万円で、実際の枠というのは増えるわけですよね。そこのところはどうでしょうか。","respondent":"黒田生活福祉課長","answer":"貸付枠は全然変わりませんので、ご利用いただいている方には、サービスの低下というのは全然ございません。","id":"exchange-003"},{"speaker":"宮崎委員","kind":"質問","question":"１億4,０００万円が１億6,０００万円になるというのは、拡大ということですか。","respondent":"黒田生活福祉課長","answer":"拡大ということではなくて、件数にはちゃんと対応できるということです。ですから、サービスの内容については変化はございませんので、従来どおりのサービスは提供できます。","id":"exchange-004"},{"speaker":"宮崎委員","kind":"質問","question":"私が聞いているのは、件数とかで、どのぐらいキャパシティが拡大するのでしょうかということなんですけれども、そこのところはどうなんですか。","respondent":"黒田生活福祉課長","answer":"件数というのが、ご利用いただける件数ということですので、ご利用いただける方が増えても、従来どおり対応できるという金額です。","id":"exchange-005"},{"speaker":"山路委員","kind":"質問","question":"利用者には、サービスの低下はないということなんで、利用者にとっては心配ないと思うんですけれども、ちまたではこの貸付けで非常に助かったというご意見が多いんです。一番高い貸付けというのは、どのぐらいあるか。低い方、平均でどのぐらいか、ちょっと教えていただけますでしょうか。","respondent":"黒田生活福祉課長","answer":"高い方といいますと、やはり２００万円近い方。心臓とか、いろいろな手術をされた方に関しましては、そういう金額をお貸ししております。低い方ですと、何千円という方もいらっしゃいます。","id":"exchange-006"},{"speaker":"山路委員","kind":"質問","question":"四つのパターンということで、いろいろな状況の方がこの制度を利用して、助かったという意見ですけれども、これは例えばですけれども、法律的なことかもわかりませんけれども、親戚同士の移植を受けて、多額の医療費がかかった方がいらっしゃるんです。移植というのは保険適用じゃないんですね。その辺について、ちょっと説明していただけますでしょうか。","respondent":"黒田生活福祉課長","answer":"高額療養費につきましては、あくまでも保険の適用された範囲ですので、適用外になりますと、このサービスは該当いたしません。","id":"exchange-007"},{"speaker":"山路委員","kind":"質問","question":"それを前提にお聞きしたんですけれども、先ほど、２００万円ぐらい心臓の病気で貸付けをやった例を出されましたけれども、内容をちょっと説明していただけますでしょうか。どういう内容でそれぐらいかかったのか。","respondent":"黒田生活福祉課長","answer":"健康保険適用ということで、本来の対象の中で１００万円以上の方ということで、１月がそのぐらいとなりますと、手術代と入院費で、翌月ということになると２００万円ぐらいになるということなんです。","id":"exchange-008"},{"speaker":"金高委員","kind":"質問","question":"１点だけお伺いしたいんです。予算というと、毎年、それぞれ変化すると思うんですね。基金の場合ですと固定されますから、これを金融機関に置くことによって、今は０金利ですから、ほとんど０に近いという形になってくるわけですけれども、基金の場合には、確実なるものが、運用はされないけれども間違いなくそこにあるということが大前提になるわけです。","respondent":"黒田生活福祉課長","answer":"ということで、今以上に、基金より会計は明確になりますので、予算に対する金額確保も可能ではなかろうかと考えています。","id":"exchange-009"},{"speaker":"金高委員","kind":"質問・要望","question":"今まできちっとした基金があって、その部分であれば間違いなく担保されているという一種の保証みたいなものがあったわけですけれども、予算組みとなると、その年度によって大きく変わる場合もなきにしもあらずということですから、やはり高額医療を受けた人というのは、そのときにほんとうにお金がない、そのときに払わなければどうしようないというところが多々あるわけです。","respondent":"黒田生活福祉課長","answer":"委員おっしゃるとおり、高額療養費につきましては、本来のところで期間が６カ月ぐらいでご本人に戻るんですが、その期間が待てないという方にお貸ししているものですので、各保険から高額療養費のところには戻ってまいります。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"１点だけお伺いしますが、高額療養費ということで、健康保険等がかかわっていると思うんですけれども、何で保険年金課とかではなくて、貸付けということで生活福祉課が担当しているんでしょうか。","respondent":"黒田生活福祉課長","answer":"ただ、生活保護の相談窓口というのは、いろいろなところで困ったというところから話が入りますので、生活福祉から、状況によっては生活保護にとつなげやすいというところで、生活福祉課のところで所管しているです。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと１点、聞くのを忘れていたんですけれども、この間の件数と金額の実績、何年間かわかる範囲内で説明いただけるといいんですけれども。昨年は1,１７０件と件数は聞いたんですけれども、金額と、あとちょっと何年か、わかる範囲で教えていただければと思います。","respondent":"黒田生活福祉課長","answer":"今年度ですが、１月末現在で、１億円弱ということになってあります。","id":"exchange-012"}]},{"id":"topic-02","title":"第２０号議案、品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第２０号議案、品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"築舘委員","kind":"質問","question":"は荏原にももちろんプールがありますし、身近でリハビリということですから、何も１カ所だけで、老人保健施設だけで実施することもないわけですので、その点を１点お聞きしたい。それから２点目は、リハビリ専門チームの場合は、専門の先生とか、理学療法士の人たちが必要ということで、その辺の人数というか、今、現状がどういうふうになっているのか。２点、お聞きしたいと思います。","respondent":"早津高齢福祉課長","answer":"そういった方々のお知恵を借りながら、保健士、それから理学療法士の中で理解のある方にこのメンバーに入っていただき、検討を進めていきたいと考えています。","id":"exchange-013"},{"speaker":"築舘委員","kind":"質問・要望","question":"専門的な指導も必要だということもあるし、やはり水中で運動することの医学的な効果というのも出ているようですので、しっかりとやっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"金高委員","kind":"質問","question":"ですから、そういうのを大いに活用することも、一つにはいいのではないかと思います。それから五反田のほうには、総合体育館が移築してまた新しくなるとすれば、そういう機能的なものも含めて、ただ単に競技場の部分もあるでしょうけれども、それはまた別個の意味の複合的な形であるならば、やはり先を見据えた形の方向づけもこれから視野に入れて考えてもらたいと思うんですが、その辺はどうでしょうか。","respondent":"早津高齢福祉課長、新美保健高齢事業部長","answer":"お話のありました、そのほかの区内のプール等につきましては、また実績を見ながら検討してまいりたいと考えています。現在、介護保険ではなくて、戸越台では、荏原健康センター主催で水中歩行教室をやっておりますし、そういった水を使った広い意味でのリハビリといったものも含めて、今後、トータルに充実する方向で考えていきたいと考えています。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問","question":"このリハビリサービスを、どのぐらいの人数の方が利用すると予定しているのかということと、その人数に対して、人材育成といいますか、リハビリ専門チームをつくっているのか。この２点について、お伺いします。","respondent":"早津高齢福祉課長","answer":"現在、身近でリハビリは３カ所を予定しておりますので、その３倍で、個性の違う方で１２０人ぐらいということになろうかと思います。水中運動についても、１クールでは大体４人ぐらいの方を予定しています。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問","question":"何点か聞きたいんですけれども、まず、利用者の見込みのところで、まず身近でリハビリは、１回８名で２クールで、１カ所で４０名ぐらいというお話だったわけですけれども、これはいわゆる施設での利用可能な能力、受け入れ可能人数だと思うんです。先ほども、ほかの戸越台等を考慮しては、という質問があったんですけれども、そういうところとの関係で、実際に希望をどういうふうにつかんでおられるのか。","respondent":"早津高齢福祉課長","answer":"それに回数ということを数えて、枠というような形で考えてありますけれども、これは、その後、希望者等の動向を踏まえながら、また検討をしてまいりたいと考えています。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そうすると、身近でリハビリ、あるいは水中運動、両方の利用の希望といいますか、ニーズというか、そこのところはまだこれからということですか。わかりました。実際に、ここら辺の見通しがどうなっているのかというのを、ちょっとお聞かせいただければと思うんですが、そこのところはどうでしょうか。そこら辺のところは、ちょっとどういうふうな体制なのか、どうでしょうか。","respondent":"早津高齢福祉課長","answer":"一定のトレーニングも必要でしょうから、それが直接そのままというわけではありませんが、全体状況として、理学療法士も、全国的にはかなりの人数が増えてくるだろうという中で、新しい方をそのままこちらのほうにというわけではないんでしょうが。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、専門のチームとしては大丈夫と、そういう見通しだということですね。利用者負担のところで、１割ということなんですけれども、具体的にそもそも介護報酬との関係で１割と考えておられるのかと思うんですけれども、介護報酬といいますか、どういうふうになるんでしょうか。具体的に１割だと幾らぐらいになるのか、そこのところはどうでしょうか。","respondent":"早津高齢福祉課長","answer":"介護報酬に相当する全体の金額が幾らぐらいかというのは、現在、さくら会、それから実施を考えているところと詰めているところです。条例の中にもありますように、その辺のところについては、制度推進委員会を経て規則で明確にしていきたいと考えています。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、大体、今の時点でどのぐらいというのがあったら教えていただければと思いますが、そこのところはお願いしたいと思います。予算のところでは、今回は2,０３６万円となっておりますけれども、その予算の考え方がどうかというところがちょっとあるんです。それから、それに伴って予算がどのぐらいになっていくのかというところを聞きたいんですけれども、そこのところをまずお願いします。","respondent":"新美保健高齢事業部長","answer":"先ほどの専門チームの関係なんですが、現在、行っている検討の中でも、地元の昭和大学病院リハビリテーション科の教授等にも入っていただいておりますので、そういった方々に、今後、ドクターとしてはご協力いただきたいと考えております。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"意見","question":"すみません、ちょっと私聞き漏らしちゃったかもしれないんですけど、３カ所でスタートすると、その３カ所がどこかというのを聞き漏らしたので、ちょっと改めてお願いしたいと思います。横出しサービスとして、今後どういうふうに考えていくのか。それと保険料はどうしてもリンクしていきますから、これとの関係の考え方がどうなのかということをお聞かせいただければと思います。","respondent":"早津高齢福祉課長、新美保健高齢事業部長","answer":"かなりの年数は大丈夫だろうと考えていますが、その後の事業の実施を見ながら考えていきたいと考えています。ということで、今後の規則等に定める中で、やはり介護保険事業計画と同じように、３年１期でどう見込めるか、保険料額等も含めまして、特別給付についても３年１期の１期ごとの見直しをしていくという仕組みにしておくことが。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問","question":"先ほど、ちょっと私の質問の仕方が悪かったのかもしれないんですけれども、いわゆる横出しの考え方、それから、基本的な考え方として、３年ごとに見直すんだというお話なんですけれども、そこら辺の横出しサービスの位置づけといいますか。今回、これも全国初という説明だったと思うんですけれども、今後の横出しサービスそのものについての考え方というのを聞いておきたいと思うんですが、どうでしょうか。","respondent":"早津高齢福祉課長","answer":"今回のリハビリにつきましては、法定の通所リハビリが、実施場所が老人保健施設か診療所、病院というふうに限られている中で、リハビリの需要が多いことにどうしたらこたえられるかという中で行ったものでありますので、横出しサービスの実施については。","id":"exchange-022"},{"speaker":"須藤委員","kind":"質問","question":"いろいろな形で、ここでは要支援、要介護者を中心ということでありますけれども、要支援になる前の高齢者に対して、今、皆さん方からいろいろな意見が出てきたと思うんですけれども、その辺との兼ね合いを、これはこれで同時に並行していっていただくけれども、同時に健康、福祉、医療という三つを連携させるというシステムを、これを中心にしながら構築していこうというお考えはいかがでしょうか。","respondent":"新美保健高齢事業部長","answer":"要支援になる前の方々、一定の年齢以上になれば、健康づくりに積極的に取り組んでいただけるような環境づくりを、健康づくりプランのほうで、これから地域につくっていきたいということで、これは両輪でやっていくという考え方です。","id":"exchange-023"},{"speaker":"須藤委員","kind":"質問・要望","question":"これからというと、また時間がかかるわけなんで、今、せっかくここに種を一つ植えられてきているんですから、ある程度の年配になったら健康増進というのは無理なんですね、健康維持という考え方を取り入れていかなきゃいけない。そういうこと自体が、要支援にならない、また介護者を増やさない状況になろうかと思うんですけれども、その辺はいかがでしょうか。","respondent":"新美保健高齢事業部長","answer":"すみません、この次というのは平成１５年度という意味ですので、もちろん新年度から早速に、健康塾の拡充、それから、ふれあい健康塾の新設、また、４０歳台からの健康センター等を活用した健康塾等、健康づくりの機会をできるだけ地域の中につくっていくということに。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問・要望","question":"リハビリのほうで、当面、３カ所から、また水中運動のほうは１カ所で、これからもいろいろなプールの活用を考えていきたいという答弁だったんですけれども、本来であれば、今、南大井の施設は老人保健施設１カ所しかないんですけれども、私は、施設そのものが足りないというふうにずっと言ってきたんですけれども、老人保健施設そのものを拡大していく、増設していくという考えというのはないんでしょうか。","respondent":"早津高齢福祉課長","answer":"品川区でこれを適用したときには、今後３年間の１、２段階の軽減者に対して、その分を４、５段階の方にご負担いただくのが現在の２５０万円のままでも大丈夫なので、２５０万円のまま据え置くという考え方です。","id":"exchange-025"},{"speaker":"宮崎委員","kind":"質問","question":"おそらく、試算されたのかと思うんですが、例えばこれが２００万円になった場合に、現在の第４段階が何人ぐらい第５段階になるはずだったと言ったらあれなんですが、何か試算されたんですか。","respondent":"早津高齢福祉課長","answer":"ちょっと、今、手元にございません。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"提案","question":"意見を。一つ、今回、提案の第二期の保険料のところ、そして、基準所得額の２５０万円というところは、そのとおりだと思います。やっぱり心配なのは、先ほど、私も質問のところで出しましたけれども、これが１号被保険者の保険料にストレートにリンクしていくというところで、非常に心配が出てきております。この意見を述べておきたいと思います。基本的には、この条例に賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"}]},{"id":"topic-03","title":"議員提出第２号議案、品川区介護保険制度に関する条例の一部を改正する条例","agenda":"議員提出第２号議案、品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"宮崎委員","kind":"提案","question":"今回、本会議の質問等、また、私自身も昨年の第４回定例会で質問したんですけれども、ご存じのとおり、なかなか区のほうからやるという答弁がいただけないものですから、あえて私のほうから、議会として条例を改正して、条件を緩和してハードルを低くしていこうという趣旨で、条例の改正を提案させていただきました。私どもの提案では、年間の収入の９６万円を１２０万円に上げたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"須藤委員","kind":"質問","question":"全然違うんですけれども、老人保険が、昨年１０月から１割負担、２割負担となったんですけれども、この辺の割合というのは、今、１割負担が何割で、２割負担が何割というのは、わかりますでしょうか。","respondent":"蓼沼高齢事業課長","answer":"手元の資料ですと、１月８日時点での割合になりますけれども、一定以上所得者２割の方が１７％、それ以外の８３％の方が１割となっています。","id":"exchange-029"},{"speaker":"須藤委員","kind":"質問","question":"提出者のほう、住まいを借りている方に関しては、ここに書いてあるんだけれども、ご自分で持っている方も、固定資産税等々の支払いがあるわけですよね。そのことについては全然触れてないんだけれども、それはなぜですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"宮崎委員","kind":"意見","question":"確かに、自分で持っている方もいろいろなそういう負担もあるというのは承知しておりますが、どこで線を引くかということで、あえてそこまではできない、今の家賃が大変だという方に対応しようということで、そこで線を引かせていただいているということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"辻副委員長","kind":"意見","question":"現在、区で実施しているのは平成１３年１０月からスタートした制度ですよね。現在、どのぐらいまでやっているか。これは申告になっていると思うんですよね。該当者に申告で徹底されていないのかどうなのか。その辺の状況というのはどのように、区はつかんでいらっしゃいますか。","respondent":"早津高齢福祉課長","answer":"そのほか、７月の広報紙におきまして、この制度の周知を図っているというような状況です。","id":"exchange-032"},{"speaker":"辻副委員長","kind":"提案","question":"要するに、今、第５段階になっているわけですよね。そのことが矛盾じゃないかということで、私はこの提案をさせていただいたんです。というのは、特別に何らかの措置をとらないと、非課税という形でどおんとくくっちゃっているものですから、これはどうしたって、生活保護を受けるか受けないかというのは、あくまでこれは本人の申告でやるわけですよね。ここをちょっとお聞かせいただきたいと思います。","respondent":"早津高齢福祉課長","answer":"その中でも、低所得者対策をどうすべきかというようなことが、一つの議論の論点と聞いてありますので、その国での議論を、私どもも注意深く見ていきたいと考えています。","id":"exchange-033"},{"speaker":"辻副委員長","kind":"提案","question":"私は、今回の提案に対して、考え方としては、基金は確かにスタートの第１段階でスタートしたわけです。それを取り崩してどうだという論議というのは、やめたほうがいいと思います。そうでないと、じゃあ基金が取り崩されてしまった後どうするんだという論議になっちゃう。それと、今現在基金があるから、それを取り崩してしろと言っても、今回の提案の段階の根拠には、私はならないと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"}]},{"id":"topic-04","title":"平成１５年請願第６号、健康保険本人３割負担などの凍結・中止を求める国への意見書提出の請願","agenda":"平成１５年請願第６号、健康保険本人３割負担などの凍結・中止を求める国への意見書提出の請願","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"今、健康保険本人３割負担凍結・中止を求める運動が、ここにも書いてありますけれども、日本医師会、歯科医師会、薬剤師会、看護協会、ほかにも地域によっては検査技師の団体とか、いろいろな団体が署名運動とかに合流しているようです。一つちょっと伺いたいんですけれども、窓口負担が１割から２割、今度は２割から３割となるんですけれども、この間の医療費が実際にどういうふうに動いてきたのか。","respondent":"蓼沼高齢事業課長","answer":"窓口負担の数字は、今すぐには出てこないんですけれども、窓口負担ではなくて、ちょっと違いますけれども保険料について言いますと、総報酬制が取り入れられるということで、年間の保険料の増額が、現行総報酬ベースに直しますと７.５％が。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"意見","question":"今のは保険料のほうですよね。これが、実際に、どういうふうに資料等で出ているのかというところで、ちょっと聞きたかったんです。実際の医療費の負担がどうなるかというのがよくわからなければ、実際に１人当たりの医療費の動きというのは、１割から２割、あるいは２割から３割になると、どの程度になるのかという試算、あるいは、この間の結果の数字というのはありますか。","respondent":"蓼沼高齢事業課長","answer":"都のレベルでは、５.３％減少しているというような数字は聞いてあります。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"高齢者のほうだと、今、ちょっと健康保険の本人の数字が何かあればと思って伺ったんですけれども、そちらのほうの数字がないということなんで、高齢者のほうで参考にお伺いしたということです。","respondent":"蓼沼高齢事業課長","answer":"直接、減少した中身について分析をされているものでもございませんので、その因果関係については、今のところ、ちょっとわかりません。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっとなかなかこの話をしてもかみ合わないんで。特にこの点でちょっとお伺いしたいのは、今回の健康保険のほうでわかれば、わからなければ国庫のでも、できたら両方でわかればいいんですが、国庫負担がかなりここのところ減ってきていますよね。特に、健康保険のほうでも減らしてきていたはずなんですけれども、そこのところの動きがどうなってきたのか、わかりますか。","respondent":"蓼沼高齢事業課長","answer":"すみません、健康保険のほうのデータについては、ちょっと持ち合わせておりません。","id":"exchange-038"},{"speaker":"宮崎委員","kind":"質問","question":"質問してもなかなかかみ合わないんで、どうしようかなと思っているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"宮崎委員","kind":"質問・要望","question":"わかりました。質問してもなかなかかみ合わないんで、ちょっと意見を言わせていただくことにしたいと思います。ですから、今回は、やっぱり、受診者、国民のほうに負担を求めるということではなくて、政府のほうでもちゃんと医療費に対する国庫負担を増やしていくという方向が改善の道だと思いますので、ちょっと質問がなかなかかみ合わなかったんですけれども、意見として、この請願には賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"須藤委員","kind":"質問・要望","question":"それからやはり、日本人の皆保険制度というのが昭和３６年からスタートしてきて、非常に世界に冠たる保険制度だろうと思うんですが、これ自体をキープする、保持していくためには、どうあるべきかというのが、厚生労働省で、政府も含めて、今、一生懸命ワーキンググループがやっているところなんですけれども、その辺の動き方もどうなってくるのか見えないと、我々もここでは。","respondent":"蓼沼高齢事業課長","answer":"全体の医療費ですけれども、全く雑ぱくな数字ですけれども、年間３０兆円程度、医療費が支出されていて、年間、大体１兆円ずつ増加しているという現状があります。","id":"exchange-041"},{"speaker":"須藤委員","kind":"質問","question":"高齢者についても、昨年１０月からということだったんですけれども、１０月の時点で比較されたから減少という数字を、先ほど、答えられたと思うんですけれども、これも時間の経過とともに、やはり疾病があればそこに通っていくというのが当然の流れだと思うんで、それも順次改善されてきているというふうに、改善という言い方はおかしい、何と言うのか。","respondent":"蓼沼高齢事業課長","answer":"ただ、今、委員おっしゃいましたように、１割負担になって、従来の定額制と比較して、自分が実際にかかっていた医療費がよくわかるようになったということで、抑制といいますか、適切な医療、受診というような形での普及啓発といいますか、そういうようなことで、今後また。","id":"exchange-042"},{"speaker":"須藤委員","kind":"質問・要望","question":"昨年の１０月から１割負担、あるいは、２割負担になったけれども、それがまだ、私は、２カ月、３カ月では１年間通しての数値にはならないと思うけれども、だんだんとまた違う傾向が出てきています、１０月当初と違うというようなことはちらっと聞いているんですけれども、その辺のところで、わかるところがあれば教えていただきたいと思います。","respondent":"蓼沼高齢事業課長、新美保健高齢事業部長","answer":"今のところ、１０月に制度が変わりまして、数字的には、１１月、１２月までの数字しか、今、はっきりしてございませんけれども、その中では、減少傾向というのは、今のところ続いておりまして、今後の明らかな形での動きといいますか。ただ、今回はまだそこを見る時間的ものが、まだ１２月診療までしか我々のほうに来てませんので、３カ月程度ではちょっとまだあれなんで、今後の推移を注視していく必要があろうかと思います。","id":"exchange-043"},{"speaker":"須藤委員","kind":"質問・要望","question":"同じように、ここに請願が来ているのは、健康保険本人３割ということなんで、そちらが主になると思うんですけれども、そこも先ほど言ったように、１割から２割になったときの状況がわかれば、教えていただきたいと思うんですが、いかがでしょうか。先ほど言ったように、メンバーに対して違うんで、わかりにくい状況であれば、また調べておいていただきたいと思うんですが。","respondent":"蓼沼高齢事業課長","answer":"健康保健１割から２割のときの動きにつきましては、すみません、今ちょっと詳しい状況を把握しておりませんので、また調べて報告させていただきたいと思います。","id":"exchange-044"},{"speaker":"山路委員","kind":"質問・要望","question":"医療費３割負担問題というのは、医療保険制度の抜本的な改革で、今回、問題になっているわけなんですけれども、国民健康保険がこの課じゃないので、非常に聞きづらいんですけれども、品川区の両保健所長もいらっしゃいますので、急速に高齢化社会を迎えまして、医療費の増大が進んでいるという話も聞くんですけれども、その辺の実態を何かつかんでいらっしゃったら、説明をしていただきたいと思います。","respondent":"蓼沼高齢事業課長","answer":"もう少し広いスパンで見ますと、やはり増加傾向はあろうかと思いますし、国全体の医療費につきましても、毎年約１兆円ずつ増加しているという状況です。","id":"exchange-045"},{"speaker":"山路委員","kind":"質問・要望","question":"さらっと言われたんですけれども、現実には、医療費の増大というのは深刻な問題で、崩壊すると言われているぐらいなところに来ているんじゃないかと思うんですよ。このままいきますと、３年、５年後には、これだけの見込みというのは、厚生労働省のほうでは話は出ていましたよね。品川区のほうで、そういうことを検討された経緯があったら、お知らせをいただきたいと思います。","respondent":"新美保健高齢事業部長","answer":"医療費の問題は、医療保険制度も含めて、基本的には国全体の問題ですので、我々としては、老人医療制度の運営は担当しておりますけれども、制度設計、制度の検討は国のほうで行っていく問題というとらえ方ですので。","id":"exchange-046"},{"speaker":"山路委員","kind":"質問・要望","question":"なるほどそうですね。その辺をどうとらえるのかと思うんですけれども、国の制度ですので、ここでどうこうというじゃないんですけれども、当然、影響力があるわけですので、その辺の検討といいますか、また将来への対策といいますか、その辺についてお聞かせいただきたいと思います。","respondent":"新美保健高齢事業部長","answer":"制度全体の設計は国なわけですが、中でも、国民健康保険につきましては区の事業ということもありますので、その点からの医療費と保険料負担、あるいは患者負担の問題というのは、私ども区のほうとしてもきちんととらえ、必要な対策はとっていかなきゃならないという観点で。","id":"exchange-047"},{"speaker":"金高委員","kind":"質問","question":"ここに出ている３割負担というのを、例えばこれをそのまま凍結してしまうと、早い話、２割にすれば、当然また赤字が増える、これを３割にすることによっても、また一時的には受診者が減っても、また高齢化社会になってまたそれがさらに増えていくというイタチごっこのような様相があるものですから、やはりこの点は、国の抜本的な形も見守っていく必要があるんじゃないかという気がするんです。","respondent":"新美保健高齢事業部長","answer":"医療負担をどういうふうにしていくのかということは、ほんとうに国全体の問題になっていることは確かですし、単にどこか部分的な改革では済まないという認識に、全体がなっていることも承知しております。","id":"exchange-048"},{"speaker":"須藤委員","kind":"質問・要望","question":"私のほうは、先ほど来お願いしていますように、地方議会としてきちんとした答えを出していく上では、もう少し調査をしていかないとというような思いがありますので、先ほど来お願いしてあります資料をいただいてから、また審査をさせていただきたいと思いますので、きょうのところは継続という形で取り扱っていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"山路委員","kind":"意見","question":"先ほども言いましたけれども、医療保険制度の抜本的な改革の一環ということですので、ここで簡単に３割負担の凍結・中止をすぐ採決、どうこうという問題ではないと、私は思っているんです。もっと国の動きを見守っていかなきゃいけないし、品川区の実態も調査しなきゃいけないしということで、もうしばらく時間をかけてお願いしたいというところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"宮崎委員","kind":"質問・要望","question":"特に医療団体から非常に強い反対が出てきている。それから、今、地方議会のほうからも、凍結、あるいは見直しを求める意見書、決議というのが非常にされているというのが実情です。ですから、そういう意味では、住民により近いこの議会が、住民の立場に立って国にものを言う、意見をするというのは当然だと思いますので、きょう皆さんに賛同していただいて、ぜひ、採決ということで主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"金高委員","kind":"質問","question":"先ほど、発言させていただきましたとおり、まだ抜本的な話が出ていないという形において３割と。結局、めぐりめぐってくるのは、すべてそこに住んでいる住民の方々ですから、ただ単にこの場でもって３割負担を凍結する云々という形よりも、もし考えるならば、地方議会から制度改革そのものをどうするかということも含めて、もっともっと制度的なものをやはり考えていかなければいけないという面があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"辻副委員長","kind":"質問・要望","question":"むしろ、今一番問題になっているのは、よくここで挙げられているのは、政府管掌保険が２割のままいっちゃうと、平成１５年度で3,４００億円の赤字になるということについてどうするんだという論議がまさしくされないままいっちゃうと、これは法律の制度上、政府管掌保険ですから、赤字負担が中小企業とか、そこに勤めている人たちに保険料として跳ね返ってきちゃうわけですよね。これは私どもの見解です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"藤原委員","kind":"質問・要望","question":"辻副委員長がすべてお話ししていただいたんですけれども、この請願は、健康保険本人３割負担の凍結ということで、きょうの質疑の中で、所管が違うということで、高齢者が中心になってしまったと思うんですけれども、やっぱり３割負担などの凍結・中止を求める国への意見書提出の請願なので、もう少し審議したいと思いますので、継続でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"}]},{"id":"topic-05","title":"平成１５年請願第７号、介護保険料・利用料の負担軽減と特別養護老人ホームの増設を求める請願","agenda":"平成１５年請願第７号、介護保険料・利用料の負担軽減と特別養護老人ホームの増設を求める請願","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"私も地域を回っていまして、わずかな年金から引かれる保険料が高いとか、利用料負担が大きく、必要なサービスが受けられないという悲鳴というのは聞かれないんですね。私が回っているところにおいては、ほんとうにありがたいということしか出ないんですけれども、所管に直接区民からこのような意見というのは上がってきているんでしょうか。","respondent":"早津高齢福祉課長","answer":"苦情の処理というものをしています。保険料につきましては、やはり保険料が高いとかいう苦情が何件か寄せられているようです。利用料については、私どものほうでも、高いというようなお話を聞いた記憶は、特段ございません。","id":"exchange-055"},{"speaker":"藤原委員","kind":"質問","question":"高いというのは、何件かしかないんでしょうか。何十件とか、何百件じゃなくて、何件かしかないんでしょうか。","respondent":"早津高齢福祉課長","answer":"件数はちょっとあれなんですが、保険料は、やはり最初に負荷されたころは多かった。多かったと言っても何十件ぐらいだったと思いますが、保険料に関する事柄も、段々と減ってきてございまして、ストレートに保険料がというのは、月に直せば１桁程度のお話だと思います。","id":"exchange-056"},{"speaker":"築舘委員","kind":"質問・要望","question":"特別養護老人ホームや老人保健施設を増設というようなことなんですけれども、介護保険で、在宅福祉を充実させようということで、デイサービスであるとか、家族の負担を低くすることによって、在宅で頑張れるというようなことを、今、求めているわけです。その点に関して、在宅福祉が質的にも高まり、数的にも、それが楽になったという件数が増えているのかどうかということをお聞かせください。","respondent":"早津高齢福祉課長","answer":"サービスの質につきましても、品川区は早くからサービス評価に取り組みまして、在宅３本柱と言われるホームヘルプ、それからショートステイ、デイサービスがひととおり終わりました。","id":"exchange-057"},{"speaker":"築舘委員","kind":"質問","question":"だからそれは都下とか、もっと伸ばして、近くの県とかと提携しながら、そういった施設を活用できるような形を連携してとるようなことも必要だと思うんですが、その点に関してはどうでしょうか。","respondent":"早津高齢福祉課長","answer":"区外での特別養護老人ホームという視野もですが、やはり、住み慣れた地域での生活ということが、基本的には望まれているかという形の中で、区外にということは、現在のところは考えていないわけですが、現に、区外にかなりの特別養護老人ホームがあるわけですけれども。","id":"exchange-058"},{"speaker":"築舘委員","kind":"質問・要望","question":"入所の審査会みたいなこともあって、大変な方は優先して入れるというようなことも、今やっていただいているので、そういうことでの総合的な面で、さらに充実していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"金高委員","kind":"質問","question":"こういったことがなされていても、なおかつ保険料が高いか低いかという論議が出てくるという、その辺のちょっとした差があるわけですけれども、その辺はどのようにお考えですか。","respondent":"早津高齢福祉課長","answer":"保険年金課等に寄せられます保険料の関係でも、例えば督促状がいったことを契機に、未納だった方が電話で保険料が高いとかというようなことをおっしゃるというような例もかなりあるようでして、何かと比べて高いとかというようなことでは。","id":"exchange-060"},{"speaker":"金高委員","kind":"意見","question":"いずれにしても、この3,３００円の据置きも、過去３年間実施した上でもって、なおかつ基金をしっかりとこちらで取り崩して保険料を値上げしないのは当然であるというようなことが書いてあるわけです。当然のことですが、使ってしまえば減ってしまう。この基金の維持管理、あるいは、今後それをどのような形で維持していくかということも含めて、何かありましたら、ちょっとお聞かせ願いたいんですが。","respondent":"早津高齢福祉課長","answer":"あくまでも、基金については、そういった形で慎重に検討を重ね、需要にこたえるような形での丁寧な使用が必要であろうと考えています。","id":"exchange-061"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっと何点か聞きたいんですけれども、年金から天引きされるという中で、私のところは、やっぱりかなり負担が大変だという意見をよく聞きます。そこのところは、どんな感じでしょうか。それから、保険料の苦情といってもいろいろ内容があろうかと思うんですけれども、今回、保険料が高いという角度からいくと、高いという苦情が、苦情の中のどのぐらいを占めているのか、そこのところはどうでしょうか。","respondent":"早津高齢福祉課長","answer":"今年度の４月から９月の上半期をまとめたもの、苦情という形で寄せられたものが１２０件あります。","id":"exchange-062"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そこのところがわかったら、もう１回お知らせいただきたい。ここには保険年金課長がいらっしゃらないので、国民年金ですと、大体５万円そこそこが平均の収入額かなと思うんですけれども、そこのところは、今、どういうふうになっているのか。要するに、年金が幾らで、そこから幾らを引いているのか、そこのところはわかりますか。","respondent":"早津高齢福祉課長","answer":"１号保険者は５万9,０００人いるわけですけれども、その中で、年金収入が平均で幾らぐらいでということまでは承知してございません、申しわけございません。","id":"exchange-063"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちなみに平成１２年度のときは、全体の何件中４０９件が保険料の苦情だったのか。そこのところはどうだったでしょうか。それからあと、東京都全体の保険料の苦情と比べても、品川区はちょっと高かったように思うんですけれども、平成１２年度、あるいは平成１３年度の上半期のところでもいいんですが、保険料の苦情というところで、もうちょっと詳しくお知らせいただきたいと思います。","respondent":"早津高齢福祉課長","answer":"保険料に寄せられた苦情をちょっと見てみますと、これはしばらく前のことですが、１０月から保険料が倍になって高いということが、「高い」ということになるんでしょうが、そのほか、納入通知書の表示がわかりにくい、口座振替の申請の手続がわかりにくい。","id":"exchange-064"},{"speaker":"宮崎委員","kind":"質問・要望","question":"保険料の引き下げを、ここで求めているんですけれども、今回、本来は3,４３８円になるところを、基金から３億円を取り崩して減額に充てて、3,３００円に据え置いたという説明だったんです。ちょっと聞きたいんですけれども、なぜ３億円なのか。あえて３億円ということでの取り崩しというのは、なぜ３億円なのか。もっと取り崩すということはできないのかということは、どうでしょうか。","respondent":"早津高齢福祉課長","answer":"そうした中で、貴重な基金をどのように使っていくのがよいかということを慎重に検討しました結果、第一期と同額のレベルに保険料を据え置くことで、なおかつ不足しているサービスについて、市町村特別給付として現物給付型のサービス。","id":"exchange-065"},{"speaker":"宮崎委員","kind":"意見","question":"平成１３年度も３６２件の苦情で２９６件というご説明だったんで、かなり保険料に対する苦情というのが多いと、改めて感じました。それから、今、私、なぜ３億円なのかということで、一部には、特別給付のために使うと、これはこれで、午前中も説明を受けました。何で第三期、第四期のところまで置いておくのかというところが、今の説明でもわからないんです。","respondent":"早津高齢福祉課長","answer":"つまり、大切な基金を最も納得がいただけるような形で使うにはどうしたらいいのかということを考えた上での、今回の考え方です。","id":"exchange-066"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、あえてなぜそれをしないのかというところなんですよ。一つ理屈のところでは、３億円じゃなくて、例えば４億円、５億円取り崩すことになれば、3,３００円がもうちょっと下がるということになるのは、理屈上もそうなるかと思うんですけれども、そこのところをちょっと、そうなるかどうか確認しておきたいんです。平成１２年度で介護保険制度が始まる当初は、入所待ちが何人だったのか。","respondent":"早津高齢福祉課長","answer":"直近状態ということですが、９月に行いました入所調整会議での希望者が６４０名です。３月に今度予定しているんですが、これはまだ集計が取れておりませんので、今のところ、数字はまだ確定できておりません。","id":"exchange-067"},{"speaker":"宮崎委員","kind":"意見","question":"保険料のほうですけれども、今のお話だと、要するに3,３００円するためには３億円だと、そういう説明だったんです。私はそうすべきだと、私はあえて主張しておきたいと思います。では逆に言えば、第２回目はどうなのか。そこのところが一つ。そこら辺の、いわゆる入所待機となるのは、どういう基準、何をクリアしなきゃいけないのかというのを、改めてちょっと聞いておきたいと思うんです。","respondent":"早津高齢福祉課長","answer":"ただし、このときは、第１回目の会議がそのように既にエントリー済みの方という形で行いましたので、４カ月の申込み期間で実施したものです。それから、入所に当たっての判定の項目等ですが、一つは要介護度です。","id":"exchange-068"},{"speaker":"宮崎委員","kind":"質問","question":"実際問題、昨年１０月時点で６４０人いるんですけれども、毎年毎年入れるというんですか、現実問題、新しくつくっていませんから、亡くなってあきが出て入るということになるんですけれども、そこの回転といいますか、そこのところはどういう状況なんでしょうか。","respondent":"早津高齢福祉課長","answer":"そういう方は除きまして、要介護であればということですが、そういう方については、全員をカウントの結果が６４０人という数字です。入所者はどのぐらいかですが、押しなべて言いますと、１年間で２００名程度の方が入所されているという実績です。","id":"exchange-069"},{"speaker":"宮崎委員","kind":"質問・要望","question":"やっぱりここのところで、介護保険の建前というんですか、介護サービスを自分たちで選べるというのがやっぱり大前提なんですよね。それで新たに負担を求めてきたんですけれども、今の、例えば特別養護老人ホームの状況を見ると、希望してもすぐに入れるという状況ではないんです。ここのところを、改めて区のほうの考え方を聞かせていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"６４０名の方が希望をされていて、２００名ぐらいの方がということですから、単純に計算すれば３年というような数字が出てまいりますが、こういうときに、希望されている方の内容というものが、やはり必要になるわけです。","id":"exchange-070"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、必要な方がというふうにおっしゃいましたけれども、やっぱりそこの必要なというところがものすごく狭まっていることは現実だと思うんですよ。希望しているのがこれだけいるというところにどうこたえるかというのが、やっぱり、今、大事なところだと思います。蛇口を閉めれば、当然、待たざるを得ない状況というのは当然増えるわけですよね。ここのところに気持ちを寄せていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"辻副委員長","kind":"提案","question":"保険料が高いということについて、高いというのは、サービスの量から出てくるわけですから、どこに比べてどうだというのは、それはできるでしょうけれども、根っこの部分の仕組みからいっちゃうと、今回言っているように、特別養護老人ホームや老人保健施設というものも計画的にやっていかないと、そのまま増設しちゃったら保険料に跳ね返っていっちゃうわけですよね。これは仕組みです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"須藤委員","kind":"提案","question":"特別養護老人ホーム施設等についても、第二次長期基本計画、第三次長期基本計画で、ずっと今まで、我々議会の中で、理事者と相談しながら、あるいは、理事者がいろいろとご提案いただたものを受けながらという形で進んできて、介護保険制度をつくってきているんで、ここで急に来たということは、ちょっと矛盾ができてくるので、採決をしていただいて、答えを出していただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"宮崎委員","kind":"質問・要望","question":"これは、ぜひ採択をしていただきたいと、私のほうからも皆さんのほうにお願いしたいと思います。健康保険のほうも、そういうふうな政府のほうの説明なんですけれども、前回の決算特別委員会のときでも、普通徴収の収納率が８割近くにきていると。そういう点では、この請願は、所得の少ない方々への配慮を求めた内容ですから、私はこれの採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"}]},{"id":"topic-06","title":"平成１４年請願第２８号、「遺伝子組み換えイネ」を承認しないこと、並びに、表示に関して国への意見書提出を求める請願","agenda":"平成１４年請願第２８号、「遺伝子組み換えイネ」を承認しないこと、並びに、表示に関して国への意見書提出を求める請願","exchanges":[{"speaker":"辻副委員長","kind":"質問","question":"これは、委員長と副委員長の立場でどうするかといろいろ悩んで、紹介議員にも聞いてみたんです。請願者は、がちがちのノーなんですね、１番目の請願内容は。要するに、しないようにという。たまたま所管の委員長がうちのものですから、どうするかねということで、昼休みも検討したところなんです。ですから、２番目は、表示するんだったら表示するんです。その辺が、ちょっと困っちゃったなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"横山委員長","kind":"質問・要望","question":"流れとしては、どういった答えを出すかというところにあろうかと思いますけれども、皆さんのほうでほかに扱い、ご意見等があれば伺いたいと思います。平成１４年請願第２８号、「遺伝子組み換えイネ」を承認しないこと、並びに、表示に関して国への意見書提出を求める請願を継続することにご異議ございません。〔「異議なし」と呼ぶ者あり〕 平成１４年請願第２８号は、継続とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"横山委員長","kind":"質問・要望","question":"その他を行います。私のほうから、今定例会の一般質問中、厚生委員会に係る項目について、所管質問をなさりたい委員がいらっしゃいましたら、その基礎となる一般質問の項目とそれに関する質問内容を、この場でお願いいたします。一般質問のフォローがございましたら、遠慮なくお申し出いただきたいと思います。〔「なし」と呼ぶ者あり〕 別段ないようですので、この項目を終了します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/749973?Template=document&Id=3042#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":55536,"voices":174}},{"id":"h15-20030303-8","meetingId":"h15-cm03","date":"2003年3月3日","dateIso":"2003-03-03","committee":"建設委員会","time":"午前１０時０４分～午後６時１４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件抜き出しています。","topics":[{"id":"topic-01","title":"本日は１０名の傍聴申請がございますので、ご案内をいたします。 では、２の議案審査","agenda":"本日は１０名の傍聴申請がございますので、ご案内をいたします。 では、２の議案審査","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"予算化のところだけ見てきたんですけれども、今まで２本の条例でそれぞれに予算がついていたわけですけれども、私道整備の方は年間予算、今オーバーするぐらいの申請があると、片方の排水設備の方はもう整備が済んでいて申請は非常に少ないということなんですけれども、これを一本化すると当然予算一つになっているんだと思いますけれども、予算化したものが全部いわゆる私道整備の方に使われていって。","respondent":"岩田管理工事課長","answer":"したがって、これはどれくらいまず出てくるかというのはちょっと予測できない状態です。ですから、当面、来年度予算につきましては、この下水管の補修費用として４００万円程度を計上しています。全体の中で様子を見ながら、それは進めていく予定でおります。","id":"exchange-001"},{"speaker":"林（和）副委員長","kind":"意見","question":"今の新旧対照表でいろいろ説明していただきまして、本当によくわかりました。今までここ１０年の助成の件数といいますか、どの程度になっていたのか、そして今度このように新しく変わってきますと、大体１００％と９０％というものの助成はないわけですけれども、大幅に拡充されまして件数が結構伸びるんじゃないかというふうに思いますけれども、その予想はどういうふうに考えていますか。","respondent":"矢部下水道河川課長、岩田管理工事課長","answer":"私道排水設備助成の実績について、ご報告します。平成元年度からのデータなんですけれども、平成元年度から平成１０年度までの１０年間の平均としますと、年間１．８件申請があります。私道の舗装の方は、１３年度で１４件、１４年度が２０件です。既に相談を受けて受理して、来年度へ持ち越さざるを得なくなったのが６件ほどあります。","id":"exchange-002"},{"speaker":"林（和）副委員長","kind":"質問","question":"とにかくこういうふうな状況だから、こういうふうに変えてきたんだと思うんですけれども、こういうふうに変えたことによって助成率がアップしたわけですから、今度は件数もふえてくると思うんですよね。今後、来年、再来年はどういうふうに、相当伸びると思うんだけど。","respondent":"岩田管理工事課長","answer":"ただ４年に一度、こういう時期は若干少し延びるきらいがありますけれども、大体１０年ぐらいのベースではこれぐらいの予算規模のペースでちょうどうまく推移しているです。","id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"もうこれは本会議のときにも説明を受けて、効率化を図っていきたいという話もありますけれども、今課長が説明してくださった戸数が多くなって管理をするのがなかなか困難になったというところがあるんで、先ほど言った区内業者の活用がなかなかできないんでというところはわかるんですけれども、この効率化の問題と、その今課長が言われた区が管理をするのは困難であったということを。","respondent":"田村住宅課長","answer":"ちょっと私の説明が不十分だったかもしれませんが、私、経過の中で話したのは、昭和５３年に大井２丁目の改良住宅を区が建設して、そのときには３０戸という管理戸数だったんですね。その後、暫時、現在の３９３戸になるまで毎年のように移管の推進を図ったんですね。","id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"この品川都市整備公社が実際にいろんな形で区の事業を管理しているところが疑問なんかもありますし、それから新しいグループホームの方もあるみたいですけれども、実際にこの品川都市整備公社の方で事業概要ってなかなかインターネットで引いても出てこないんですけれども、実際に社員がどれぐらいいて、事業内容は最初の設立当初、開発のところとか不動産関係扱っていると出ておりますけれども。","respondent":"田村住宅課長","answer":"特に品川都市整備公社の所管ではないですけれども、資料を持っている限りでお答えしますが、株式会社品川都市整備公社は、業務の定款の定めで２条にあるんですが、都市整備に関する調査だとか、あるいは建築の建物、不動産の販売、賃貸、管理。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"６名の職員でいろんなことをやっているんですけれども、この区営住宅に関していえば、要はこの品川都市整備公社を支所にして、そこから、修理だったら修理の業者に委託をしているという形をとっているんですけれども、実際に品川都市整備公社が入っている事業というのは全部大体そうなんですよね、きゅりあんなんかの管理がそうみたいですし、この区営住宅の管理のことに限っていえば。","respondent":"田村住宅課長","answer":"そうすると、業者が例えば空家で事前にわかっていると、空家で事前にいつ出るというのは空家募集をやってわかるというときは別ですけど、急に水が出なくなっちゃった、エレベーターがとまちゃった、何とかというのに対応しなきゃならないですね。","id":"exchange-006"},{"speaker":"菊地委員","kind":"質問","question":"もう１点だけお聞きしたいんですけれども、株式会社ということですから、品川区が資本金を出資をして、株主がいらっしゃるんですけれども、役員、例えば理事と呼ぶのかどうなのかわかりませんけれども、役員の報酬ですとか、当然出資をされた会社に対する株式の配当というか、そこまでは課長の方ではちょっとわからないですか。","respondent":"田村住宅課長","answer":"私が効いている限りでは、出捐は全体の株主の９０％ということで聞いておりますし、あとは株主は残りの１０％はすごく細かい会社がいっぱいあるということなので、それくらいまでしか私の方は、会社内部の構成、配当金についても内容までは。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問・要望","question":"整理するんでちょっと教えていただきたいんですけれども、今回の条例については、先ほどからお話が出ておりますように、管理の一部、この新旧対照表によると、その住宅の検査あるいは管理の委託というのが細分化されておりますけれども、今お話に出ました入居者の管理については区が直接やっていますけれども、そして宅建管理センターに委託しているあれは区民住宅だけですか。","respondent":"田村住宅課長","answer":"今回の２２号議案につきましては、引き続き区営住宅の入居者管理は区で、将来的な課題で検討はしていますが、ことしの４月の段階では直営ということで、建物の維持管理等につきましては、東京都の住宅供給公社からことしの４月で株式会社品川都市整備公社に委託するものです。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問","question":"そうすると、今もおっしゃっておられましたように、将来検討されているようなとおっしゃいましたよね、要するに区営住宅の入居者管理、これも今区で直営になっているのを、この宅建管理センターの方へ品川都市整備公社を通じて委託をするというんですかね、そういう形に、要するに区営住宅も区民住宅も。","respondent":"田村住宅課長","answer":"それでなかなか受け手の方にＯＫしてもらえないというような現状がありますので、引き続き課題として、宅建管理センターに委託するかという話も当初はあったんですが、なかなかほかの関係のことには無理だとか、もうちょっと検討させてくれという話になったんで。","id":"exchange-009"},{"speaker":"堺委員","kind":"意見","question":"今課長がおっしゃっておられましたように、要するに、一つの建物を入居者管理はこっちがやって、検査とか修繕とかそれはこちらと、要するに一本化するというんですね、そういう仕組みの方がいいのかなと、何事も一本化していた方がスムーズにいくんじゃないかと思ったりもしたので申し上げただけで、何か検討されているですので、引き続きちょっとスムーズにいくように検討をお願いしたいなと思います。","respondent":"田村住宅課長","answer":"先ほどちょっと入居者管理については、地方自治法の定めで区に残さなければならない部分があるというのが一つで、やはり高額所得者だとか強制執行だとか、使用許可の取消だとか、それは法律的行政というのは地方自治法上、区に残さなきゃいけませんから。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"住宅供給公社から株式会社品川都市整備公社に変わることによって、住宅にお住みの方にとってのサービスが変わるような点があるのでしょうか、修繕とか修理とか管理において。","respondent":"田村住宅課長","answer":"ですから、特別こういうサービスがプラスアルファするというよりも、やはり先ほど申し上げた点、区が直接、株式会社品川都市整備公社が担当するということで、柔軟な対応が得られるだろうということと、区内業者の育成の観点から地元業者の育成が図れるということです。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"都営のところから区営に移管になった段階で、設備関係で都と同じじゃないというか、設備で低下した部分があったというのを以前聞いたことがあるんですね。そういった面で、区営になった段階で、水準的には同じと言われながら、実際に区でやっていく上において抜け出るということがあったんでしょうか。設備でということで聞いたんですけど。","respondent":"田村住宅課長","answer":"ちょっと個別の話なんで、一般論でちょっとお答えするのは難しいかと思いますけど、やはり計画修繕等の計画も、今までですと、東京都の住宅供給公社にお願いして、全団地見て、こういう老朽があるということでやっぱり必要だというような形で、予算要求内でランクづけをして。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"お伺いしたいのはなぜかというと、品川都市整備公社の仕事が本当にわからないんですね。だから、そういう特に議会のところで表にきちんと出ればいいんですけれども、その辺のチェックが果たしてできるのかどうかというすごい疑問を持っているんですけれども。","respondent":"田村住宅課長","answer":"一つは、ちょっと建設委員会の中で議論して良いのかちょっとわからないですけど、やはり区の関与する団体等については、議会に実情に応じて報告しているというふうに私ども認識しておりますし、一応区営住宅の維持管理については、区民住宅も既にやってましたので。","id":"exchange-013"},{"speaker":"菊地委員","kind":"意見","question":"全体を総合すると物すごい額になると思うんですけれども、たった６名の社員ですよね、部長を含めて、もちろん非常勤もいらっしゃるようですけれども、実際にそういう地方自治法にあると言われれば何とも言いようがないんですけれども、もう少し区民の税金を使って、実際にこういうところに回さざるを得ないというのは、そういうのがどうにも不可解でしようがないんですけれども、その辺をもう少し何か詳しく。","respondent":"田村住宅課長","answer":"ちょっと話が全体にわたっているので、もう一度私の所管している内容について説明します。","id":"exchange-014"},{"speaker":"菊地委員","kind":"意見","question":"採決をするんですよね。やっぱりこの条例で品川都市整備公社に変えていくというのは、私はちょっと現時点では反対という立場を表明していきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"田中委員","kind":"確認","question":"ちょっと確認の意味も含めましてお尋ねしたいんですが、先ほどの補助３０号線の西小山駅の駅前整備の事業としての対応ですが、なかなか用地取得が進まない中で、ちょっと異例かもしれませんが、逆収用という形でなっておりますが、これはもしそういう形ではなくて、通常の事前の交渉の段階でこの地権者あるいは権利者、関係者と話がスムーズに協議が進んだ結果、仮に進んだ場合のその品川区の負担する部分と。","respondent":"中島街路事業担当課長","answer":"私ども権利者の方とまだ同意に至らない段階での裁決申請ということですので、仮定で合意した時点と今回ということでの比較はなかなか難しい部分です。","id":"exchange-016"},{"speaker":"田中委員","kind":"意見","question":"収用というと、言葉上でいうと、ちょっと地権者の方の意に反してといいますか、いわゆる公権力によってというニュアンス的にとれる印象があるんですが、そういう部分を含めると、逆に品川区の負担がふえるということは、当事者の方にとってはある一定のラインでの理解も得られていることだと理解できますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"本間委員","kind":"質問","question":"それと、同じようにしてもう１本、２２号で、関係人が土地に対する損失補償以外の損失の補償がありますが、これはいずれも何かご商売をやっていらっしゃるような形ですけれども、そのはじかれた部分での中身、例えば営業補償ですとか、どういうふうな算出の仕方をしてこのような金額が生まれてきたのかとかいうふうな部分、もう１回教えていただけますか。","respondent":"中島街路事業担当課長","answer":"２２号、２１号の２事件の関係人に対しましては、基本的には同じような補償ですけれども、建物移転、工作物移転、不動産移転補償、移転雑費、それと営業補償です。","id":"exchange-018"},{"speaker":"船波委員","kind":"質問","question":"この予定地は、用途地域でいうと準工業地域ということですけど、準工業地域で工業地帯であったからそういう用途地域に指定されたんじゃないかと思いますけど、これがそうやって準工業地域に指定されたのはいつごろだったのか。あるいはそのころはその準工業地域に指定するというくらい工業がどれくらいあった地域なのか、その当時どういう状況があったのかお伺いしたいと思います。","respondent":"伊佐都市計画課長、浜脇住環境整備課長","answer":"住宅系に変わってきているですが、まだ現状、工場、倉庫等、この地域の中ではありますし、ご趣旨が、例えばこれを住居系に用途を見直すべきというご趣旨だとすると、現状、住宅系以外の工業立地もある以上。いつごろからマンションが建って、ちょっと統計を今持ってないんですが、私の印象では１５年ぐらい前から、たぶん５０年代の後半だと思うんですけれども、倉庫が住居にといいますか、マンションになったかというふうに見ておりました。","id":"exchange-019"},{"speaker":"船波委員","kind":"質問","question":"この地域が予定地が工業系だから、そういった住むための環境をよりよくするための配慮がより少ない地域なんじゃないかなと思ったわけですけれども、その辺の細かいところの違いはどうなんでしょうか、あるんでしょうか。","respondent":"伊佐都市計画課長","answer":"先ほどの話に戻りますけれども、まだ地域全体とすれば、準工業系の土地利用がありますし、これを今住居に変更というところまでは、地域全体、用途を見たときに、そういう考えはまだしておりませんし、今回の建築の用途・容積なんかも。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問・要望","question":"先日ちょっと本会議で、川西議員が東品川３丁目のまちづくりについての質問があったときに、私は部長の答弁がよく聞き取れなかったんですけれども、川西議員の要望ですか、あのときに、東品川３丁目のまちづくりについて新しいルールを考えていくというような答弁がなされたような、要望というか再質問というかやっていらっしゃった。","respondent":"伊佐都市計画課長","answer":"その辺の合意形成を図る上で、区としては、まちづくりのいろんなルールづくりに対する支援制度等もありますし、それに専門家を派遣するとか、いずれにしても地域の中で例えば地区計画とか建築協定というようなもの結んでいこうという意向があって。","id":"exchange-021"},{"speaker":"菊地委員","kind":"質問","question":"今の環境の部分でいいますと、この図面ですか、一番最後の８ページにあるこれなんか見ますと、１４階建ての共同住宅、これ２名ですよね、２名のこの新しい建物に対する側というのは、かなり広い庭みたいになっていて、かなり奥まったところから立ち上げられていますけれども、この新しい建物というのは、隣地境界まさに目いっぱいぐらいで立てるんでしょうかね、これだけだとよくわかりませんけれども。","respondent":"浜脇住環境整備課長、岩田管理工事課長","answer":"図面の後ろだったと思いますが、今どのくらい隣地と離れておるかという話がございました。すみませんが、２ページを見ていただけますでしょうか。今回の計画の日照の関係を見ましても、南側部分一部に日影が２時間から３時間程度かかる程度ですので、ここには砂場等。話し合いを住民とやってないじゃないかという今ご意見があったんですが、私どもから見れば４回の説明会ということで。","id":"exchange-022"},{"speaker":"菊地委員","kind":"確認","question":"受忍限度がどこにあるかというのを単純に今説明があったような形で推し測るというのは、非常にとてもおかしな話かなと思うんですけれども、その辺もう少し実際今業者の方は十分住民の皆さんと話をしているというんですけれども、実際にその辺を配慮しない話し合いをしているからこそ、こういう形で請願が上がってくるんじゃないんでしょうか。","respondent":"浜脇住環境整備課長","answer":"区の方はこういうものを見て指導してほしいといいますが、こういうことを私どもが指導できるのは、周辺の環境といいますか、周辺のそういった公共空地でありますとか実際にありますが、そういったものに対しては、もちろん指導要綱に沿って指導していますが、その中の方に配置が。","id":"exchange-023"},{"speaker":"菊地委員","kind":"提案","question":"ただ先ほど東品川３丁目、協定みたいなものを住民の間でつくっていくなんていう話がありますけれども、やっぱり実際にまちづくりをどうしていくかという、住民参加のところでどういう土壌をつくっていくのかというところは、先ほどのご説明だとよくわからない、住民にお任せしますみたいな話で、じゃあ実際にどこがどういうふうにつくり上げていくのかなんていうのは実際には提案されていないわけですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この辺の高層ビルが立ち並んでいる地域の防災面でどういうお考えを持っていらっしゃるのかちょっと聞かせていただきたいと思います。","respondent":"浜脇住環境整備課長、山室住宅指導担当部長","answer":"防災上のどっちかというと避難の関係だと思うんですけれども、そういったものについてはちょっと持ち合わせておりませんが、たしかあそこには天王洲野球場がありますので、そこへ行くと。それで既存のマンション、既に高いマンションも周辺にありますし低いマンションもあるわけですから、いろいろなその容積というものが建てられる地域、かなりある面では事業者も計画が建てやすいといいますか。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"震災なんかであちこちに燃え広まったときなんか、私はすごい高層の建物が多くて、きょう風がなくてよかったですけれどもね、風の流れや何かの災害に対する影響というのも、やはりこの辺も十分研究が必要だと思うんですが、その辺は今後臨海部どんどんふえていきますよね、そういうところにおいてどういう研究がされているのか、どういう街を考えているのかという、その広げたお考えがあるのかどうか。","respondent":"浜脇住環境整備課長","answer":"現在はまずは荏原方面が先に立ったというのが実情です。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"でも、別の面でやっぱり災害に対してすごく心配があるのではないかなという思いがしたんで、今のちょっと質問にもう一度きちっと、そういうことに対して研究がされてないというのは今わかりました。でも今後どう考えていくのか、やはりまちづくりということで、住みよい街をつくっていくという立場でのその辺の問題点を今後どう考えているのかお聞かせいただきたいんですけど。","respondent":"伊佐都市計画課長","answer":"それこそ荏原地域の木造密集とかというのがどんどん出まして、だから避難の面では、今申しましたように割と近くにこうした避難場所があるということですので、防災面からはいろいろ地域の方のご意見ありますけれども、行政としては、ほかの地域と比較しますと。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問","question":"今のところは地域的に容量として大丈夫ということなんですけど、やっぱり住民の方はまちづくりというところで今の時点だけじゃないですよ、今度あの街がどうなっていくのかというところで現時点をとらえていらっしゃると思うんで、今だったら大丈夫というところじゃなくて、その辺の見通しを持っていくのがまちづくりだと思うんで、やはり住民の方に安心して住んでいただくためには。","respondent":"山室住宅指導担当部長","answer":"よく風対策については、ご案内のとおり、高い建物をつくるわけですが、基本的なその風対策というのは、樹木等の育成をもって緩和をしていくと。一年のうちに何回かある強い風等の対応については、そういったことで緩和をしているというのが現状です。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"今回、東品川３丁目の方々からのこういうご要望が出ておるわけですが、３丁目の方々、民間の方々が、東京電力、こちらの請願書の方には「公共的独占企業」というふうに書いてありますが、株式会社でもありますし、その電力供給の観点では公共性が高い会社なんですが、その子会社、関連会社が建築主となっているわけですので、そういう意味では、不動産業務と考えれば完全な民営・民間の法人だと、ですから。","respondent":"浜脇住環境整備課長","answer":"とにかくこれはそういう建築紛争自身がこういう流れになってございまして、そういった基準法との問題と私どもがやっている条例との若干の乖離があるというのが事実でございまして、こうなってしまいますと、区の方は建築紛争予防条例上での介入にはなりますけれども。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっとここから仮定の話になってしまうんですけれども、そのあっせんする過程で、段階でのその想定の話なんですが、例えばこの合意を生かすと仮にしたならば、その建築主、東電不動産管理株式会社としても、民間ですので、ある一定の採算ということを想定した１０６戸という計画なんだろうと思われるんですが、ただ一方、その住民の方々のご要望を反映するということで。","respondent":"浜脇住環境整備課長","answer":"ですから、そこまではこの建築紛争予防条例の中ではやれないんだというのが一貫した考えです。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"もう一つ想定の話をしたいんですが、こういう今回の場所だけではないんですが、品川区内同様のお話というのは多々私も耳にしておりますが、大体請願をされる方は既存の住民の方々で、新たに建設するものに対してのいろいろなさまざまなご要望を出しておられるんですが、要は後から建てる方のその建築物に対して制限をしようという、しなさいという、してほしいというご要望なんですが。","respondent":"浜脇住環境整備課長","answer":"あるいは周辺を１２ｍ以上離そうというようになった場合に、今１０ｍ以上の建物は幾つあるかと、そうすると、こういったものは全部建て替えの際には不適格になりますから、土地を貸す人は非常に制限されると、困るという状況ですから。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"ちょっと別で、もう一つ質問なんですが、請願理由の中に、雪印工業跡地のトミンハイムが５階建てでという、その４の最後の方に、「こういった建物をつくろうという動きが自治体からも起きているよい例です」とこちらには書いていらっしゃるんですが、この雪印工業跡地に対して品川区としてそういう何らかの指導なりをされたのかどうかという、ちょっと事実確認だけしたいんですけど。","respondent":"浜脇住環境整備課長","answer":"私も文書がここに乗ってましたので、今うちの職員から聞いた話なんですが、あくまでもこれはこのトミンハイムの方が周辺との環境を考えてといいますか、自分の方で独自でやったというふうに伺っております。","id":"exchange-032"},{"speaker":"堺委員","kind":"質問","question":"それで、お願いしたいことは、請願事項の中にも書いてありますように、４段目の「住環境を考慮し、まちづくりに配慮した建物の建設を希望します」という地域住民の方からの請願の内容を、基本的には建設実施の方も東京電力ですか、東電不動産管理株式会社、ここが設計者ですね、建築主が東電不動産管理株式会社ですか、そちらの方に十分意向は伝わっているのかなとは思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほど質疑の中でも出たんですが、行政としてのできる範囲というのが、どうしてもその一定のところまでしかないという現状の中において、既に４回の話し合いの場を持たれているということなんですが、是非地域の皆様のご要望を十分先方に伝えていただく場をさらに設けていただきたいという思いを含めまして、継続ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"菊地委員","kind":"意見","question":"これは請願事項の中にありますけれども、こういう特別に分かれているような分かれていないような感じですけれども、少なくても近隣マンションへの日照の問題、それから今申し上げました東品川交通公園、これに日影を落としていく、こういう問題についても、この一番の事項についてはきちんと整えていくべきではないかというふうに思いますので、これについてはぜひ採択をしていきたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"船波委員","kind":"質問","question":"ですから、例えば建てたいという側も、それでは困りますという側も、それぞれの思いがあって主張することがあり、それが対立してしまうんだと思いますけれども、品川区としてこうした計画や方針やらですね、その環境に配慮した住環境だとか、そういった理念を掲げている以上、やはりそうしたことが実現されるような少しでも動きをしたいと思いますし、究極的には、その住民の方がどう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"本間委員","kind":"質問","question":"これまでこの種の請願者の代表者と建主側とのやりとりは、既に４回ほど説明会、話し合いが行われてきているというようなことですので、私どもの立場といいますか、意見は、本当に何かあそこの部分だけどんどんどんどん出てきている部分も、驚くべき姿も一方では実感すると同時に、今現在でのできることは、どこまで何ができるかなということで常に置き換えてみますと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"菊地委員","kind":"質問","question":"６０ｍ範囲にかかる件数って、これ実際に何名くらいあるのかは事業者の方から報告はあるんでしょうか、ちょっとそこからまず教えていただければと思います。","respondent":"浜脇住環境整備課長","answer":"申しわけございません。ちょっと件数まで私どもの方は報告を受けてませんので、職員がちょっと今調査いたします。","id":"exchange-038"},{"speaker":"菊地委員","kind":"質問","question":"今件数をお聞きしたのは、請願を出された方にちょっと電話でお聞きをしたんですけれども、第１回目の説明会のときには、たしか説明会をやりますという案内状は入ってたんですけど、全然気がつかなかったと。ポストに封筒に入れて投函をしていったみたいですけれども、実質的に一体何名ぐらいに業者の方で配られて、最初の説明会がたった２名だったのかという。","respondent":"浜脇住環境整備課長","answer":"申しわけございませんが、職員の方もちょっと今報告受けていないという話ですので、何件配布したかというのはちょっとわかっていません。","id":"exchange-039"},{"speaker":"菊地委員","kind":"質問","question":"まあ配布の形式も含めて、何件配布をしたか管理にないというのは、住環境整備課のほうにも、ちょっと私、実際に今みたいなお話もありますが、これまでも同じような住民説明会の告知についての話がありましたけれども、それでは業者の基本的な姿勢をつかむ上で絶対に大事な部分ではないかなと思うんですけれども、現状でつかんでないというのは、そういうシステムは今までなかったんですか。","respondent":"浜脇住環境整備課長","answer":"何件配ったとか配布したということは、報告の中に入ってございません。","id":"exchange-040"},{"speaker":"菊地委員","kind":"確認","question":"ということは、区としては今までも従来もつかむ体制はなかったということになるんですね。区の方も実際に手引きの中にもきちんとそのようなことは書かれているわけですから、それがつかめていないというのは、そもそも、つかめていないというより、つかむ意を住環境整備課が持っていないというのが何とも、その辺の法的義務ですから、当然そのものもちょっとそこら辺の考え方を教えていただけますか。","respondent":"浜脇住環境整備課長","answer":"ですから、１回目に何件配布をしたか、あるいはその説明会というのは、例えば今委員がおっしゃるように重要でありますから、今後はそういう部分について、いつ何時ごろどういう形でという部分をつけ加えて、これからは報告してもらえるように考えてまいります。","id":"exchange-041"},{"speaker":"菊地委員","kind":"質問・要望","question":"ぜひその辺は改善をしていただければと思います。ですから、電話でお聞きしたときも、まだプライバシーの問題ですとか、基本的なことについても事業主からまだ聞いてはいないということでしたから、そこは早急に改善をするような、これは区の問題か業者の問題なのかよくわかりませんけれども、改善すべきだろうなというふうに思いますので、改めてそこは要望しておきます。","respondent":"浜脇住環境整備課長","answer":"第２回ということは、今、業者から見て第２回ですけれども、あるいは住民の方からは説明してやった第２回でいいますと、その中で言わているのは、日照や住環境、プライバシーや階数を８階と、こういったような要望があって、それについてどういうふうにやるかといったところ。","id":"exchange-042"},{"speaker":"菊地委員","kind":"質問","question":"いずれにしても、全体像は、このたった２回の説明会の中では、全くこの業者の方から提起もされずに、住民の方もこれで承認するというところまでいっていないかと思うんですね。ですから、やっぱり説明会、本当に事業主と相対して説明会を持たれるような、この辺は十分区でも指導していける部分なんだと思いますので、これはしっかりとやっていただければなと思います。","respondent":"浜脇住環境整備課長","answer":"今ご意見いただきましたように、２月１７日の日に住民側から建築主の方に説明会を開催してほしいと、ある意味では、通算すれば３回目になるところですが、要望出されておって、今建築主側の方は保留にしていますから開催しないんですね。","id":"exchange-043"},{"speaker":"菊地委員","kind":"質問","question":"１点だけ、聞くのを忘れました。これは建築申請の方はどうなっているんですか。","respondent":"浜脇住環境整備課長","answer":"建築基準法に基づく確認申請は、平成１５年２月７日に申請が行われてあります。それで、まだ確認が終わったということは聞いてございません。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどの東品川の方々と同様なんですが、なかなか行政としてどこまで対応できるのかという制限がある中で、できるところとしては、お互いの住環境をお互いの話し合いの中で、環境のことでご審議いただきたいと考えていますので、そういった意味に立って、ぜひ話し合いの場を設定いただくような、いろいろあっせんといいますか、場の設定の交渉を引き続きしていただきたいという意味で、継続です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"船波委員","kind":"質問","question":"ですから、品川区もこうやって基本方針だとか計画とかに盛り込まれていて、また住民だけでなく、議会としても、この計画に盛り込まれているような景観を守るとか住環境を守ることももちろん目指す立場だと思いますから、こうした目指すものを現実のものとなる制度も保証されていないからこそ、やはりそうしたものを目指したいという気持ち、立場だけはやはり明らかにしたいということで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"堺委員","kind":"質問・要望","question":"私は、先ほどの東品川３丁目と同じで、引き続き、当事者間での話し合いの余地があると思いますから、しっかりまた話し合いを進めていただきたいという希望を持っておりますので、大変かもしれませんが、それのあっせん、橋渡しをしていただいて、ご努力をお願いしたいということを添えて、この件についても継続ということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"菊地委員","kind":"意見","question":"旧街道と、それから第一京浜、間にしているわけですけれども、実際にあそこで生活をされてこられた皆さんが、あれだけ大型の国道に接しているとはいえ、実際に日照被害等なり受けているという街づくりそのもののあり方にきちんと行政として、環境を前提として価値はとらえていく必要があるというふうに思いますけど、そのことから、この請願についても受け入れていきたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"本間委員","kind":"質問","question":"私たち審議をすることが多いのですが、ときどき被疑者から適切なお話も伺ったりしておりますが、今回のこの件も、先ほどの東品川３丁目の件と同様の受けとめで、これからもお互いに建物が建って、そこに住む住民と、それから今までどおりまた住む住民と共存共栄していかなきゃならない、そういう場面もあるわけなんで、できるだけ話し合いによって事が進むように、行政側も大変かもしれませんが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"意見","question":"だから、そういった面では、この昇降機のところにきているんですけれども、やはり地元の方に負担が物すごくかかっているということをまたしっかり受けとめて対応してほしいなと思うのが一点で、どのくらい把握をしていらっしゃるのかなというのが一点と。","respondent":"中島街路事業担当課長","answer":"今後、この事業の延伸については、新たな展開というんですかね、新しい形でまたこれから何年やっていきますということもありますので、そういった部分では、なるべく広範囲な方にご理解いただけるような形でケアできるようなことも検討していきたいと考えております。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひいろいろ対処をしていたり苦情に対してもいろいろなさっていることも含めて、地域の方にお伝えいただきたいなと思います。これは要望というか意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"その仮に３年弱まるまる使えたとしまして、工期がその分遅れるからプラス半年なんでしょうから、仮に使えたとして、じゃあ地下に平成１７年秋にもぐった際には、新たにここで仮駅舎に設置するエレベーターなりの機器類はどういうふうにするのか、処分してしまうのかどうかというのも含めてちょっと教えてください。","respondent":"中島街路事業担当課長","answer":"私ども基本的に、あくまでも仮駅舎につける仮の昇降機という考えを持ってありますので、そこに本格的なものを安くつけられればいいんですけれども、そういう安くつけて、なおかつ安全で工期の影響もないというものがあれば一番いいと思っていますけれども。","id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"そうなると、その代用品というんでしょうかね、何というんでしょうかね、仮駅舎への設置したものを本格的な地下切り替えの際は、それは使えないということで、果たしてそれを別の場所に移したらじゃあ使えるのかということなどもありますが、場合によっては、わかりませんが、これは推測なんですが、勝手なことなんですが、例えば監査の折に審査を受けて十分耐えられるのかどうかって。","respondent":"中島街路事業担当課長","answer":"監査、会計検査等についてのご質問だと思いますけれども、別にこれは４事業者によって取り付けを検討した結果、必要という判断でつけるということになれば、それは工事事業者との説明というのは当然必要ではないかと考えています。","id":"exchange-053"},{"speaker":"堺委員","kind":"質問","question":"この件については、今担当の課長のおっしゃっておられましたように、区としてはある方が望ましいという判断を既にされている、その理由についても何点かお述べになっておられましたし、その点についての２６日の本会議代表質問の中でも、まちづくりの関係ということで私どもも取り上げさせていただきました。したがって、この件については、採択ということで取り扱いをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"田中委員","kind":"質問・要望","question":"総意はエレベーター設置プラス早期完成だと考えていますので、エレベーター設置をすることによって工期が延びるということに対してはなかなか理解は得られないのではないかと考えていますので、工期をもう最小限といいますか、工期を延ばさないというぐらいの前提の設置ならば理解できるのと、設置された機がむだにならないようにということで、費用対効果を十分ご考慮。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"船波委員","kind":"質問","question":"そうしたことが、やはり今のそのバリアフリーとか、ましてやデザインのまちづくりにも理念にかなうことだと思うので、それがもう平成９年現在の状態になって以来、設置されなかったということの方が驚きなくらいなものなので、やはり早く設置してほしいということで、これは採択したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"本間委員","kind":"意見","question":"説明にありましたように、中身はわかりますけれども、今後の事業費の見直しだとか完成時期をどうするかというのが全部係わり合いを持ってくるということなので、平成１７年秋を目標に、それを早めていただくことを中心にしながら、もろもろの検討課題を工夫していっていただければというふうにお願いを付して、趣旨採択。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"田中委員","kind":"意見","question":"区長あての陳情された方々が中心となりまして、たまたま議会あてに今回出ている請願代表者の方あるいは代表者と他に３名の方も区長あて請願者に入っていらっしゃいますが、その方々を含めまして、こういう案内板がいいんじゃないかという部分、具体的につくっていらっしゃいますので、ぜひそれはごらんいただきまして、ぜひそれを踏まえながら、地域の声を踏まえながら、ぜひ東急電鉄。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"田中委員","kind":"意見","question":"そういうことを含めて採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"菊地委員","kind":"質問","question":"今の点で、田中委員の言われた、この請願者の方ですか、この方はもう前回の区長陳情者に入っていらっしゃるというのは私今初めて聞いたんですけれども、請願を出したり陳情出したりというのは個人の自由ですのであれですけれども、実際に前回の陳情を出して、こういうものを設置しますよというのは、区の方から。","respondent":"中島街路事業担当課長","answer":"先ほど私申し上げますたように、案内所の設置は難しいけれども、案内板の設置については、区が関係者、東急電鉄も初めとしてですが、関係者の間のコーディネートをしていきますというようなことでお答えしております。","id":"exchange-060"},{"speaker":"菊地委員","kind":"質問","question":"わかりました。この代表者の方は、そういう設置をする方向ですよみたいな、そういうとらえ方じゃなかったかどうか、その辺は何ともわからないところなんですけれども。何か先日の横山議員の質問の中で、これは案内板の設置を検討する同じ内容なんだというのはわかったんですけれども、ちょっと何かその辺がよくわからなかったもんですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"堺委員","kind":"確認","question":"田中委員と課長の話しを一緒にして、流れだけ確認させてください。それで、お会いになった際に、今課長の方で説明されたようなそういうのはできないけれども、案内板の設置についてのコーディネーターはできますよというお話をその１２月に既にされたというのにもかかわらず、この２月にこの陳情者が今度は請願代表者になられて請願書を出してきたという、そういう流れになるんですか。","respondent":"中島街路事業担当課長","answer":"区長陳情にどなたが来たとかということを私どもの方で言っていいのかどうかというのがあります。ただ、この方たち３名の方は陳情には見えてませんでした。区長と会うときにはこの方たちはいらっしゃいませんでした。","id":"exchange-062"},{"speaker":"堺委員","kind":"確認","question":"全くそのとおりです。流れだけをちょっと確認しようかなと。わかりました、結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"堺委員","kind":"意見","question":"結論を出すということで、これについては私は採択でお願いしたいというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"船波委員","kind":"意見","question":"外壁に設置される掲示板、案内板がどういうものであるかは、ここにいろいろ具体的にアイデアが出ていますけれども、最終的にどういうものになるかは、その今後の動きということもありますけど、やはり設置するという方向で、品川区が関係者と話していくとかいうことはしてほしいと思うので、採択。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"本間委員","kind":"意見","question":"ポイントでいうと２つの項目なんですが、この中身には細かいことがいろいろ書いてありますね。これについても、それぞれ関係者を交えた中での調整を図って、よりよい結果を出していただければというふうに思いますので、一応結論は採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"船波委員","kind":"質問","question":"この陳情を出された方が、このハウス島津山の方は、一体開発としてほしいということを申し入れられていたんだと思いますけれども、それができなかった、その理由がどういうことなのかお伺いしたいと思うんですけど。ほかに何か理由が、説明されなかったものか、お尋ねします。","respondent":"浜脇住環境整備課長","answer":"住民の観点からいえば、一体化した方が、当然北側とか西側の方から見て、一体開発が良い。しかし、これにはやはり業者側としての思いといいますか、いろいろなことがありますから、その辺の条件面でのお互いの検討というのがありました。","id":"exchange-067"},{"speaker":"菊地委員","kind":"質問","question":"ちょっと１点だけ、質問を。どの部分をというか、スロープみたいなあそこを階段にしちゃうということで、奥に昨年だか立ち上がったマンションがありますけれども、実際にはあそこのマンションの人と、今度新しく立ち上がるであろうマンションの人たちが使うことになるんでしょうかね。実際に階段状にしていくことは法律的には何も問題もないということなんでしょうかね、ちょっとそこだけ。","respondent":"浜脇住環境整備課長","answer":"今現在のスロープ自身が最大２１％ぐらいのスロープでありまして、それほど通行がなかったということもございまして、かえって歩行者安全上では歩行者用がいいんじゃないかということで、階段というようなことで申請をされました。","id":"exchange-068"},{"speaker":"船波委員","kind":"質問","question":"品川区には品川としてもいろいろ建築物いろいろ集まってきていると思いますけど、これは余りにも建物と建物が建って日影になる時間帯が長くなってしまうんじゃないかと思いますけど、こうした物件はどうなんでしょうか、よくあることなんでしょうか、それとも何か私なんか拝見していて余りにもひどい状況というふうに思うんですけど、どうなんでしょうか。","respondent":"浜脇住環境整備課長","answer":"商業地域でございまして、そういった意味では規制がなくて、そういうことを法律的には指導できる状況ではなかったということで、少しでもこういう配慮を含めて設計するよう指導しています。","id":"exchange-069"},{"speaker":"船波委員","kind":"質問","question":"目標だけ掲げていってるだけで、今の現状はこうだから仕方がないと言っていたんでは、せっかく掲げた目標に全然近づく様子が見られないというふうになってしまうので、現状仕方がないにしても、やはり掲げた目標に少しでも近づくような何かこうスタンスとか、その後の具体的な問題に関するかかわりとかというのも知らせてほしいと思うんですけど、その辺はどうなんでしょうか。","respondent":"山室住宅指導担当部長","answer":"良好な住環境を目指していくということで、委員のご指摘のとおりなんですが、品川区というその地域特性を生かしたまちづくりをどう考えていくかという中で、基本的にはその都市計画法ないし建築基準法の規制にのっとって我々としてはまちおこしを進めていくわけですが。","id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"でも、この間いろいろなケースが陳情・請願でいっぱい出されていますよね、そうやって出された本当にわらにもすがりたい思いのその声を受けとめて、本当に仕組みをつくっていくのは、仕組みを知る場がなかったり、意見を言う場も知らない住民の方がまだまだ多いので、やっぱり行政がそういう場をつくっていく、意見を言える場を作っていくのがまず努めではないかなと思うんですけど。","respondent":"山室住宅指導担当部長","answer":"先ほど言いましたように、後からここについても、南側が基本的には未来永劫に２階建ての建物というわけではないので、私有地ですので、やはり一定の開発が行われるというのは当然のこととしてあり得るわけですので、そういった中で、住まい方といいますか。","id":"exchange-071"},{"speaker":"菊地委員","kind":"意見","question":"ちょっと１点だけ。今部長のおっしゃられた、実際にああいうところで買う側の問題なんですけれどもね。そこまでもし見越して買える人がいるとすれば、やはり相当そういう知識を持った人でない限りは無理でしょうし、調べることそのものもなかなか不可能な部分が多いと思うんですよね。実際には、そこに手をつけない限り、私は絶対無理なんじゃないのかなという気がしますけれども。","respondent":"山室住宅指導担当部長","answer":"例えば下階といいますか、下の方の価格については、やっぱり住環境がそれなりに周辺の階数によって変化しますと、こういう影響が一番受けやすいわけですから、それなりの価格になっていますよという説明になるわけですね。","id":"exchange-072"},{"speaker":"船波委員","kind":"質問","question":"もちろん例えばこのハウス島津山の方と話し合いがうまく進むように願っているわけですけれども、それにしても、もう３月末ぐらい着工を目指されているということですから、やはり次回審議されるのはもう６月末になってしまうので、継続にしてはこの件に関して意味がない扱いになってしまうので、私としては、その話し合いしかないというところで、話し合いがうまくいってほしいというところは思いますけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"堺委員","kind":"質問","question":"私は、先ほどの２件、第３号と第４号のマンション建設に係る請願と結論的には同じです。中身が先ほどの２件とはちょっと違うので私も悩んでいたんですけれども、うまく当事者間で話し合いが進むようになればいいなと思いますが、ただ一体開発への誘導ですか、こちらが一緒にやってくれるんだったら、向うがいろんな面でできないと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"本間委員","kind":"質問・要望","question":"今回は、もう陳情・請願３件ございましたが、それぞれの置かれた状況は違ってはいますけれども、将来的にも建物ができた暁には、一緒に同じ地域の人々と共存していくようなことに、付き合って住んでいくようなことになっていかなければならないわけですので、ちょっとこの一体化再開発という部分は、相手とのやりとりの部分でどうなるかわかりませんけれども、とにかく引き続きお互いに誠意を引き出して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/296109?Template=document&Id=3746#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2003-01-01&TermEnd=2003-12-31"}],"sourceMeta":{"pages":0,"characters":70280,"voices":214}}]);
